INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94378, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尿", "is_correct": true, "explanation": "尿（niào）：人和动物从体内排出的液体废物。"}, {"text": "鸟", "is_correct": false, "explanation": "鸟（niǎo）与 niào 声调不同（第三声与第四声），意思是鸟类。"}, {"text": "料", "is_correct": false, "explanation": "料（liào）与 niào 声母不同（l 与 n），意思是材料。"}, {"text": "念", "is_correct": false, "explanation": "念（niàn）与 niào 韵母不同（-ian 与 -iao），意思是出声地读。"}, {"text": "笑", "is_correct": false, "explanation": "笑（xiào）与 niào 声母不同（x 与 n），意思是高兴时发出的声音或表情。"}, {"text": "调", "is_correct": false, "explanation": "调（diào）与 niào 声母不同（d 与 n），意思是调整。"}], "explanations": {"尿": "尿（niào）：人和动物从体内排出的液体废物。", "鸟": "鸟（niǎo）与 niào 声调不同（第三声与第四声），意思是鸟类。", "料": "料（liào）与 niào 声母不同（l 与 n），意思是材料。", "念": "念（niàn）与 niào 韵母不同（-ian 与 -iao），意思是出声地读。", "笑": "笑（xiào）与 niào 声母不同（x 与 n），意思是高兴时发出的声音或表情。", "调": "调（diào）与 niào 声母不同（d 与 n），意思是调整。"}, "sentence_index": null, "correct_answer": "尿"}, "level_3": {"options": [{"text": "尿", "is_correct": true, "explanation": "正确：尿是身体排出的液体，能说明身体状况，与“颜色”“身体”搭配。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝进去的东西，不是身体排出的废物，它的颜色不能反映身体好坏。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水来自天空，不是人体的排出物，不能说明身体好不好。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“颜色”不能修饰“味道”，说明身体状况要用排出物的颜色。"}], "explanations": {"尿": "正确：尿是身体排出的液体，能说明身体状况，与“颜色”“身体”搭配。", "饮料": "语义：饮料是喝进去的东西，不是身体排出的废物，它的颜色不能反映身体好坏。", "雨水": "语义：雨水来自天空，不是人体的排出物，不能说明身体好不好。", "味道": "搭配：“颜色”不能修饰“味道”，说明身体状况要用排出物的颜色。"}, "sentence_index": 0, "correct_answer": "尿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听完这个故事，流下了很多尿。", "explanation": "这里应该用〈眼泪〉。眼泪是从眼睛里流出的，尿是泌尿系统排出的废物，不能用“流下”来形容。"}, {"text": "他用一瓶尿画画。", "explanation": "这里应该用〈颜料〉。颜料是用来画画的，尿是身体排出的黄色液体，不能用来画画。"}, {"text": "医生给他开了一瓶尿。", "explanation": "这里应该用〈药〉。药是医生开给病人治病用的，尿不能当药开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94378, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尿", "is_correct": true, "explanation": "尿（niào）：人和动物从体内排出的液体废物。"}, {"text": "叫", "is_correct": false, "explanation": "叫（jiào）与 niào 声母不同（j 与 n），意思是喊、叫唤。"}, {"text": "庙", "is_correct": false, "explanation": "庙（miào）与 niào 声母不同（m 与 n），意思是供奉神佛的地方。"}, {"text": "酿", "is_correct": false, "explanation": "酿（niàng）与 niào 韵母不同（-iang 与 -iao），意思是利用发酵制造酒类。"}], "explanations": {"尿": "尿（niào）：人和动物从体内排出的液体废物。", "叫": "叫（jiào）与 niào 声母不同（j 与 n），意思是喊、叫唤。", "庙": "庙（miào）与 niào 声母不同（m 与 n），意思是供奉神佛的地方。", "酿": "酿（niàng）与 niào 韵母不同（-iang 与 -iao），意思是利用发酵制造酒类。"}, "sentence_index": null, "correct_answer": "尿"}, "level_3": {"options": [{"text": "尿", "is_correct": true, "explanation": "正确：尿里可以含糖，“里”指液体所在的位置，与“有糖”“生病”搭配。"}, {"text": "书", "is_correct": false, "explanation": "语义：书里不会有糖，也与“可能是生病了”没有关系。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气里不会检测出糖，说“有糖”可能生病没有依据。"}, {"text": "脸", "is_correct": false, "explanation": "搭配：“里”要求容器或液体所在的地方，脸不是能装东西的地方，不能说“脸里有糖”。"}], "explanations": {"尿": "正确：尿里可以含糖，“里”指液体所在的位置，与“有糖”“生病”搭配。", "书": "语义：书里不会有糖，也与“可能是生病了”没有关系。", "空气": "语义：空气里不会检测出糖，说“有糖”可能生病没有依据。", "脸": "搭配：“里”要求容器或液体所在的地方，脸不是能装东西的地方，不能说“脸里有糖”。"}, "sentence_index": 6, "correct_answer": "尿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子把杯子里的尿喝光了。", "explanation": "这里应该用〈牛奶〉。尿是身体排出的废物，不能被喝掉。"}, {"text": "孩子写完了尿。", "explanation": "这里应该用〈作业〉。作业是用笔写的，尿是身体排出的液体，不能写。"}, {"text": "孩子把尿当成了玩具。", "explanation": "这里应该用〈玩具〉。玩具是给孩子玩的，尿是身体排出的废物，不能当玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士让他明天早上留一只尿。", "corrected_sentence": "护士让他明天早上留一杯尿。", "error_description": "量词错误：尿是液体，计量时应用〈杯〉，不能用〈只〉。应把“一只尿”改为“一杯尿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "检验室的桌子上放着一条尿。", "corrected_sentence": "检验室的桌子上放着一杯尿。", "error_description": "量词错误：尿是液体，计量时应用〈杯〉，不能用〈条〉。应把“一条尿”改为“一杯尿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4007d5b7-552d-4820-b2db-c1392ba7f764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
