INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "个人所任职、工作的机构或团体。", "primary_collocate": null, "pronunciation": "gōng zuò dān wèi", "ipa": "kʊŋ˥ tswo˥˩ tan˥ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "办银行卡要填工作单位的名称。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作单位是一家大医院。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作单位是市图书馆。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作单位要给员工交保险。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司是我爸爸的工作单位。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简历上要写清楚以前的工作单位。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作单位是一所中学。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请签证时，需要工作单位的证明。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟工作单位签了三年的合同。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的工作单位会照顾员工的家庭。", "target_word": "工作单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个工作单位", "label": "量词"}, {"form": "工作單位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人任职所在的机构或团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de77f8f-f932-4d69-8d97-208873924bdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作单位", "is_correct": true, "explanation": "正确：办银行卡要填写的是任职机构的名称，“工作单位”符合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是需要填写的机构名称，“填颜色的名称”说不通。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”不是机构，不能说“填性别的名称”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能与“填……的名称”搭配，句子不通。"}], "explanations": {"工作单位": "正确：办银行卡要填写的是任职机构的名称，“工作单位”符合。", "颜色": "语义：“颜色”不是需要填写的机构名称，“填颜色的名称”说不通。", "性别": "语义：“性别”不是机构，不能说“填性别的名称”。", "体重": "搭配：“体重”不能与“填……的名称”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "工作单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的工作单位是医生。", "explanation": "这里应该用〈职业〉。“工作单位”指任职的机构，说“是医生”时要用职业。"}, {"text": "他的工作单位是经理。", "explanation": "这里应该用〈职务〉。“工作单位”指机构，说“是经理”时要用职务。"}, {"text": "我表哥在一条工作单位上班。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不用来数机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作单位", "is_correct": true, "explanation": "正确：“工作单位”指任职的机构，可以是一所学校。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不是机构，不能说“是一所中学”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”不是机构，不能说“是一所中学”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能作“是……中学”的主语，搭配不通。"}], "explanations": {"工作单位": "正确：“工作单位”指任职的机构，可以是一所学校。", "年龄": "语义：“年龄”不是机构，不能说“是一所中学”。", "性格": "语义：“性格”不是机构，不能说“是一所中学”。", "身高": "搭配：“身高”不能作“是……中学”的主语，搭配不通。"}, "sentence_index": 6, "correct_answer": "工作单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工作单位是学生。", "explanation": "这里应该用〈身份〉。“工作单位”指机构，学生的身份要用身份来说明。"}, {"text": "她的工作单位是会计。", "explanation": "这里应该用〈岗位〉。“工作单位”指机构，说“是会计”时要用岗位。"}, {"text": "他换了一把工作单位。", "explanation": "这里应该用〈个〉。“把”多用于有柄的器具，不用来数机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年进入了一只新的工作单位，待遇比以前好。", "corrected_sentence": "她去年进入了一个新的工作单位，待遇比以前好。", "error_description": "错误：“工作单位”的量词写成了“只”，应为“个”。“只”多用于动物，不用来数机构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些工作单位们都很大，招聘的人也多。", "corrected_sentence": "这些工作单位都很大，招聘的人也多。", "error_description": "错误：“工作单位”后面加了“们”。“们”只用于指人，不能用于机构，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
