INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的组成部分及其相互关系。", "primary_collocate": null, "pronunciation": "gòu zào", "ipa": "koʊ˥˩ tsɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器的构造很简单。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了房子的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的耳朵构造很复杂。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看这个手表的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种汽车的内部构造和别的不同。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里详细讲解了花的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生很了解人体的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的构造很特别。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学了句子的构造。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具的构造让孩子很感兴趣。", "target_word": "构造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "構造", "label": "繁体"}, {"form": "构造图", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物的组成部分及其相互关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f8e7373-3f85-45fd-969d-6624b002f8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，不能用来说机器的组成简单不简单。"}, {"text": "构造", "is_correct": true, "explanation": "正确：“构造”指事物各部分的组成及相互关系，与“机器的……很简单”搭配。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只指人或动物的体形，不用来说机器。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人或动物的性情，机器没有脾气。"}], "explanations": {"味道": "语义：“味道”指气味或滋味，不能用来说机器的组成简单不简单。", "构造": "正确：“构造”指事物各部分的组成及相互关系，与“机器的……很简单”搭配。", "身材": "体貌：“身材”只指人或动物的体形，不用来说机器。", "脾气": "语义：“脾气”指人或动物的性情，机器没有脾气。"}, "sentence_index": 0, "correct_answer": "构造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个蛋糕的构造很香甜，我吃了好几块。", "explanation": "这里应该用〈味道〉。“构造”指事物的组成和相互关系，说食物的滋味要用“味道”。"}, {"text": "他的构造很善良，大家都喜欢他。", "explanation": "这里应该用〈性格〉。“构造”指事物的组成，说人的为人和品质要用“性格”。"}, {"text": "这首歌的构造很响亮，邻居都听见了。", "explanation": "这里应该用〈音量〉。“构造”指各部分怎样组合，说声音的大小要用“音量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "搭配：“感情”指人的情绪，不能用来说人体的组成。"}, {"text": "作风", "is_correct": false, "explanation": "语义：“作风”指人的做事方式，与人体的组成无关。"}, {"text": "构造", "is_correct": true, "explanation": "正确：“构造”指人体各部分的组成及相互关系，与“医生很了解人体的……”搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是人体的组成或结构，句意不通。"}], "explanations": {"感情": "搭配：“感情”指人的情绪，不能用来说人体的组成。", "作风": "语义：“作风”指人的做事方式，与人体的组成无关。", "构造": "正确：“构造”指人体各部分的组成及相互关系，与“医生很了解人体的……”搭配。", "时间": "语义：“时间”不是人体的组成或结构，句意不通。"}, "sentence_index": 6, "correct_answer": "构造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个玩具的一条构造很特别，孩子很感兴趣。", "explanation": "这里应该用〈种〉。“构造”是抽象名词，量词用“种”；“条”用于细长的东西，不能修饰“构造”。"}, {"text": "这个玩具的一把构造很复杂，我一直没看懂。", "explanation": "这里应该用〈种〉。“把”多用于有柄或能握住的东西，不能修饰“构造”。"}, {"text": "这个玩具的一首构造很有趣，大家都想试试。", "explanation": "这里应该用〈种〉。“首”用于诗歌、歌曲，不能修饰“构造”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个积木的的构造很简单。", "corrected_sentence": "这个积木的构造很简单。", "error_description": "多余的“的”：定语“积木”后只用一个“的”，应说“积木的构造”，不能说“积木的的构造”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥有一只很特别的构造。", "corrected_sentence": "这座桥有一种很特别的构造。", "error_description": "量词错误：“构造”是抽象名词，应该用“种”，不能用“只”；“只”用于动物或单个的东西，不能修饰“构造”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分", "is_correct": true, "explanation": "分：与“混”意思相反，指把合在一起的东西分开。"}, {"text": "吃", "is_correct": false, "explanation": "吃：动词，指把食物咽下去，与“混”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑：动词，指快速移动，与“混”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：动词，指用笔记录文字，与“混”没有反义关系。"}], "correct_answer": "分", "explanations": {"分": "分：与“混”意思相反，指把合在一起的东西分开。", "吃": "吃：动词，指把食物咽下去，与“混”没有反义关系。", "跑": "跑：动词，指快速移动，与“混”没有反义关系。", "写": "写：动词，指用笔记录文字，与“混”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分", "is_correct": true, "explanation": "分：与“混”意思相反，指把合在一起的东西分开。"}, {"text": "唱", "is_correct": false, "explanation": "唱：动词，指发出歌声，与“混”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走：动词，指移动脚步，与“混”没有反义关系。"}, {"text": "想", "is_correct": false, "explanation": "想：动词，指在头脑中思考或怀念，与“混”没有反义关系。"}], "correct_answer": "分", "explanations": {"分": "分：与“混”意思相反，指把合在一起的东西分开。", "唱": "唱：动词，指发出歌声，与“混”没有反义关系。", "走": "走：动词，指移动脚步，与“混”没有反义关系。", "想": "想：动词，指在头脑中思考或怀念，与“混”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "混是把几样东西放在一起搅一搅。", "primary_collocate": null, "pronunciation": "hùn", "ipa": "xwən˥˩", "syllable_count": 1, "sentences": [{"text": "把水和糖混在一起，搅一搅。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把红色和黄色混了一下，变成了橙色。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面粉和水要先混好，再放盐。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油和水混不到一起。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两种米混一混。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把牛奶和鸡蛋混着放进碗里。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把颜料混一混，再画在纸上。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几种茶叶混在一起泡。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把沙子和水混在一起，搅成了泥。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把牛奶和咖啡混在一起，慢慢搅匀。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混合", "label": "复合"}, {"form": "混一混", "label": "重叠"}], "register": "口语", "sense_fingerprint": "混：动词，把几种东西放在一起搅拌，使它们合在一起，如把水和糖混在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de77f8f-f932-4d69-8d97-208873924bdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "混", "is_correct": true, "explanation": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。"}, {"text": "恨", "is_correct": false, "explanation": "恨 hèn 与 混 hùn 只有韵母不同（en 与 un），声调都是第四声，意思是怨恨。"}, {"text": "困", "is_correct": false, "explanation": "困 kùn 与 混 hùn 只有声母不同（k 与 h），声调都是第四声，意思是疲倦、被困住。"}, {"text": "讯", "is_correct": false, "explanation": "讯 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是消息。"}], "explanations": {"混": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。", "恨": "恨 hèn 与 混 hùn 只有韵母不同（en 与 un），声调都是第四声，意思是怨恨。", "困": "困 kùn 与 混 hùn 只有声母不同（k 与 h），声调都是第四声，意思是疲倦、被困住。", "讯": "讯 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是消息。"}, "sentence_index": null, "correct_answer": "混"}, "level_3": {"options": [{"text": "混", "is_correct": true, "explanation": "混：动词，把几样东西放在一起搅拌，使它们合在一起。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”是分开，与后句“在一起”相矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”只用于清洗，不能说把水和糖“洗在一起”。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指切割，不能说把水和糖“切在一起”。"}], "explanations": {"混": "混：动词，把几样东西放在一起搅拌，使它们合在一起。", "分": "语义：“分”是分开，与后句“在一起”相矛盾。", "洗": "搭配：“洗”只用于清洗，不能说把水和糖“洗在一起”。", "切": "搭配：“切”指切割，不能说把水和糖“切在一起”。"}, "sentence_index": 0, "correct_answer": "混"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把书按大小混在一起，整整齐齐的。", "explanation": "这里应该用〈放〉。“混”指搀合在一起、分不清，与“按大小”“整整齐齐”的意思矛盾；把东西按次序放在一起要用“放”。"}, {"text": "把碎片混在一起，就成了一幅完整的画。", "explanation": "这里应该用〈拼〉。“混”不表示把碎片按位置组合，要把碎片组成完整的画应该用“拼”。"}, {"text": "两家公司混在一起，成了一家大公司。", "explanation": "这里应该用〈合〉。“混”指搀杂、不分彼此，两家公司合并成一家应该用“合”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "混", "is_correct": true, "explanation": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。"}, {"text": "魂", "is_correct": false, "explanation": "魂 hún 与 混 hùn 只有声调不同（第二声与第四声），意思是灵魂。"}, {"text": "婚", "is_correct": false, "explanation": "婚 hūn 与 混 hùn 只有声调不同（第一声与第四声），意思是婚姻。"}, {"text": "训", "is_correct": false, "explanation": "训 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是训练、教导。"}], "explanations": {"混": "混 hùn：动词，把几样东西放在一起搅拌，使它们合在一起。", "魂": "魂 hún 与 混 hùn 只有声调不同（第二声与第四声），意思是灵魂。", "婚": "婚 hūn 与 混 hùn 只有声调不同（第一声与第四声），意思是婚姻。", "训": "训 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是训练、教导。"}, "sentence_index": null, "correct_answer": "混"}, "level_3": {"options": [{"text": "混", "is_correct": true, "explanation": "混：动词，把几种颜料搅在一起，使它们合在一起。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”是剪断、剪开，不能用于处理颜料。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是擦拭，与调和颜料的意思不同。"}, {"text": "削", "is_correct": false, "explanation": "搭配：“削”指削去表层，颜料不能被削。"}], "explanations": {"混": "混：动词，把几种颜料搅在一起，使它们合在一起。", "剪": "搭配：“剪”是剪断、剪开，不能用于处理颜料。", "擦": "语义：“擦”是擦拭，与调和颜料的意思不同。", "削": "搭配：“削”指削去表层，颜料不能被削。"}, "sentence_index": 6, "correct_answer": "混"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "把苹果和香蕉混在一起，一个个摆成了整齐的队伍。", "explanation": "这里应该用〈排〉。“混”指搀合在一起、分不清，与“一个个摆成整齐的队伍”矛盾；按次序放置要用“排”。"}, {"text": "两块布混在一起，就成了一件衣服。", "explanation": "这里应该用〈缝〉。“混”指搀合，不表示把两块东西连接成整体；要把布连在一起应该用“缝”。"}, {"text": "把红豆和绿豆混开，各自装在两个碗里。", "explanation": "这里应该用〈分〉。“混”是搀合，与“混开”“各自装”的分离意思矛盾；把东西分开要用“分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把面粉和水混很匀，再放一点盐。", "corrected_sentence": "把面粉和水混得很匀，再放一点盐。", "error_description": "错误形式：“混很匀”；正确形式：“混得很匀”。动词后接程度补语“很匀”时，要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把红色和白色混进一起，就变成了粉色。", "corrected_sentence": "把红色和白色混在一起，就变成了粉色。", "error_description": "错误形式：“混进一起”；正确形式：“混在一起”。“进”表示进入某处，不能与“一起”搭配，表示东西搀合在某处要用“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
