INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94406, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搀杂在一起；蒙骗；随便度日。", "primary_collocate": null, "pronunciation": "hùn", "ipa": "xwən˥˩", "syllable_count": 1, "sentences": [{"text": "小偷混进人群，一下子不见了。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想混过检查，被老师发现了。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在家混日子，什么也不做。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有票，想混进电影院。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这家公司混了三年，没学到什么。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别想混过去，这道题你得自己做。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没复习，还想混过这次考试。", "target_word": "混", "complexity_tier": "T3", "furigana": "tā méi fù xí, hái xiǎng hùn guò zhè cì kǎo shì", "sentence_source": "generated"}, {"text": "好人和坏人混在一起，很难分清。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时在外面混饭吃，很辛苦。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子混在大人中间，想听他们说话。", "target_word": "混", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混杂", "label": "复合"}], "register": "口语", "sense_fingerprint": "混：动词，指搀杂在一起、蒙骗蒙混过去，或随便度日、在外谋生，如混进人群、混日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de77f8f-f932-4d69-8d97-208873924bdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94406, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "混", "is_correct": true, "explanation": "混 hùn：动词，指蒙混、偷偷地混入某处。"}, {"text": "恨", "is_correct": false, "explanation": "恨 hèn 与 混 hùn 只有韵母不同（en 与 un），声调都是第四声，意思是怨恨。"}, {"text": "困", "is_correct": false, "explanation": "困 kùn 与 混 hùn 只有声母不同（k 与 h），声调都是第四声，意思是疲倦、被困住。"}, {"text": "讯", "is_correct": false, "explanation": "讯 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是消息。"}], "explanations": {"混": "混 hùn：动词，指蒙混、偷偷地混入某处。", "恨": "恨 hèn 与 混 hùn 只有韵母不同（en 与 un），声调都是第四声，意思是怨恨。", "困": "困 kùn 与 混 hùn 只有声母不同（k 与 h），声调都是第四声，意思是疲倦、被困住。", "讯": "讯 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是消息。"}, "sentence_index": null, "correct_answer": "混"}, "level_3": {"options": [{"text": "混", "is_correct": true, "explanation": "混：动词，指蒙混、偷偷地混入某处。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷东西，人不能被“扔进”人群，与“小偷”的行为不符。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：“砸”指重重地撞击，不能说人“砸进”人群。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是丢弃，不能用来描述小偷自己进入人群。"}], "explanations": {"混": "混：动词，指蒙混、偷偷地混入某处。", "扔": "语义：“扔”是抛掷东西，人不能被“扔进”人群，与“小偷”的行为不符。", "砸": "搭配：“砸”指重重地撞击，不能说人“砸进”人群。", "丢": "语义：“丢”是丢弃，不能用来描述小偷自己进入人群。"}, "sentence_index": 0, "correct_answer": "混"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他堂堂正正地混进了教室，向老师问好。", "explanation": "这里应该用〈走〉。“混”指偷偷地蒙混进入，与“堂堂正正”“向老师问好”的光明正大矛盾；公开地进入要用“走”。"}, {"text": "他光明正大地混进了办公室，要找经理谈话。", "explanation": "这里应该用〈进〉。“混进”是偷偷蒙混进入，与“光明正大”矛盾；公开地进入只需用“进”。"}, {"text": "他大声喊着，要混进人群里跟大家打招呼。", "explanation": "这里应该用〈挤〉。“混进”是偷偷地混入，与“大声喊着”的公开方式矛盾；正面挤进人群要用“挤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94406, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "混", "is_correct": true, "explanation": "混 hùn：动词，指蒙混、偷偷地混入某处。"}, {"text": "魂", "is_correct": false, "explanation": "魂 hún 与 混 hùn 只有声调不同（第二声与第四声），意思是灵魂。"}, {"text": "婚", "is_correct": false, "explanation": "婚 hūn 与 混 hùn 只有声调不同（第一声与第四声），意思是婚姻。"}, {"text": "训", "is_correct": false, "explanation": "训 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是训练、教导。"}], "explanations": {"混": "混 hùn：动词，指蒙混、偷偷地混入某处。", "魂": "魂 hún 与 混 hùn 只有声调不同（第二声与第四声），意思是灵魂。", "婚": "婚 hūn 与 混 hùn 只有声调不同（第一声与第四声），意思是婚姻。", "训": "训 xùn 与 混 hùn 只有声母不同（x 与 h），声调都是第四声，意思是训练、教导。"}, "sentence_index": null, "correct_answer": "混"}, "level_3": {"options": [{"text": "混", "is_correct": true, "explanation": "混：动词，这里指蒙混过去，勉强应付。"}, {"text": "赢", "is_correct": false, "explanation": "搭配：“赢”表示比赛胜出，不能说“赢过这次考试”。"}, {"text": "碰", "is_correct": false, "explanation": "搭配：“碰”指接触，不能与“过这次考试”搭配。"}, {"text": "学", "is_correct": false, "explanation": "语义：“学过”表示已经学习过，与前句“没复习”相矛盾。"}], "explanations": {"混": "混：动词，这里指蒙混过去，勉强应付。", "赢": "搭配：“赢”表示比赛胜出，不能说“赢过这次考试”。", "碰": "搭配：“碰”指接触，不能与“过这次考试”搭配。", "学": "语义：“学过”表示已经学习过，与前句“没复习”相矛盾。"}, "sentence_index": 6, "correct_answer": "混"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他混上新衣服，去参加聚会。", "explanation": "这里应该用〈穿〉。“混”没有穿衣服的意思，它的搀杂、蒙混、随便度日等意思都不能用于穿衣。"}, {"text": "他把照片混下来，发给了朋友。", "explanation": "这里应该用〈存〉。“混”没有保存的意思，把照片保存下来要用“存”。"}, {"text": "他每天混好书包再上学，很少迟到。", "explanation": "这里应该用〈收〉。“混”没有整理东西的意思，收拾好书包要用“收”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想混人群里，溜进会场看比赛。", "corrected_sentence": "他想混在人群里，溜进会场看比赛。", "error_description": "错误形式：“混人群里”；正确形式：“混在人群里”。“混”表示搀进某处，后面要用介词“在”引出地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在城里混很好，已经买了房子。", "corrected_sentence": "他在城里混得很好，已经买了房子。", "error_description": "错误形式：“混很好”；正确形式：“混得很好”。“混”后面接程度补语时要用“得”连接，不能直接接形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5dec087-9d58-4b59-8b84-3c083aaeae2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
