INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留学是到别的国家去读书。", "primary_collocate": null, "pronunciation": "liú xué", "ipa": "liou˧˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "我打算明年去美国留学。", "target_word": "留学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她高中毕业后去英国留学了。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在日本留学三年，日语说得很好。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥想去国外留学，所以每天学英语。", "target_word": "留学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去外国留学需要准备很多钱。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我姐姐留学回来以后，在一家公司工作。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爸爸妈妈不同意他一个人出国留学。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了留学，他每天都在认真准备考试。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李拿到了奖学金，可以去德国留学。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "留学的第一年，她很想家。", "target_word": "留学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "留學", "label": "繁体"}, {"form": "留学生", "label": "复合"}], "register": "中性", "sense_fingerprint": "离开自己的国家，到别的国家去读书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f8e7373-3f85-45fd-969d-6624b002f8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体状况，不能作为“去美国”的目的。"}, {"text": "留学", "is_correct": true, "explanation": "正确：“留学”指到别的国家去读书，与“我打算明年去美国……”搭配。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”是情绪，不能作为“去美国”的目的。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，不能作为“去美国”的目的。"}], "explanations": {"生病": "语义：“生病”是身体状况，不能作为“去美国”的目的。", "留学": "正确：“留学”指到别的国家去读书，与“我打算明年去美国……”搭配。", "生气": "语义：“生气”是情绪，不能作为“去美国”的目的。", "发烧": "语义：“发烧”是身体状况，不能作为“去美国”的目的。"}, "sentence_index": 0, "correct_answer": "留学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去医院留学，医生给我看了病。", "explanation": "这里应该用〈看病〉。“留学”指到外国读书，去医院就诊要用〈看病〉。"}, {"text": "他下周去上海留学，要开三天会。", "explanation": "这里应该用〈出差〉。“留学”指去外国读书，去国内城市开会要用〈出差〉。"}, {"text": "我暑假去北京留学，看望奶奶。", "explanation": "这里应该用〈探亲〉。“留学”指去外国读书，去国内看望亲人要用〈探亲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是出国的目的，句意不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是情绪表现，不能说一个人出国哭。"}, {"text": "留学", "is_correct": true, "explanation": "正确：“留学”指到别的国家去读书，与“他爸爸妈妈不同意他一个人出国……”搭配。"}, {"text": "长胖", "is_correct": false, "explanation": "体貌：“长胖”说身体变胖，不说出国的行为。"}], "explanations": {"睡觉": "语义：“睡觉”不是出国的目的，句意不通。", "哭": "语义：“哭”是情绪表现，不能说一个人出国哭。", "留学": "正确：“留学”指到别的国家去读书，与“他爸爸妈妈不同意他一个人出国……”搭配。", "长胖": "体貌：“长胖”说身体变胖，不说出国的行为。"}, "sentence_index": 6, "correct_answer": "留学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸每天去公司留学，很辛苦。", "explanation": "这里应该用〈上班〉。“留学”指到外国读书，在公司工作要用〈上班〉。"}, {"text": "周末我们去博物馆留学，看了很多展品。", "explanation": "这里应该用〈参观〉。“留学”指到外国读书，去博物馆看展要用〈参观〉。"}, {"text": "我暑假在上海留学，学到了很多东西。", "explanation": "这里应该用〈进修〉。“留学”指到外国读书，在国内学校短期进修要用〈进修〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在德国留学着两年。", "corrected_sentence": "她在德国留学两年。", "error_description": "“留学”后加了“着”：“留学着”不是自然的说法，应去掉“着”，说“在德国留学两年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我英国留学一年。", "corrected_sentence": "我在英国留学一年。", "error_description": "漏字错误：表示地点的“在英国”前缺少介词“在”，应说“在英国留学”，不能说“英国留学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
