INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94413, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "稳是东西放得牢，不会倒，不会晃。", "primary_collocate": null, "pronunciation": "wěn", "ipa": "wən˨˩˦", "syllable_count": 1, "sentences": [{"text": "这张桌子很稳。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他站在梯子上，站得很稳。", "target_word": "稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "椅子腿不一样长，坐上去不稳。", "target_word": "稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆自行车骑起来很稳。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小船在水里晃，我站不稳。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "把花瓶放稳，别让它倒了。", "target_word": "稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地面不平，桌子放得不稳。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山路很滑，爸爸走得很稳。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汽车开得很稳，我在车上睡着了。", "target_word": "稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请坐稳，车马上就要开了。", "target_word": "稳", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "稳稳", "label": "重叠"}, {"form": "稳当", "label": "复合"}, {"form": "穩", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容词：物体放得牢，不倒不晃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94413, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "稳", "is_correct": true, "explanation": "稳（wěn，第三声）：东西放得牢，不倒不晃。"}, {"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wěn（第三声）声调不同，意思是文字。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wěn（第三声）声调不同，意思是询问。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 wěn 韵母不同（an/en），意思是碗。"}], "explanations": {"稳": "稳（wěn，第三声）：东西放得牢，不倒不晃。", "文": "wén（第二声）与 wěn（第三声）声调不同，意思是文字。", "问": "wèn（第四声）与 wěn（第三声）声调不同，意思是询问。", "碗": "wǎn 与 wěn 韵母不同（an/en），意思是碗。"}, "sentence_index": null, "correct_answer": "稳"}, "level_3": {"options": [{"text": "稳", "is_correct": true, "explanation": "“稳”指桌子放得牢、不晃动，与“很”搭配自然。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”指速度快，不能用来形容桌子。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不说桌子胖。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，不能用来形容桌子。"}], "explanations": {"稳": "“稳”指桌子放得牢、不晃动，与“很”搭配自然。", "快": "语义：“快”指速度快，不能用来形容桌子。", "胖": "体貌：“胖”形容人或动物的体形，不说桌子胖。", "聪明": "语义：“聪明”指人的智力，不能用来形容桌子。"}, "sentence_index": 0, "correct_answer": "稳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身体很稳，每天都跑步。", "explanation": "这里应该用〈结实〉。稳指东西放得牢或站得不摇晃，人的身体强健要用“结实”。"}, {"text": "这碗面很稳，吃起来很香。", "explanation": "这里应该用〈劲道〉。稳指东西放得牢、不晃，或做事可靠；面条有嚼劲、口感好要用“劲道”。"}, {"text": "这块布很稳，摸起来很柔软。", "explanation": "这里应该用〈柔软〉。稳指东西放得牢或不晃动，布料手感软要用“柔软”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94413, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "稳", "is_correct": true, "explanation": "稳（wěn，第三声）：东西放得牢，不倒不晃。"}, {"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wěn（第三声）声调不同，意思是温暖。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn 与 wěn 韵母不同（an/en），意思是晚上。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wěn（第三声）声调不同，意思是闻到或听到。"}], "explanations": {"稳": "稳（wěn，第三声）：东西放得牢，不倒不晃。", "温": "wēn（第一声）与 wěn（第三声）声调不同，意思是温暖。", "晚": "wǎn 与 wěn 韵母不同（an/en），意思是晚上。", "闻": "wén（第二声）与 wěn（第三声）声调不同，意思是闻到或听到。"}, "sentence_index": null, "correct_answer": "稳"}, "level_3": {"options": [{"text": "稳", "is_correct": true, "explanation": "“稳”指放得牢、不晃动，与“地面不平”形成合理的因果。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能用来描述桌子放置的状态。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容心情，不能用来描述桌子放置的状态。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人的体形，不能用来形容放置的状态。"}], "explanations": {"稳": "“稳”指放得牢、不晃动，与“地面不平”形成合理的因果。", "甜": "语义：“甜”指味道，不能用来描述桌子放置的状态。", "高兴": "语义：“高兴”形容心情，不能用来描述桌子放置的状态。", "瘦": "体貌：“瘦”形容人的体形，不能用来形容放置的状态。"}, "sentence_index": 6, "correct_answer": "稳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里很稳，同学们都在认真听课。", "explanation": "这里应该用〈安静〉。教室没有声音要用“安静”，“稳”不用来形容环境的寂静。"}, {"text": "今天的气温很稳，大家都穿了外套。", "explanation": "这里应该用〈稳定〉。气温的持续变化小要用“稳定”；“稳”偏重于物体放得牢或站得不摇晃。"}, {"text": "这根绳子很稳，一拉就断。", "explanation": "这里应该用〈牢固〉。稳指东西放得牢、不晃，与“一拉就断”矛盾；绳子结实、不易断要用“牢固”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子终于坐了稳。", "corrected_sentence": "孩子终于坐稳了。", "error_description": "错误形式：“了”放在动词和结果补语之间。正确形式：“坐稳了”，结果补语“稳”紧跟动词，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子坐得没稳。", "corrected_sentence": "这把椅子坐得不稳。", "error_description": "错误形式：“坐得没稳”，补语前的否定词用了“没”。正确形式：“坐得不稳”，补语的否定要用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
