INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94414, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "稳当，不摇晃；可靠。", "primary_collocate": null, "pronunciation": "wěn", "ipa": "wən˨˩˦", "syllable_count": 1, "sentences": [{"text": "他做事很稳，大家都放心。", "target_word": "稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手很稳，不会抖。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥修得很稳，大家都敢走。", "target_word": "稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个司机开车很稳。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的老板做生意很稳，从不冒进。", "target_word": "稳", "complexity_tier": "T3", "furigana": "zhè jiā diàn de lǎobǎn zuò shēngyi hěn wěn, cóng bù màojìn。", "sentence_source": "generated"}, {"text": "她办事又稳又快。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他年纪不大，但是说话办事都很稳。", "target_word": "稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走路要走稳，一步一步来。", "target_word": "稳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生的手很稳，手术做得很好。", "target_word": "稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人很稳，把事情交给他不会错。", "target_word": "稳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稳稳", "label": "重叠"}, {"form": "稳当", "label": "复合"}, {"form": "穩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：稳当不摇晃，做事可靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94414, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "稳", "is_correct": true, "explanation": "稳（wěn，第三声）：稳当，不摇晃；可靠。"}, {"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wěn（第三声）声调不同，意思是温暖。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn 与 wěn 韵母不同（an/en），意思是晚上。"}, {"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wěn（第三声）声调不同，意思是文字。"}], "explanations": {"稳": "稳（wěn，第三声）：稳当，不摇晃；可靠。", "温": "wēn（第一声）与 wěn（第三声）声调不同，意思是温暖。", "晚": "wǎn 与 wěn 韵母不同（an/en），意思是晚上。", "文": "wén（第二声）与 wěn（第三声）声调不同，意思是文字。"}, "sentence_index": null, "correct_answer": "稳"}, "level_3": {"options": [{"text": "稳", "is_correct": true, "explanation": "与“大家都放心”呼应，说明做事稳当可靠。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”指做事粗心，与“大家都放心”相矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容身材或位置，不能用来形容做事的态度。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”指杂乱无章，与“大家都放心”相矛盾。"}], "explanations": {"稳": "与“大家都放心”呼应，说明做事稳当可靠。", "马虎": "语义：“马虎”指做事粗心，与“大家都放心”相矛盾。", "高": "体貌：“高”形容身材或位置，不能用来形容做事的态度。", "乱": "语义：“乱”指杂乱无章，与“大家都放心”相矛盾。"}, "sentence_index": 0, "correct_answer": "稳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子很稳，一拉就断。", "explanation": "这里应该用〈牢固〉。稳指稳当可靠或东西不晃，与“一拉就断”矛盾；绳子结实、不易断要用“牢固”。"}, {"text": "这块布料很稳，穿在身上很精神。", "explanation": "这里应该用〈挺括〉。稳指东西放得牢或做事可靠，布料挺而不软、有型要用“挺括”。"}, {"text": "这壶茶很稳，喝起来很香。", "explanation": "这里应该用〈醇〉。稳指东西放得牢、不摇晃，或做事可靠；茶汤味道浓厚纯正要用“醇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94414, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "稳", "is_correct": true, "explanation": "稳（wěn，第三声）：稳当，不摇晃；可靠。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wěn（第三声）声调不同，意思是询问。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn 与 wěn 韵母不同（an/en），意思是碗。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wěn（第三声）声调不同，意思是闻到或听到。"}], "explanations": {"稳": "稳（wěn，第三声）：稳当，不摇晃；可靠。", "问": "wèn（第四声）与 wěn（第三声）声调不同，意思是询问。", "碗": "wǎn 与 wěn 韵母不同（an/en），意思是碗。", "闻": "wén（第二声）与 wěn（第三声）声调不同，意思是闻到或听到。"}, "sentence_index": null, "correct_answer": "稳"}, "level_3": {"options": [{"text": "稳", "is_correct": true, "explanation": "“但是”引出的转折是年纪不大却办事稳当，“稳”正符合这一语境。"}, {"text": "毛躁", "is_correct": false, "explanation": "语义：“毛躁”指冒失、不沉着，与“但是”后的赞许语气相反。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容身体，不能用来形容说话办事。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：“慌张”指惊慌失措，与“但是”后要表达的可靠相矛盾。"}], "explanations": {"稳": "“但是”引出的转折是年纪不大却办事稳当，“稳”正符合这一语境。", "毛躁": "语义：“毛躁”指冒失、不沉着，与“但是”后的赞许语气相反。", "胖": "体貌：“胖”形容身体，不能用来形容说话办事。", "慌张": "语义：“慌张”指惊慌失措，与“但是”后要表达的可靠相矛盾。"}, "sentence_index": 6, "correct_answer": "稳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双靴子很稳，穿了一天就坏了。", "explanation": "这里应该用〈结实〉。稳指稳当可靠，与“穿了一天就坏了”矛盾；鞋子耐穿要用“结实”。"}, {"text": "图书馆里很稳，大家都在看书。", "explanation": "这里应该用〈安静〉。稳不用来形容环境没有声音，要用“安静”。"}, {"text": "这个女孩长得很稳，很招人喜欢。", "explanation": "这里应该用〈秀气〉。稳指东西放得牢或做事可靠，人的五官清秀、长相文雅要用“秀气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子终于站了稳。", "corrected_sentence": "孩子终于站稳了。", "error_description": "错误形式：“了”放在动词和结果补语之间。正确形式：“稳”是结果补语，应紧跟动词，“了”放在句末，应为“站稳了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈抱着孩子走很稳。", "corrected_sentence": "妈妈抱着孩子走得很稳。", "error_description": "错误形式：程度补语前漏掉“得”。正确形式：“走得很稳”，动词与补语之间要用“得”连接，“走很稳”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
