INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "老到是做事时间长，很有经验，做得很稳。", "primary_collocate": null, "pronunciation": "lǎo dào", "ipa": "lau̯˨˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "他做事很老到，从来不出错。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王干了三十年，处理问题十分老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老司机开车很老到，我们都很放心。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅修机器的手法非常老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厨师炒菜的火候掌握得很老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做生意很老到，一眼就看出问题。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老医生下手老到，病人一点也不怕。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手艺老到，做出来的家具又结实又好看。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民撒网的动作十分老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老木匠干活很老到，从不着急。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事年头久、经验足、手法稳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f23a97a0-1d54-4234-ade3-1bbe96a40f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。"}, {"text": "捞到", "is_correct": false, "explanation": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。"}, {"text": "考到", "is_correct": false, "explanation": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。"}, {"text": "老套", "is_correct": false, "explanation": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d，送气与不送气），意思是陈旧、不新鲜。"}], "explanations": {"老到": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。", "捞到": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。", "考到": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。", "老套": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d，送气与不送气），意思是陈旧、不新鲜。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。做事经验足、手法稳，与后文“从来不出错”相符。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”指做事不仔细，与后文“从来不出错”矛盾。"}, {"text": "马虎", "is_correct": false, "explanation": "语义：“马虎”指做事不认真，与后文“从来不出错”矛盾。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”指做事不熟练，与“从来不出错”相矛盾。"}], "explanations": {"老到": "正确。做事经验足、手法稳，与后文“从来不出错”相符。", "粗心": "语义：“粗心”指做事不仔细，与后文“从来不出错”矛盾。", "马虎": "语义：“马虎”指做事不认真，与后文“从来不出错”矛盾。", "生疏": "语义：“生疏”指做事不熟练，与“从来不出错”相矛盾。"}, "sentence_index": 0, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新打印机很老到，买回来第二天就坏了。", "explanation": "这里应该用〈劣质〉。老到形容人做事的经验和手法，不用来形容刚买的机器；买回来就坏的应说劣质。"}, {"text": "他对这条路一窍不通，却很老到。", "explanation": "这里应该用〈生疏〉。老到形容做事的经验和手法，对某条路一窍不通却说老到，应说生疏。"}, {"text": "这把椅子很老到，靠背都裂了。", "explanation": "这里应该用〈陈旧〉。老到指做事经验足、做得稳，形容家具用旧应说陈旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。"}, {"text": "老大", "is_correct": false, "explanation": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。"}, {"text": "老调", "is_correct": false, "explanation": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。"}, {"text": "咬到", "is_correct": false, "explanation": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}], "explanations": {"老到": "老到 lǎo dào：做事经验丰富、手法稳当，是本词的正确读音和意思。", "老大": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。", "老调": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。", "咬到": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。老医生下手熟练稳当，才会让病人一点也不怕。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：“慌张”说明下手乱，与病人“一点也不怕”的信任感矛盾。"}, {"text": "生硬", "is_correct": false, "explanation": "语义：“生硬”指动作或态度僵硬、不柔和，与病人“一点也不怕”的情形相反，句意不符。"}, {"text": "笨拙", "is_correct": false, "explanation": "语义：“笨拙”与老医生的熟练相反，病人不会因此一点也不怕。"}], "explanations": {"老到": "正确。老医生下手熟练稳当，才会让病人一点也不怕。", "慌张": "语义：“慌张”说明下手乱，与病人“一点也不怕”的信任感矛盾。", "生硬": "语义：“生硬”指动作或态度僵硬、不柔和，与病人“一点也不怕”的情形相反，句意不符。", "笨拙": "语义：“笨拙”与老医生的熟练相反，病人不会因此一点也不怕。"}, "sentence_index": 6, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对新设备毫无经验，却很老到。", "explanation": "这里应该用〈生疏〉。老到要靠多年经验，刚接触新设备的人只能说生疏。"}, {"text": "这把新菜刀很老到，切了几下就卷了刃。", "explanation": "这里应该用〈不耐用〉。老到形容人做事的经验和手法，不用来形容新买的菜刀；切几下就卷刃的应说不耐用。"}, {"text": "这座老宅子很老到，墙上都是裂缝。", "explanation": "这里应该用〈破旧〉。老到指做事经验足、做得稳，形容房屋年头久、残旧应说破旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他修车修很老到，从来不出错。", "corrected_sentence": "他修车修得很老到，从来不出错。", "error_description": "错误在于动词后接形容词作状态补语时漏了“得”。正确说法是“修得很老到”，动词和“很老到”之间要用“得”连接，不能直接写“修很老到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个做事很老到人。", "corrected_sentence": "他是个做事很老到的人。", "error_description": "错误在于“老到”修饰“人”时漏了“的”。正确说法是“做事很老到的人”，形容词作定语后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
