INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容做事经验丰富，周到老练。", "primary_collocate": null, "pronunciation": "lǎo dào", "ipa": "lau̯˨˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "她虽然年轻，待人接物却很老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位律师在法庭上的表现十分老到。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他待人办事很老到，一看就是见过世面的人。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈判时他的回答很老到，对方没占到便宜。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小伙子看起来年轻，办事却老到得很。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李处理家里的矛盾很老到，两边都不得罪。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者提问很老到，一步一步问到了重点。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她招待客人的方式很老到，大家都满意。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板应付检查很老到，从没出过麻烦。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟同事相处很老到，话说得周全，从不得罪人。", "target_word": "老到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "待人处事周到老练", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f23a97a0-1d54-4234-ade3-1bbe96a40f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。"}, {"text": "捞到", "is_correct": false, "explanation": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。"}, {"text": "考到", "is_correct": false, "explanation": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。"}, {"text": "老套", "is_correct": false, "explanation": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d），意思是陈旧、不新鲜。"}], "explanations": {"老到": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。", "捞到": "捞到 lāo dào 的第一音节是第一声，与 lǎo dào 的第三声声调不同，意思是捞取或得到。", "考到": "考到 kǎo dào 的第一音节声母为 k，与 lǎo 的 l 只差一个音位，声调相同，意思是考取、考上。", "老套": "老套 lǎo tào 的第二音节声母与 dào 不同（t 与 d），意思是陈旧、不新鲜。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。“虽然…却…”后面要说出与“年轻”相反的长处，“老到”符合这一转折。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“虽然…却…”要转出与“年轻”相反的长处，“幼稚”顺着“年轻”说，没有转折。"}, {"text": "粗疏", "is_correct": false, "explanation": "语义：“粗疏”是缺点，与“却”要求的转折优点不相符，也与“待人接物”的周到相反。"}, {"text": "冒失", "is_correct": false, "explanation": "语义：“冒失”是缺点，与“却”要求的转折优点不相符。"}], "explanations": {"老到": "正确。“虽然…却…”后面要说出与“年轻”相反的长处，“老到”符合这一转折。", "幼稚": "语义：“虽然…却…”要转出与“年轻”相反的长处，“幼稚”顺着“年轻”说，没有转折。", "粗疏": "语义：“粗疏”是缺点，与“却”要求的转折优点不相符，也与“待人接物”的周到相反。", "冒失": "语义：“冒失”是缺点，与“却”要求的转折优点不相符。"}, "sentence_index": 0, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很老到，有什么想法就直说，不管别人爱不爱听。", "explanation": "这里应该用〈直爽〉。老到指待人周到、说话有分寸，有什么想法就直说的人应说直爽。"}, {"text": "他遇事很老到，从不考虑别人的感受。", "explanation": "这里应该用〈鲁莽〉。老到讲究周全，不考虑别人感受的人应说鲁莽。"}, {"text": "他穿的衣服很老到，都是十几年前的款式。", "explanation": "这里应该用〈老式〉。老到指待人周到、做事老练，形容衣服款式过时应说老式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老到", "is_correct": true, "explanation": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。"}, {"text": "老大", "is_correct": false, "explanation": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。"}, {"text": "老调", "is_correct": false, "explanation": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。"}, {"text": "咬到", "is_correct": false, "explanation": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}], "explanations": {"老到": "老到 lǎo dào：待人处事周到老练，是本词的正确读音和意思。", "老大": "老大 lǎo dà 与 lǎo dào 的第二音节韵母少了一个 o，意思是排行第一或首领。", "老调": "老调 lǎo diào 的第二音节比 dào 多一个介音 i，意思是陈旧的论调。", "咬到": "咬到 yǎo dào 的第一音节声母为 y（零声母），与 lǎo 的 l 只差一个音位，声调相同，意思是咬住、咬着。"}, "sentence_index": null, "correct_answer": "老到"}, "level_3": {"options": [{"text": "老到", "is_correct": true, "explanation": "正确。记者提问周密，才会一步一步问到重点。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：“慌张”与“一步一步”的沉稳不符。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”与“一步一步问到了重点”的周密相反。"}, {"text": "乖巧", "is_correct": false, "explanation": "搭配：“乖巧”多形容孩子的举止，不用来说记者提问。"}], "explanations": {"老到": "正确。记者提问周密，才会一步一步问到重点。", "慌张": "语义：“慌张”与“一步一步”的沉稳不符。", "草率": "语义：“草率”与“一步一步问到了重点”的周密相反。", "乖巧": "搭配：“乖巧”多形容孩子的举止，不用来说记者提问。"}, "sentence_index": 6, "correct_answer": "老到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚入行，应付客户很老到，结果把客户都得罪光了。", "explanation": "这里应该用〈莽撞〉。老到指待人周到、处事有分寸，把客户都得罪光的应说莽撞。"}, {"text": "他对新方法很老到，一点都不肯试。", "explanation": "这里应该用〈守旧〉。老到指经验丰富、待人周到老练，不指思想保守、不肯尝试，应说守旧。"}, {"text": "他对新来的同事很老到，见了面连招呼都不打。", "explanation": "这里应该用〈冷淡〉。老到指待人周到，不用来形容对人冷淡、不愿交谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她招待客人招待很老到，大家都满意。", "corrected_sentence": "她招待客人招待得很老到，大家都满意。", "error_description": "错误在于“老到”作补语时漏了“得”。正确说法是“招待得很老到”，动词后接形容词补语时要用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是个应付场面很老到人。", "corrected_sentence": "她是个应付场面很老到的人。", "error_description": "错误在于“老到”修饰“人”时漏了“的”。正确说法是“应付场面很老到的人”，形容词作定语后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
