INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "临是快要到了某个时间或动作的时候，表示事情即将发生。", "primary_collocate": null, "pronunciation": "lín", "ipa": "lin˧˥", "syllable_count": 1, "sentences": [{"text": "临走前，他给我打了电话。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "临睡前不要喝咖啡。", "target_word": "临", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "临出门的时候，下起了大雨。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "临考试前，她还在认真复习。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他临上车才发现没带钱包。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "临下班的时候，老板给了我一个新任务。", "target_word": "临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临开会前，我才想起要带电脑。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈临出发前检查了一下行李。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他临毕业时，找到了工作。", "target_word": "临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我总是临睡前才想起来关灯。", "target_word": "临", "complexity_tier": "T3", "furigana": "wǒ zǒng shì lín shuì qián cái xiǎng qǐ lái guān dēng", "sentence_source": "generated"}], "morphological_forms": [{"form": "臨", "label": "繁体"}, {"form": "临近", "label": "复合"}, {"form": "临时", "label": "复合"}], "register": "中性", "sense_fingerprint": "放在动作前，表示事情快要发生的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f8e7373-3f85-45fd-969d-6624b002f8e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案，表示快要到了或到了跟前。"}, {"text": "您", "is_correct": false, "explanation": "声母 n 与 l 不同（nín 与 lín），意思是您（敬称）。"}, {"text": "零", "is_correct": false, "explanation": "韵母 -ing 与 -in 不同，意思是零。"}, {"text": "拎", "is_correct": false, "explanation": "声调不同（līn 第一声与 lín 第二声），意思是用手提。"}], "explanations": {"临": "正确答案，表示快要到了或到了跟前。", "您": "声母 n 与 l 不同（nín 与 lín），意思是您（敬称）。", "零": "韵母 -ing 与 -in 不同，意思是零。", "拎": "声调不同（līn 第一声与 lín 第二声），意思是用手提。"}, "sentence_index": null, "correct_answer": "临"}, "level_3": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案。“临走前”表示快要走的时候，符合句意。"}, {"text": "靠", "is_correct": false, "explanation": "语义：“靠”表示靠近或依靠，不能表示事情快要发生。"}, {"text": "随", "is_correct": false, "explanation": "语义：“随”表示跟随，与快要发生的时间无关。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”指站立，不能与“走前”搭配。"}], "explanations": {"临": "正确答案。“临走前”表示快要走的时候，符合句意。", "靠": "语义：“靠”表示靠近或依靠，不能表示事情快要发生。", "随": "语义：“随”表示跟随，与快要发生的时间无关。", "站": "搭配：“站”指站立，不能与“走前”搭配。"}, "sentence_index": 0, "correct_answer": "临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他临上周才告诉我这件事。", "explanation": "这里应该用〈直到〉。“临”表示快要发生，不能指已经过去的时间，应说“直到上周”。"}, {"text": "我们临吃饭以后才想起没买菜。", "explanation": "这里应该用〈饭后〉。“临”表示快要发生，不能指已经发生的事，饭后才想起要用“饭后”。"}, {"text": "临走之后，他才想起忘了带钥匙。", "explanation": "这里应该用〈之前〉。“临”表示快要发生，不能与“之后”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案，表示快要到了或到了跟前。"}, {"text": "蓝", "is_correct": false, "explanation": "韵母 -an 与 -in 不同（lán 与 lín），意思是蓝色。"}, {"text": "凌", "is_correct": false, "explanation": "韵母 -ing 与 -in 不同，意思是凌（欺压、升高）。"}, {"text": "离", "is_correct": false, "explanation": "韵尾 n 不同（lí 与 lín），意思是离开。"}], "explanations": {"临": "正确答案，表示快要到了或到了跟前。", "蓝": "韵母 -an 与 -in 不同（lán 与 lín），意思是蓝色。", "凌": "韵母 -ing 与 -in 不同，意思是凌（欺压、升高）。", "离": "韵尾 n 不同（lí 与 lín），意思是离开。"}, "sentence_index": null, "correct_answer": "临"}, "level_3": {"options": [{"text": "临", "is_correct": true, "explanation": "正确答案。“临开会前”表示快要开会的时候，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”是进食，不能与“开会前”搭配。"}, {"text": "绕", "is_correct": false, "explanation": "搭配：“绕”表示环绕，不能用来说“开会前”。"}, {"text": "登", "is_correct": false, "explanation": "搭配：“登”表示登上或登记，不能与“开会前”搭配。"}], "explanations": {"临": "正确答案。“临开会前”表示快要开会的时候，符合句意。", "吃": "搭配：“吃”是进食，不能与“开会前”搭配。", "绕": "搭配：“绕”表示环绕，不能用来说“开会前”。", "登": "搭配：“登”表示登上或登记，不能与“开会前”搭配。"}, "sentence_index": 6, "correct_answer": "临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他临去年就离开了这座城市。", "explanation": "这里应该用〈早在〉。“临”表示快要发生，不能指已经过去的时间，应说“早在去年”。"}, {"text": "我们昨天临放学后，老师表扬了我。", "explanation": "这里应该用〈放学后〉。“临”表示快要发生，不能与“后”搭配，应说“放学后”。"}, {"text": "妈妈临下班之后，才想起要买菜。", "explanation": "这里应该用〈下班后〉。“临”表示快要发生，不能用于已经发生的事，下班以后要用“下班后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他临下班后给我发了消息。", "corrected_sentence": "他临下班前给我发了消息。", "error_description": "“临”表示快要发生，后面应接“前”，说“临下班前”。“临下班后”表示已经下班以后，与“临”的意思矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她临开会后才把报告发给我。", "corrected_sentence": "她临开会前才把报告发给我。", "error_description": "“临”表示快要发生，后面应接“前”，说“临开会前”。“临开会后”表示已经开完会以后，与“临”的意思矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4367a99f-14c5-4450-86c0-00474c69ff77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甜", "is_correct": true, "explanation": "正确：「甜」指像糖或蜜的味道，与「苦」相对。"}, {"text": "酸", "is_correct": false, "explanation": "「酸」是另一种味道，与「苦」并列，不是反义关系。"}, {"text": "辣", "is_correct": false, "explanation": "「辣」是另一种味道，与「苦」并列，不是反义关系。"}, {"text": "鲜", "is_correct": false, "explanation": "「鲜」指味道鲜美，与「苦」没有反义关系。"}], "correct_answer": "甜", "explanations": {"甜": "正确：「甜」指像糖或蜜的味道，与「苦」相对。", "酸": "「酸」是另一种味道，与「苦」并列，不是反义关系。", "辣": "「辣」是另一种味道，与「苦」并列，不是反义关系。", "鲜": "「鲜」指味道鲜美，与「苦」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甜", "is_correct": true, "explanation": "正确：「甜」指像糖或蜜的味道，与「苦」相对。"}, {"text": "淡", "is_correct": false, "explanation": "「淡」指味道轻、不浓，与「苦」没有反义关系。"}, {"text": "烫", "is_correct": false, "explanation": "「烫」指温度高，与「苦」没有反义关系。"}, {"text": "香", "is_correct": false, "explanation": "「香」指气味好，与「苦」没有反义关系。"}], "correct_answer": "甜", "explanations": {"甜": "正确：「甜」指像糖或蜜的味道，与「苦」相对。", "淡": "「淡」指味道轻、不浓，与「苦」没有反义关系。", "烫": "「烫」指温度高，与「苦」没有反义关系。", "香": "「香」指气味好，与「苦」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "苦是吃起来不甜，让人不想吃的味道。", "primary_collocate": null, "pronunciation": "kǔ", "ipa": "kʰu˨˩˦", "syllable_count": 1, "sentences": [{"text": "这杯咖啡没放糖，喝起来很苦。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药很苦，孩子不肯吃。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝了一口没放糖的茶，说太苦了。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢苦的东西，只爱吃甜的。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑巧克力不甜，吃起来有点苦。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中药又黑又苦，我每次都喝不下去。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶泡得太久，味道变苦了。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个橙子的皮很苦，不能吃。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯茶苦得他直摇头。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药太苦了，妈妈给我一块糖。", "target_word": "苦", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "苦味", "label": "复合"}, {"form": "苦瓜", "label": "复合"}], "register": "中性", "sense_fingerprint": "味道不甜，不好吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119b896a-7a6c-482d-97ff-7470b8956fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。"}, {"text": "哭", "is_correct": false, "explanation": "声调不同：「哭」读 kū（第一声），「苦」读 kǔ（第三声），意思是哭泣。"}, {"text": "库", "is_correct": false, "explanation": "声调不同：「库」读 kù（第四声），「苦」读 kǔ（第三声），意思是仓库。"}, {"text": "古", "is_correct": false, "explanation": "声母不同：「古」读 gǔ，声母是 g，「苦」的声母是 k，意思是古老。"}, {"text": "努", "is_correct": false, "explanation": "声母不同：「努」读 nǔ，声母是 n，「苦」的声母是 k，意思是努力。"}], "explanations": {"苦": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。", "哭": "声调不同：「哭」读 kū（第一声），「苦」读 kǔ（第三声），意思是哭泣。", "库": "声调不同：「库」读 kù（第四声），「苦」读 kǔ（第三声），意思是仓库。", "古": "声母不同：「古」读 gǔ，声母是 g，「苦」的声母是 k，意思是古老。", "努": "声母不同：「努」读 nǔ，声母是 n，「苦」的声母是 k，意思是努力。"}, "sentence_index": null, "correct_answer": "苦"}, "level_3": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：咖啡没放糖，喝起来「很苦」，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：咖啡「没放糖」，不可能很甜，与句中条件相矛盾。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：「咸」指盐的味道，咖啡一般不说很咸。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：「硬」形容质地，不能用来形容饮品的味道。"}], "explanations": {"苦": "正确：咖啡没放糖，喝起来「很苦」，符合句意。", "甜": "语义：咖啡「没放糖」，不可能很甜，与句中条件相矛盾。", "咸": "搭配：「咸」指盐的味道，咖啡一般不说很咸。", "硬": "搭配：「硬」形容质地，不能用来形容饮品的味道。"}, "sentence_index": 0, "correct_answer": "苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个程序很苦，运行起来总是很慢。", "explanation": "这里应该用〈慢〉。苦是味觉，程序的运行速度要说慢，不说苦。"}, {"text": "这块布摸起来很苦，穿着不舒服。", "explanation": "这里应该用〈粗糙〉。苦是味觉，布料的触感要用粗糙，不说苦。"}, {"text": "这首歌的声音很苦，我不太喜欢。", "explanation": "这里应该用〈低沉〉。苦是味觉，声音的音色不能说苦，要说低沉或沙哑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。"}, {"text": "酷", "is_correct": false, "explanation": "声调不同：「酷」读 kù（第四声），「苦」读 kǔ（第三声），意思是酷炫。"}, {"text": "鼓", "is_correct": false, "explanation": "声母不同：「鼓」读 gǔ，声母是 g，「苦」的声母是 k，意思是鼓。"}, {"text": "土", "is_correct": false, "explanation": "声母不同：「土」读 tǔ，声母是 t，「苦」的声母是 k，意思是土地。"}, {"text": "五", "is_correct": false, "explanation": "声母不同：「五」读 wǔ，声母是 w，「苦」的声母是 k，意思是数字五。"}], "explanations": {"苦": "正确：「苦」读 kǔ（第三声），指吃起来不甜的味道。", "酷": "声调不同：「酷」读 kù（第四声），「苦」读 kǔ（第三声），意思是酷炫。", "鼓": "声母不同：「鼓」读 gǔ，声母是 g，「苦」的声母是 k，意思是鼓。", "土": "声母不同：「土」读 tǔ，声母是 t，「苦」的声母是 k，意思是土地。", "五": "声母不同：「五」读 wǔ，声母是 w，「苦」的声母是 k，意思是数字五。"}, "sentence_index": null, "correct_answer": "苦"}, "level_3": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「变苦了」指茶泡久了味道变得发苦，符合句意。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：「亮」形容光线或颜色，不能用来形容味道。"}, {"text": "宽", "is_correct": false, "explanation": "搭配：「宽」形容空间或尺寸，不能用来形容味道。"}, {"text": "快", "is_correct": false, "explanation": "语义：「快」指速度，茶泡久了味道不会变快。"}], "explanations": {"苦": "正确：「变苦了」指茶泡久了味道变得发苦，符合句意。", "亮": "搭配：「亮」形容光线或颜色，不能用来形容味道。", "宽": "搭配：「宽」形容空间或尺寸，不能用来形容味道。", "快": "语义：「快」指速度，茶泡久了味道不会变快。"}, "sentence_index": 6, "correct_answer": "苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盒茶叶的香味很苦，我不太喜欢。", "explanation": "这里应该用〈清香〉。苦是味觉，气味不能说苦，要说清香。"}, {"text": "这幅画的颜色很苦，看着很刺眼。", "explanation": "这里应该用〈鲜艳〉。苦是味觉，颜色不能说苦，要说鲜艳。"}, {"text": "这杯蜂蜜水甜滋滋的，很苦。", "explanation": "这里应该用〈甜〉。苦与甜相反，甜滋滋的蜂蜜水不能说苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这碗中药没加糖，喝起来苦很。", "corrected_sentence": "这碗中药没加糖，喝起来很苦。", "error_description": "「很」要放在形容词「苦」之前，应说「喝起来很苦」，不说「喝起来苦很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这壶茶放久了，味道苦变了。", "corrected_sentence": "这壶茶放久了，味道变苦了。", "error_description": "「变苦」是「变」带结果补语「苦」，应说「味道变苦了」，不能说「味道苦变了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
