INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94432, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生活或处境艰难，使人难受。", "primary_collocate": null, "pronunciation": "kǔ", "ipa": "kʰu˨˩˦", "syllable_count": 1, "sentences": [{"text": "他小时候家里很穷，日子过得很苦。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年工作又累又苦，他从不抱怨。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶一个人带大三个孩子，真苦啊。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人这一生过得很苦，现在终于享福了。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们那时候生活很苦，常常吃不饱。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民种田很苦，天不亮就要下地。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里很苦，却不愿意告诉别人。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一个人养家，她的命太苦了。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起以前的苦日子，现在好多了。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚到城里没钱没工作，觉得很苦。", "target_word": "苦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辛苦", "label": "复合"}, {"form": "苦难", "label": "复合"}], "register": "中性", "sense_fingerprint": "生活艰难，心里难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119b896a-7a6c-482d-97ff-7470b8956fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94432, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「苦」读 kǔ（第三声），指处境艰难、使人难受。"}, {"text": "哭", "is_correct": false, "explanation": "声调不同：「哭」读 kū（第一声），「苦」读 kǔ（第三声），意思是哭泣。"}, {"text": "库", "is_correct": false, "explanation": "声调不同：「库」读 kù（第四声），「苦」读 kǔ（第三声），意思是仓库。"}, {"text": "古", "is_correct": false, "explanation": "声母不同：「古」读 gǔ，声母是 g，「苦」的声母是 k，意思是古老。"}, {"text": "土", "is_correct": false, "explanation": "声母不同：「土」读 tǔ，声母是 t，「苦」的声母是 k，意思是土地。"}], "explanations": {"苦": "正确：「苦」读 kǔ（第三声），指处境艰难、使人难受。", "哭": "声调不同：「哭」读 kū（第一声），「苦」读 kǔ（第三声），意思是哭泣。", "库": "声调不同：「库」读 kù（第四声），「苦」读 kǔ（第三声），意思是仓库。", "古": "声母不同：「古」读 gǔ，声母是 g，「苦」的声母是 k，意思是古老。", "土": "声母不同：「土」读 tǔ，声母是 t，「苦」的声母是 k，意思是土地。"}, "sentence_index": null, "correct_answer": "苦"}, "level_3": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「过得很苦」指生活艰难，与前句“家里很穷”相符。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：「富裕」与前句“家里很穷”相矛盾，不能用于这个语境。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」形容身体，不能用来形容日子过得怎样。"}, {"text": "奢侈", "is_correct": false, "explanation": "语义：「奢侈」指花钱大方、生活讲究，与前句“家里很穷”相矛盾。"}], "explanations": {"苦": "正确：「过得很苦」指生活艰难，与前句“家里很穷”相符。", "富裕": "语义：「富裕」与前句“家里很穷”相矛盾，不能用于这个语境。", "胖": "体貌：「胖」形容身体，不能用来形容日子过得怎样。", "奢侈": "语义：「奢侈」指花钱大方、生活讲究，与前句“家里很穷”相矛盾。"}, "sentence_index": 0, "correct_answer": "苦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划很苦，需要很多步骤。", "explanation": "这里应该用〈复杂〉。苦形容生活或人的处境艰难，不用来形容计划的繁复程度。"}, {"text": "这支笔很苦，写起来很流畅。", "explanation": "这里应该用〈流畅〉。苦形容人的处境，笔的书写感要用流畅，不说苦。"}, {"text": "这次谈判的进展很苦，双方一直没有结果。", "explanation": "这里应该用〈艰难〉。苦多用于人的生活与遭遇，谈判的进展要用艰难，不说苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94432, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「苦」读 kǔ（第三声），指处境艰难、使人难受。"}, {"text": "裤", "is_correct": false, "explanation": "声调不同：「裤」读 kù（第四声），「苦」读 kǔ（第三声），意思是裤子。"}, {"text": "鼓", "is_correct": false, "explanation": "声母不同：「鼓」读 gǔ，声母是 g，「苦」的声母是 k，意思是鼓。"}, {"text": "努", "is_correct": false, "explanation": "声母不同：「努」读 nǔ，声母是 n，「苦」的声母是 k，意思是努力。"}, {"text": "五", "is_correct": false, "explanation": "声母不同：「五」读 wǔ，声母是 w，「苦」的声母是 k，意思是数字五。"}], "explanations": {"苦": "正确：「苦」读 kǔ（第三声），指处境艰难、使人难受。", "裤": "声调不同：「裤」读 kù（第四声），「苦」读 kǔ（第三声），意思是裤子。", "鼓": "声母不同：「鼓」读 gǔ，声母是 g，「苦」的声母是 k，意思是鼓。", "努": "声母不同：「努」读 nǔ，声母是 n，「苦」的声母是 k，意思是努力。", "五": "声母不同：「五」读 wǔ，声母是 w，「苦」的声母是 k，意思是数字五。"}, "sentence_index": null, "correct_answer": "苦"}, "level_3": {"options": [{"text": "苦", "is_correct": true, "explanation": "正确：「心里很苦」指心中难受，与后句“却不愿意告诉别人”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：「热闹」形容场面，不能用来形容心里的感受。"}, {"text": "圆满", "is_correct": false, "explanation": "语义：「圆满」说事情的结果，不能说心里很圆满，与句意不符。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：「干燥」形容空气或物体缺少水分，不能用来形容心里。"}], "explanations": {"苦": "正确：「心里很苦」指心中难受，与后句“却不愿意告诉别人”相符。", "热闹": "搭配：「热闹」形容场面，不能用来形容心里的感受。", "圆满": "语义：「圆满」说事情的结果，不能说心里很圆满，与句意不符。", "干燥": "搭配：「干燥」形容空气或物体缺少水分，不能用来形容心里。"}, "sentence_index": 6, "correct_answer": "苦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "形势很苦，我们必须马上采取行动。", "explanation": "这里应该用〈严峻〉。苦指人的生活遭遇，形势的紧迫程度要用严峻。"}, {"text": "这本书很苦，我看了三遍也看不懂。", "explanation": "这里应该用〈深奥〉。苦不用来形容书的难懂程度，要说深奥。"}, {"text": "这个理论很苦，学生很难理解。", "explanation": "这里应该用〈抽象〉。苦形容人的处境，理论的抽象程度要用抽象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那几年她过得苦很。", "corrected_sentence": "那几年她过得很苦。", "error_description": "「很」要放在形容词「苦」之前，应说「过得很苦」，不说「过得苦很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚到城里这几年，觉得很太苦。", "corrected_sentence": "他刚到城里这几年，觉得很苦。", "error_description": "「很」和「太」都是程度副词，不能叠用，应删去「太」，说「觉得很苦」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
