INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94435, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "补助是别人给的、帮你过日子的一点钱。", "primary_collocate": null, "pronunciation": "bǔ zhù", "ipa": "pu˨˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶每个月都有一点补助。", "target_word": "补助", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这点补助刚够我们买菜。", "target_word": "补助", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他没有工作，靠政府的补助过日子。", "target_word": "补助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里给老人发了生活补助。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用补助给孩子交了学费。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每月三百元的补助，让他们不再担心吃饭。", "target_word": "补助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的补助不多，所以花钱很小心。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷把这个月的补助都存起来了。", "target_word": "补助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校没有给我补助，我只好打工。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拿到补助以后，他先给家里买了米。", "target_word": "补助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "补助金", "label": "复合"}, {"form": "生活补助", "label": "复合"}, {"form": "補助", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人给的、帮助维持生活的一点钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f23a97a0-1d54-4234-ade3-1bbe96a40f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补助", "is_correct": true, "explanation": "补助是别人给的、帮助维持生活的钱，与“奶奶每个月都有”相符，正确。"}, {"text": "欠款", "is_correct": false, "explanation": "搭配：欠款是欠别人的钱，不能说“有一点欠款”来表示收入。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：罚款是因违规被收的钱，不是别人给的帮助。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是交给学校的钱，不是别人给奶奶的帮助。"}], "explanations": {"补助": "补助是别人给的、帮助维持生活的钱，与“奶奶每个月都有”相符，正确。", "欠款": "搭配：欠款是欠别人的钱，不能说“有一点欠款”来表示收入。", "罚款": "语义：罚款是因违规被收的钱，不是别人给的帮助。", "学费": "语义：学费是交给学校的钱，不是别人给奶奶的帮助。"}, "sentence_index": 0, "correct_answer": "补助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向亲戚借了一笔补助，说好下个月还。", "explanation": "这里应该用〈借款〉。补助是别人给的、帮你过日子的钱，不用归还；要还的钱款应说借款。"}, {"text": "她每天早上都要喝一大碗补助。", "explanation": "这里应该用〈粥〉。补助是给予的钱物，不能用来喝；早上要喝的应说粥。"}, {"text": "老师布置了一份补助，让我们回家做。", "explanation": "这里应该用〈作业〉。补助指帮人过日子的钱，不是要完成的任务；布置回家做的要说作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补助", "is_correct": true, "explanation": "补助是别人给的、帮助生活的钱，“不多，所以花钱很小心”的因果成立，正确。"}, {"text": "押金", "is_correct": false, "explanation": "语义：押金会退还，不能拿来花，与“花钱很小心”的因果说不通。"}, {"text": "税款", "is_correct": false, "explanation": "语义：税款是上交国家的钱，不是个人得到的钱，与句意相反。"}, {"text": "罚金", "is_correct": false, "explanation": "语义：罚金是受罚所交的钱，句中说的是得到的钱，不符。"}], "explanations": {"补助": "补助是别人给的、帮助生活的钱，“不多，所以花钱很小心”的因果成立，正确。", "押金": "语义：押金会退还，不能拿来花，与“花钱很小心”的因果说不通。", "税款": "语义：税款是上交国家的钱，不是个人得到的钱，与句意相反。", "罚金": "语义：罚金是受罚所交的钱，句中说的是得到的钱，不符。"}, "sentence_index": 6, "correct_answer": "补助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生每个学期都要交补助。", "explanation": "这里应该用〈学费〉。补助是给予的钱，不由学生交出去。"}, {"text": "银行按时给他的存款付了补助。", "explanation": "这里应该用〈利息〉。补助是给予的帮助，不是存款的收益。"}, {"text": "他因为违章被罚了一笔补助。", "explanation": "这里应该用〈罚款〉。补助是别人给的钱，不是处罚；被罚的钱要说罚款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的一只补助已经到账了。", "corrected_sentence": "这个月的一笔补助已经到账了。", "error_description": "错误在于量词：补助是钱款，量词应用“笔”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把一个补助发给了每个学生。", "corrected_sentence": "学校把一笔补助发给了每个学生。", "error_description": "错误在于量词：补助是钱款，量词应用“笔”，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
