INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "翻译，把一种语言文字转换为另一种。", "primary_collocate": null, "pronunciation": "yì", "ipa": "i˥˩", "syllable_count": 1, "sentences": [{"text": "这本小说已经译成十几种语言了。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这首中国诗译成了英文。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章太难，我一个人译不完。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她正在译一本法语的儿童书。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这封信译成日文，明天交给我。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词很难译，因为汉语里没有对应的说法。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他译过很多本德国小说。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗译成别的语言，味道就变了。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天晚上译两页书，已经译了半年。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书译得很好，读起来像中文原著。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "译了", "label": "体标：了"}, {"form": "译过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "把书、文章等文字材料翻成另一种语言文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f834fce6-8bd2-470f-a5c3-a80bfad7aa75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，正是本词的意思。"}, {"text": "衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是衣服。"}, {"text": "已", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经。"}, {"text": "疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是怀疑。"}, {"text": "椅", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是椅子。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，正是本词的意思。", "衣": "yī（第一声）与 yì（第四声）声调不同，意思是衣服。", "已": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经。", "疑": "yí（第二声）与 yì（第四声）声调不同，意思是怀疑。", "椅": "yǐ（第三声）与 yì（第四声）声调不同，意思是椅子。"}, "sentence_index": null, "correct_answer": "译"}, "level_3": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，符合「已经……成十几种语言」。"}, {"text": "删", "is_correct": false, "explanation": "语义：「删」是去掉，不能表示把文字变成另一种语言。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切成」用于具体物体，小说不能切成语言。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮成」用于烹饪，不能用于语言。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，符合「已经……成十几种语言」。", "删": "语义：「删」是去掉，不能表示把文字变成另一种语言。", "切": "搭配：「切成」用于具体物体，小说不能切成语言。", "煮": "搭配：「煮成」用于烹饪，不能用于语言。"}, "sentence_index": 0, "correct_answer": "译"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她坐在沙发上，译着旧相册。", "explanation": "这里应该用〈翻看〉。译是把文字转换成另一种语言，相册是图片，要翻看。"}, {"text": "她每天早上译一杯牛奶。", "explanation": "这里应该用〈喝〉。译是语言转换，牛奶是饮品，要喝，不能说译。"}, {"text": "他花了一下午译那把旧吉他。", "explanation": "这里应该用〈修补〉。译是语言转换，吉他是乐器，要修补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，正是本词的意思。"}, {"text": "一", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是数字「一」。"}, {"text": "以", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是用、凭借。"}, {"text": "移", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是移动。"}, {"text": "医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是医生、治病。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，正是本词的意思。", "一": "yī（第一声）与 yì（第四声）声调不同，意思是数字「一」。", "以": "yǐ（第三声）与 yì（第四声）声调不同，意思是用、凭借。", "移": "yí（第二声）与 yì（第四声）声调不同，意思是移动。", "医": "yī（第一声）与 yì（第四声）声调不同，意思是医生、治病。"}, "sentence_index": null, "correct_answer": "译"}, "level_3": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，符合「他……过很多本德国小说」。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，小说不能吃。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，小说不能唱。"}, {"text": "跳", "is_correct": false, "explanation": "配价：「跳」是不及物动词，不能带「小说」作宾语。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，符合「他……过很多本德国小说」。", "吃": "搭配：「吃」的对象是食物，小说不能吃。", "唱": "搭配：「唱」的对象是歌曲，小说不能唱。", "跳": "配价：「跳」是不及物动词，不能带「小说」作宾语。"}, "sentence_index": 6, "correct_answer": "译"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计每天都译一遍收支。", "explanation": "这里应该用〈计算〉。译是语言转换，收支是数字，要计算。"}, {"text": "妈妈在厨房译晚饭。", "explanation": "这里应该用〈烹饪〉。译只用于文字材料，晚饭要烹饪。"}, {"text": "工匠每天都译一扇屏风。", "explanation": "这里应该用〈修复〉。译是语言转换，屏风是器物，要修复，不能说译。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同译很准确。", "corrected_sentence": "这份合同译得很准确。", "error_description": "「译」与「很准确」之间需要补语标记「得」，应说「译得很准确」，不能直接说「译很准确」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌词译给了英文。", "corrected_sentence": "这首歌词译成了英文。", "error_description": "「译」后接语言时要用「成」，应说「译成了英文」；「给」表示给予的对象，不能与「英文」搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
