INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94441, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "错过是该做的事没做上，或者没赶上。", "primary_collocate": null, "pronunciation": "cuò guò", "ipa": "tsʰuɔ˥˩ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "我起晚了，错过了第一班地铁。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上堵车，他错过了飞机。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影八点开始，我八点半才到，错过了开头。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，错过了昨天的考试。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车刚开走，我们错过了这班车。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时我在看手机，错过了经理说的重点。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太可惜了，你错过了昨晚的足球比赛。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天起晚了，错过了早饭。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他加班太晚，错过了末班公交车。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他因为出差，错过了妈妈的生日聚会。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "错过了", "label": "体标"}], "register": "中性", "sense_fingerprint": "错过：没赶上车船、活动或该做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c6295ca-33a1-4cb5-9a44-6d80043396b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撞见", "is_correct": false, "explanation": "搭配：“撞见”的宾语多是人或突发的事情，不说“撞见地铁”这样的交通工具。"}, {"text": "错过", "is_correct": true, "explanation": "正确：“错过”指没赶上，与“我起晚了”的因果关系一致。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”表示开动车辆，与“起晚了”的语境没有逻辑关系，句意荒谬。"}, {"text": "迎来", "is_correct": false, "explanation": "语义：“迎来”表示欣然等到，与“起晚了”的语境相矛盾。"}], "explanations": {"撞见": "搭配：“撞见”的宾语多是人或突发的事情，不说“撞见地铁”这样的交通工具。", "错过": "正确：“错过”指没赶上，与“我起晚了”的因果关系一致。", "驾驶": "语义：“驾驶”表示开动车辆，与“起晚了”的语境没有逻辑关系，句意荒谬。", "迎来": "语义：“迎来”表示欣然等到，与“起晚了”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "错过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他错过了一床被子，晚上冷得睡不着。", "explanation": "这里应该用〈盖〉。“错过”指没遇上或没抓住机会、时间，不能表示“盖被子”这样的动作。"}, {"text": "他错过了那只苹果，饿得肚子咕咕叫。", "explanation": "这里应该用〈吃〉。“错过”指没遇上或没抓住机会、时间，不能表示“吃掉”这样的动作。"}, {"text": "他错过了作业，交给了老师。", "explanation": "这里应该用〈完成〉。“错过”不能跟“作业”这类任务搭配，应说“完成作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设计", "is_correct": false, "explanation": "搭配：“设计”接方案、产品等，不接“比赛”。"}, {"text": "错过", "is_correct": true, "explanation": "正确：“错过”指没赶上比赛，与“太可惜了”的语气吻合。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求食物作宾语，不能接“比赛”。"}, {"text": "赢得", "is_correct": false, "explanation": "语义：“赢得”表示胜出，与“太可惜了”的语气相反。"}], "explanations": {"设计": "搭配：“设计”接方案、产品等，不接“比赛”。", "错过": "正确：“错过”指没赶上比赛，与“太可惜了”的语气吻合。", "吃": "配价：“吃”要求食物作宾语，不能接“比赛”。", "赢得": "语义：“赢得”表示胜出，与“太可惜了”的语气相反。"}, "sentence_index": 6, "correct_answer": "错过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于错过了压力，松了一口气。", "explanation": "这里应该用〈摆脱〉。“错过”不能跟“压力”搭配，应说“摆脱压力”。"}, {"text": "他错过了问题，同学们都很佩服。", "explanation": "这里应该用〈解决〉。“错过”指没赶上，不能用于“问题”。"}, {"text": "他错过了照片，给朋友看。", "explanation": "这里应该用〈拍摄〉。“错过”不指做出某个东西，只指没遇上或没抓住时机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我因为在路上买东西，错过这班公交车。", "corrected_sentence": "我因为在路上买东西，错过了这班公交车。", "error_description": "“错过”表示已经发生的事，动词后缺少动态助词“了”。应为“错过了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她因为生病，错过掉了朋友的婚礼。", "corrected_sentence": "她因为生病，错过了朋友的婚礼。", "error_description": "“错过”后面不能接“掉”作结果补语，应为“错过了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
