INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有遇上或没有抓住（机会、时间等）。", "primary_collocate": null, "pronunciation": "cuò guò", "ipa": "tsʰuɔ˥˩ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他没有好好努力，错过了这次机会。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忙着工作，错过了报名的时间。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好机会只有一次，别错过。", "target_word": "错过", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她来得太晚，错过了最好的时机。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻时错过的机会，以后很难再有。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她忘了日期，错过了申请的截止日期。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天很短，不要错过赏花的好时间。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天加班，错过了和家人在一起的好时光。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犹豫了半天，结果错过了最好的买房时机。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换工作太慢，错过了升职的机会。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "错过了", "label": "体标"}], "register": "中性", "sense_fingerprint": "错过：没抓住机会、时机或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c6295ca-33a1-4cb5-9a44-6d80043396b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争取", "is_correct": false, "explanation": "语义：“争取”要靠主动努力去求得，与“没有好好努力”正相矛盾。"}, {"text": "错过", "is_correct": true, "explanation": "正确：“错过”指没有抓住机会，与“没有好好努力”的语境一致。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多接待遇、生活等，不说“享受机会”。"}, {"text": "把握", "is_correct": false, "explanation": "语义：“把握”表示抓住机会，与“没有好好努力”的语境相悖。"}], "explanations": {"争取": "语义：“争取”要靠主动努力去求得，与“没有好好努力”正相矛盾。", "错过": "正确：“错过”指没有抓住机会，与“没有好好努力”的语境一致。", "享受": "搭配：“享受”多接待遇、生活等，不说“享受机会”。", "把握": "语义：“把握”表示抓住机会，与“没有好好努力”的语境相悖。"}, "sentence_index": 0, "correct_answer": "错过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师错过了他这次迟到，没有批评。", "explanation": "这里应该用〈放过〉。“错过”指没遇上或没抓住，不能表示“不追究”。"}, {"text": "他错过了作业里的一个逗号，被扣了分。", "explanation": "这里应该用〈漏掉〉。“错过”用于机会、时间、活动，不能说“错过一个逗号”。"}, {"text": "我们错过了迎面飞来的石头。", "explanation": "这里应该用〈躲开〉。“错过”指没遇上机会或事件，不能表示“躲避”危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "珍惜", "is_correct": false, "explanation": "语义：“珍惜”表示珍视，与“不要”组合后意思与“春天很短”的劝勉相反。"}, {"text": "错过", "is_correct": true, "explanation": "正确：“错过”指没有遇上，句中表示不要让好时光从身边溜走。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”接景物、作品，不接“好时间”这样的时段。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“节约”表示省下，与“不要”组合后意思与语境的珍惜之意相反。"}], "explanations": {"珍惜": "语义：“珍惜”表示珍视，与“不要”组合后意思与“春天很短”的劝勉相反。", "错过": "正确：“错过”指没有遇上，句中表示不要让好时光从身边溜走。", "欣赏": "搭配：“欣赏”接景物、作品，不接“好时间”这样的时段。", "节约": "语义：“节约”表示省下，与“不要”组合后意思与语境的珍惜之意相反。"}, "sentence_index": 6, "correct_answer": "错过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于错过了困境，松了一口气。", "explanation": "这里应该用〈摆脱〉。“错过”用于机会、时间、活动，不能说“错过困境”。"}, {"text": "她错过了窗户，觉得很冷。", "explanation": "这里应该用〈打开〉。“错过”指没遇上或没抓住机会、时间，不能跟“窗户”这类物体搭配。"}, {"text": "他们错过了这份快乐，玩得很开心。", "explanation": "这里应该用〈分享〉。“错过”表示没抓住，与后半句“玩得很开心”自相矛盾；想说一起享受快乐，应说“分享快乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为犹豫，错过过这次机会。", "corrected_sentence": "他因为犹豫，错过了这次机会。", "error_description": "“错过”后面重复用了“过”，错在体标。应为“错过了”，表示这次机会已经没抓住。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她因为临时出差，错过着这个难得的机会。", "corrected_sentence": "她因为临时出差，错过了这个难得的机会。", "error_description": "“错过”后面不能接“着”表示持续，这里说的是已经发生的事，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
