INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开通是把原来不通的路或线弄通,让人可以用。", "primary_collocate": null, "pronunciation": "kāi tōng", "ipa": "kʰaɪ˥ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这条新路下个月开通。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把山里的路开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁三号线昨天开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里修了一条新路，终于开通了。", "target_word": "开通", "complexity_tier": "T3", "furigana": "cūn lǐ xiū le yì tiáo xīn lù, zhōng yú kāi tōng le.", "sentence_source": "generated"}, {"text": "他们想开通一条去海边的路。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水堵住了,大家把水路开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥开通以后,过河很方便。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路开通以后,卖菜的人多起来了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老家终于开通了去县城的公路。", "target_word": "开通", "complexity_tier": "T3", "furigana": "lǎo jiā zhōng yú kāi tōng le qù xiàn chéng de gōng lù.", "sentence_source": "generated"}, {"text": "修路的人把断了的路开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开通了", "label": "体标"}, {"form": "开通过", "label": "体标"}, {"form": "開通", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把不通的路或线弄通,让人使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119b896a-7a6c-482d-97ff-7470b8956fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开通", "is_correct": true, "explanation": "开通指路线可以开始使用，符合“下个月开通”的句意。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：关闭是停止使用，与新路刚建成、准备使用的句意相反。"}, {"text": "消失", "is_correct": false, "explanation": "语义：新路不会在下个月消失。"}, {"text": "堵塞", "is_correct": false, "explanation": "搭配：“堵塞”说的是已经有的路被挡住，与“新路下个月”不搭配。"}], "explanations": {"开通": "开通指路线可以开始使用，符合“下个月开通”的句意。", "关闭": "语义：关闭是停止使用，与新路刚建成、准备使用的句意相反。", "消失": "语义：新路不会在下个月消失。", "堵塞": "搭配：“堵塞”说的是已经有的路被挡住，与“新路下个月”不搭配。"}, "sentence_index": 0, "correct_answer": "开通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个景区去年终于开通了，游客很多。", "explanation": "这里应该用〈开放〉。景区、公园要说“开放”，“开通”多用于路、线、服务。"}, {"text": "工人们终于开通了山里的那座铁矿。", "explanation": "这里应该用〈开采〉。矿产、资源要说“开采”，“开通”指把路或线弄通，多用于路、线、服务。"}, {"text": "工厂的机器终于开通了，大家都很高兴。", "explanation": "这里应该用〈启动〉。机器要说“启动”，“开通”多用于路、线、服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开通", "is_correct": true, "explanation": "开通指桥可以开始通行，“开通以后，过河很方便”符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：桥被拆除后，过河不会方便。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：桥损坏后，过河会更不方便。"}, {"text": "封住", "is_correct": false, "explanation": "搭配：“封住”多用于门窗、出口，不用来说桥的通行状态。"}], "explanations": {"开通": "开通指桥可以开始通行，“开通以后，过河很方便”符合句意。", "拆除": "语义：桥被拆除后，过河不会方便。", "损坏": "语义：桥损坏后，过河会更不方便。", "封住": "搭配：“封住”多用于门窗、出口，不用来说桥的通行状态。"}, "sentence_index": 6, "correct_answer": "开通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司决定开通海外市场。", "explanation": "这里应该用〈开发〉。市场、资源要说“开发”，“开通”多用于路、线、服务。"}, {"text": "他轻轻开通了门，走了进去。", "explanation": "这里应该用〈打开〉。门要说“打开”，“开通”不用于门。"}, {"text": "他们开通了一家新店。", "explanation": "这里应该用〈开设〉。店铺、公司要说“开设”，“开通”多用于路、线、服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们把这座桥开通。", "corrected_sentence": "工人们把这座桥开通了。", "error_description": "把字句要有“了”或其他补充成分才完整：“把这座桥开通”不完整，应说“把这座桥开通了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥明天就会开通着。", "corrected_sentence": "这座桥明天就会开通。", "error_description": "“着”表示动作或状态正在持续，不能与将来的“明天就会”一起用，应直接说“就会开通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
