INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可供观赏的自然景色。", "primary_collocate": null, "pronunciation": "fēng jǐng", "ipa": "fɤŋ˥ tɕiŋ˨˩", "syllable_count": 2, "sentences": [{"text": "来这里的人都是为了看风景。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖边的风景吸引了很多游客。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路上的风景值得慢慢欣赏。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爬到山顶，欣赏着四周的风景。", "target_word": "风景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游说，这里秋天的风景最美。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外的风景像一幅画。", "target_word": "风景", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐船游览，一路上风景不错。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的风景很有名，每年都有很多游客。", "target_word": "风景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪以后，山里的风景更好看了。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在海边住了三天，天天看风景。", "target_word": "风景", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "风景区", "label": "复合"}, {"form": "风景画", "label": "复合"}, {"form": "風景", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可供观赏的自然景色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f23a97a0-1d54-4234-ade3-1bbe96a40f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风景", "is_correct": true, "explanation": "风景指可供观赏的自然景色，与“看”搭配，正好填入句中。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是用来吃的，与“为了看”的动作不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”不能搭配“味道”，味道要用“闻”或“尝”来感知。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能搭配“声音”，声音要用“听”来感知。"}], "explanations": {"风景": "风景指可供观赏的自然景色，与“看”搭配，正好填入句中。", "食物": "语义：食物是用来吃的，与“为了看”的动作不符。", "味道": "搭配：“看”不能搭配“味道”，味道要用“闻”或“尝”来感知。", "声音": "搭配：“看”不能搭配“声音”，声音要用“听”来感知。"}, "sentence_index": 0, "correct_answer": "风景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在台上的风景很迷人，观众都为他鼓掌。", "explanation": "这里应该用〈风采〉。风采指人的仪态，风景指自然景色，不能用来形容人。"}, {"text": "这次比赛，我们的风景很差。", "explanation": "这里应该用〈成绩〉。风景只指可供观赏的自然景色，没有“成绩”的意思，这里用错了词义。"}, {"text": "这个项目的风景很光明。", "explanation": "这里应该用〈前景〉。风景指自然景色，指事情的发展趋势要用“前景”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风景", "is_correct": true, "explanation": "风景指可供观赏的自然景色，“一路上风景不错”符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是令人厌恶的废弃物，不能被评为“不错”。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“不错”多用来评价景致、天气等，不能说“问题不错”。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是令人烦躁的声音，与“不错”的好评相反。"}], "explanations": {"风景": "风景指可供观赏的自然景色，“一路上风景不错”符合句意。", "垃圾": "语义：垃圾是令人厌恶的废弃物，不能被评为“不错”。", "问题": "搭配：“不错”多用来评价景致、天气等，不能说“问题不错”。", "噪音": "语义：噪音是令人烦躁的声音，与“不错”的好评相反。"}, "sentence_index": 6, "correct_answer": "风景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在这种风景下，大家都很紧张。", "explanation": "这里应该用〈情景〉。风景指可供观赏的自然景色，指当时的情形、场面要用“情景”。"}, {"text": "他在舞台上演了一场风景。", "explanation": "这里应该用〈戏〉。风景指自然景色，不能被表演，演出的应是戏。"}, {"text": "他的风景很英俊，很多人都喜欢他。", "explanation": "这里应该用〈相貌〉。风景指自然景色，人的长相要用“相貌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站在山顶看一只风景。", "corrected_sentence": "他站在山顶看风景。", "error_description": "错误形式：看一只风景；正确形式：看风景（或看一片风景）。“风景”是景色，量词应用“片”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一只美丽的风景。", "corrected_sentence": "这里有美丽的风景。", "error_description": "错误形式：一只美丽的风景；正确形式：美丽的风景（或一片美丽的风景）。“风景”是景色，量词应用“片”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
