INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不算是不能算在里面，或者不到那个样子。", "primary_collocate": null, "pronunciation": "bù suàn", "ipa": "pu˥˩ suan˥˩", "syllable_count": 2, "sentences": [{"text": "鲸不算鱼，它是哺乳动物。", "target_word": "不算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们刚认识，还不算朋友。", "target_word": "不算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这点钱不算贵，我可以买。", "target_word": "不算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只会几句英语，不算会说英语。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天二十度，对冬天来说不算冷。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，我的字写得还不算太差。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的小毛病不算大问题。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这里住了三个月，不算新来的了。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人不算好人，他经常骗别人。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去那儿只要五分钟，不算远。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不能归入某一类，或不属于某种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f834fce6-8bd2-470f-a5c3-a80bfad7aa75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不算", "is_correct": true, "explanation": "正确。“不算”表示不能归入某一类，这里说鲸不归入鱼类。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”是归入某一类，与后半句“它是哺乳动物”的判断相反。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”是把东西放在某个范围里，说“鲸包括鱼”与句子意思矛盾。"}, {"text": "比作", "is_correct": false, "explanation": "搭配：“比作”要用在打比方的句子里，不能直接用来判断鲸是不是鱼。"}], "explanations": {"不算": "正确。“不算”表示不能归入某一类，这里说鲸不归入鱼类。", "属于": "语义：“属于”是归入某一类，与后半句“它是哺乳动物”的判断相反。", "包括": "语义：“包括”是把东西放在某个范围里，说“鲸包括鱼”与句子意思矛盾。", "比作": "搭配：“比作”要用在打比方的句子里，不能直接用来判断鲸是不是鱼。"}, "sentence_index": 0, "correct_answer": "不算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书不算了，我们今天不读了。", "explanation": "这里应该用〈作罢〉。“不算”表示不归入或达不到，不能表示取消某件事。"}, {"text": "这件衣服不算那件高，我们换一件。", "explanation": "这里应该用〈不如〉。“不算”表示不归入某一类或不到某个样子，不用于比较高矮或好坏。"}, {"text": "明天不算会下雨，你不用带伞。", "explanation": "这里应该用〈不会〉。“不算”表示不归入或达不到，不能用来预测天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不算", "is_correct": true, "explanation": "正确。“不算”表示达不到大问题的程度，这里说小毛病不算大问题。"}, {"text": "抱怨", "is_correct": false, "explanation": "搭配：“抱怨”接的是人的不满，不能说“抱怨大问题”。"}, {"text": "分析", "is_correct": false, "explanation": "搭配：“分析”后面接的是问题或原因，这里说“分析大问题”不通。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指否定已有的结论，与“小毛病”的轻微程度不符。"}], "explanations": {"不算": "正确。“不算”表示达不到大问题的程度，这里说小毛病不算大问题。", "抱怨": "搭配：“抱怨”接的是人的不满，不能说“抱怨大问题”。", "分析": "搭配：“分析”后面接的是问题或原因，这里说“分析大问题”不通。", "推翻": "语义：“推翻”指否定已有的结论，与“小毛病”的轻微程度不符。"}, "sentence_index": 6, "correct_answer": "不算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些钱不算买车，还差很多。", "explanation": "这里应该用〈不够〉。“不算”表示不归入或达不到，不能用来说钱够不够买车。"}, {"text": "这本书不算十块钱，买它太贵了。", "explanation": "这里应该用〈不值〉。“不算十块钱”说明价格低，与后句“太贵”相矛盾。"}, {"text": "他很不算高兴，一直看着窗外。", "explanation": "这里应该用〈不太〉。“不算”前不能加程度副词“很”，“很不算”不通，应说“不太高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们还不不算熟，只见过两次。", "corrected_sentence": "我们还不算熟，只见过两次。", "error_description": "多加了一个“不”：“不不算熟”重复否定，不通，应说“不算熟”，表示还达不到“熟”的程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩不算了差，但是进步很快。", "corrected_sentence": "他的成绩不算差，但是进步很快。", "error_description": "多加了“了”：“不算”是否定形式，中间不能插入“了”，应说“不算差”，表示成绩还不到差的程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
