INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "之际是说某一件事发生的那个时候。", "primary_collocate": null, "pronunciation": "zhī jì", "ipa": "ʈʂɻ̩˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "火车出发之际，妈妈跑来送了水果。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "危急之际，他第一个冲了上去。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "收到通知之际，我正在做饭。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他搬家之际，邻居都来帮忙了。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在两国领导人见面之际，天下起了雨。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试开始之际，教室里突然停电了。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婚礼开始之际，新娘的眼睛红了。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司困难之际，他没有离开。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她出国留学之际，爸爸送了她一支笔。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨来临之际，工人们赶快回家了。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "之际：用在事情后，指这件事发生的那个时候（危急之际）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c6295ca-33a1-4cb5-9a44-6d80043396b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94457, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之际", "is_correct": true, "explanation": "正确：之际 zhījì（第一、第四声）指某事发生的那个时候，如“火车出发之际”。"}, {"text": "知己", "is_correct": false, "explanation": "zhījǐ（第三声）与 zhījì（第四声）第二个音节声调不同，意思是知心的朋友。"}, {"text": "字迹", "is_correct": false, "explanation": "zìjì 与 zhījì 第一个音节声母不同（z 与 zh），声调也不同，意思是字的笔迹。"}, {"text": "四季", "is_correct": false, "explanation": "sìjì 与 zhījì 声母不同（s 与 zh），声调也不同，意思是春夏秋冬。"}, {"text": "值机", "is_correct": false, "explanation": "zhíjī（第二声、第一声）与 zhījì 两个音节声调都不同，意思是办理登机手续。"}], "explanations": {"之际": "正确：之际 zhījì（第一、第四声）指某事发生的那个时候，如“火车出发之际”。", "知己": "zhījǐ（第三声）与 zhījì（第四声）第二个音节声调不同，意思是知心的朋友。", "字迹": "zìjì 与 zhījì 第一个音节声母不同（z 与 zh），声调也不同，意思是字的笔迹。", "四季": "sìjì 与 zhījì 声母不同（s 与 zh），声调也不同，意思是春夏秋冬。", "值机": "zhíjī（第二声、第一声）与 zhījì 两个音节声调都不同，意思是办理登机手续。"}, "sentence_index": null, "correct_answer": "之际"}, "level_3": {"options": [{"text": "之下", "is_correct": false, "explanation": "语义：“之下”表示在…底下，“火车出发之下”意思不通。"}, {"text": "之际", "is_correct": true, "explanation": "正确：“之际”指某事发生的那个时候，与“火车出发”搭配自然。"}, {"text": "之间", "is_correct": false, "explanation": "配价：“之间”要求两方或多方，“火车出发之间”缺少对象。"}, {"text": "之内", "is_correct": false, "explanation": "搭配：“之内”接时间段或范围，不接“出发”这类动作。"}], "explanations": {"之下": "语义：“之下”表示在…底下，“火车出发之下”意思不通。", "之际": "正确：“之际”指某事发生的那个时候，与“火车出发”搭配自然。", "之间": "配价：“之间”要求两方或多方，“火车出发之间”缺少对象。", "之内": "搭配：“之内”接时间段或范围，不接“出发”这类动作。"}, "sentence_index": 0, "correct_answer": "之际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三天之际，邻居都来帮忙了。", "explanation": "这里应该用〈之内〉。“之际”指时间点或阶段，不能表示一段时间的范围。"}, {"text": "他的眼睛之际很亮。", "explanation": "这里应该去掉〈之际〉，说“他的眼睛很亮”。“之际”只表示时间，不能描述眼睛的样子。"}, {"text": "屋里之际放着一张床。", "explanation": "“之际”只用于时间，不用于表示屋里的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94457, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之际", "is_correct": true, "explanation": "正确：之际 zhījì（第一、第四声）指某事发生的那个时候，如“大雨来临之际”。"}, {"text": "世纪", "is_correct": false, "explanation": "shìjì 与 zhījì 声母不同（sh 与 zh），声调也不同，意思是一百年。"}, {"text": "实际", "is_correct": false, "explanation": "shíjì 与 zhījì 声母不同（sh 与 zh），声调也不同，意思是实际、真实。"}, {"text": "直击", "is_correct": false, "explanation": "zhíjī（第二声、第一声）与 zhījì 两个音节声调都不同，意思是直接目击。"}, {"text": "织机", "is_correct": false, "explanation": "zhījī（第一声）与 zhījì 第二个音节声调不同，意思是纺织用的机器。"}], "explanations": {"之际": "正确：之际 zhījì（第一、第四声）指某事发生的那个时候，如“大雨来临之际”。", "世纪": "shìjì 与 zhījì 声母不同（sh 与 zh），声调也不同，意思是一百年。", "实际": "shíjì 与 zhījì 声母不同（sh 与 zh），声调也不同，意思是实际、真实。", "直击": "zhíjī（第二声、第一声）与 zhījì 两个音节声调都不同，意思是直接目击。", "织机": "zhījī（第一声）与 zhījì 第二个音节声调不同，意思是纺织用的机器。"}, "sentence_index": null, "correct_answer": "之际"}, "level_3": {"options": [{"text": "之上", "is_correct": false, "explanation": "搭配：“之上”表示在…上面，不接“婚礼开始”这种时间性的事件。"}, {"text": "之际", "is_correct": true, "explanation": "正确：“之际”指某事发生的那个时候，与“婚礼开始”搭配自然。"}, {"text": "之地", "is_correct": false, "explanation": "语义：“之地”指地方，“婚礼开始之地”与语境不符，指的是地点而非时间。"}, {"text": "之处", "is_correct": false, "explanation": "语义：“之处”指地点或部分，不表示事件发生的时间点。"}], "explanations": {"之上": "搭配：“之上”表示在…上面，不接“婚礼开始”这种时间性的事件。", "之际": "正确：“之际”指某事发生的那个时候，与“婚礼开始”搭配自然。", "之地": "语义：“之地”指地方，“婚礼开始之地”与语境不符，指的是地点而非时间。", "之处": "语义：“之处”指地点或部分，不表示事件发生的时间点。"}, "sentence_index": 6, "correct_answer": "之际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子之际，放着一本书。", "explanation": "这里应该用〈之上〉。“之际”指时间点，不能表示物体的位置。"}, {"text": "她跟同学之际很开心。", "explanation": "这里应该用〈相处〉。“之际”只表示时间，不能用来描述与人相处的样子。"}, {"text": "这个包之际装着三本书。", "explanation": "这里应该用〈之中〉。“之际”是时间意义，不指物体内部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子出生际，父母都在身边。", "corrected_sentence": "孩子出生之际，父母都在身边。", "error_description": "错误：“之际”是一个整体，去掉“之”就不成词，“出生际”不通。正确：应说“出生之际”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛开始之际的，观众都站了起来。", "corrected_sentence": "比赛开始之际，观众都站了起来。", "error_description": "“之际”后面不能加“的”，它不是名词修饰语，应直接接逗号。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
