INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时候；某个时间点或阶段。", "primary_collocate": null, "pronunciation": "zhī jì", "ipa": "ʈʂɻ̩˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "新年之际，祝大家身体健康。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毕业之际，同学们互相写了留言。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节之际，很多人坐火车回家。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国庆之际，大街上挂满了红旗。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在公司成立十周年之际，老板发了礼物。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离开家乡之际，他回头看了一眼。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在春天来临之际，公园里开满了花。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开学之际，商店里的书包卖得很快。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束之际，大家都站了起来。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在新旧年交替之际，城市里放起了烟花。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "之际：用在时间词后，指某个时间点或阶段（新年之际）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c6295ca-33a1-4cb5-9a44-6d80043396b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94458, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之际", "is_correct": true, "explanation": "正确：之际 zhījì（第一、第四声）指某个时间点或阶段，如“新年之际”。"}, {"text": "知己", "is_correct": false, "explanation": "zhījǐ（第三声）与 zhījì（第四声）第二个音节声调不同，意思是知心的朋友。"}, {"text": "实际", "is_correct": false, "explanation": "shíjì 与 zhījì 声母不同（sh 与 zh），声调也不同，意思是实际、真实。"}, {"text": "字迹", "is_correct": false, "explanation": "zìjì 与 zhījì 第一个音节声母不同（z 与 zh），声调也不同，意思是字的笔迹。"}, {"text": "直击", "is_correct": false, "explanation": "zhíjī（第二声、第一声）与 zhījì 两个音节声调都不同，意思是直接目击。"}], "explanations": {"之际": "正确：之际 zhījì（第一、第四声）指某个时间点或阶段，如“新年之际”。", "知己": "zhījǐ（第三声）与 zhījì（第四声）第二个音节声调不同，意思是知心的朋友。", "实际": "shíjì 与 zhījì 声母不同（sh 与 zh），声调也不同，意思是实际、真实。", "字迹": "zìjì 与 zhījì 第一个音节声母不同（z 与 zh），声调也不同，意思是字的笔迹。", "直击": "zhíjī（第二声、第一声）与 zhījì 两个音节声调都不同，意思是直接目击。"}, "sentence_index": null, "correct_answer": "之际"}, "level_3": {"options": [{"text": "之地", "is_correct": false, "explanation": "语义：“之地”指地点，与“新年”这个时间不合。"}, {"text": "之际", "is_correct": true, "explanation": "正确：“之际”指某个时间点或阶段，与“新年”搭配自然。"}, {"text": "之下", "is_correct": false, "explanation": "语义：“之下”表示在…底下，与“新年”这个时间不合。"}, {"text": "之处", "is_correct": false, "explanation": "语义：“之处”指地点或部分，不表示时间点，与“新年”不合。"}], "explanations": {"之地": "语义：“之地”指地点，与“新年”这个时间不合。", "之际": "正确：“之际”指某个时间点或阶段，与“新年”搭配自然。", "之下": "语义：“之下”表示在…底下，与“新年”这个时间不合。", "之处": "语义：“之处”指地点或部分，不表示时间点，与“新年”不合。"}, "sentence_index": 0, "correct_answer": "之际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一周之际，他读完了这本书。", "explanation": "这里应该用〈之内〉。“之际”指时间点或阶段，不能表示一段时间的范围。"}, {"text": "他明天之际去北京出差。", "explanation": "这里应该用〈那天〉。“之际”指某件大事或特定时刻，不能用于一个普通的日子。"}, {"text": "教室之际，大家都安静下来。", "explanation": "“之际”只用于时间，不用于地点，不能指教室这样的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') 