INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94463, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个位是一个数最右边的那个数字的位置。", "primary_collocate": null, "pronunciation": "gè wèi", "ipa": "kɤ˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "二十五的个位是五。", "target_word": "个位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你写出这个数的个位。", "target_word": "个位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "三百四十七的个位是七。", "target_word": "个位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "个位在一个数的最右边。", "target_word": "个位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问我们：“这个数的个位是几？”", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个数的个位是零，十位是三。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把八写在个位上。", "target_word": "个位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百二十三，三在个位，二在十位。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明把个位和十位的数字写反了。", "target_word": "个位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在个位上写了一个九。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个位数", "label": "复合"}, {"form": "個位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个数最右边数字所在的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f23a97a0-1d54-4234-ade3-1bbe96a40f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个位", "is_correct": true, "explanation": "个位是数字最右边的位置，二十五的个位是五，符合句意。"}, {"text": "十位", "is_correct": false, "explanation": "语义：十位是倒数第二位，“二十五”的十位是二，不是五。"}, {"text": "百位", "is_correct": false, "explanation": "语义：“二十五”只有两位，没有百位，这个说法不成立。"}, {"text": "小数位", "is_correct": false, "explanation": "搭配：小数位用于小数，不能与整数“二十五”搭配。"}], "explanations": {"个位": "个位是数字最右边的位置，二十五的个位是五，符合句意。", "十位": "语义：十位是倒数第二位，“二十五”的十位是二，不是五。", "百位": "语义：“二十五”只有两位，没有百位，这个说法不成立。", "小数位": "搭配：小数位用于小数，不能与整数“二十五”搭配。"}, "sentence_index": 0, "correct_answer": "个位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司的个位很高，大家都很尊敬他。", "explanation": "这里应该用〈地位〉。个位只指数字的位置，指身份高低要用“地位”。"}, {"text": "这些零件的个位很多。", "explanation": "这里应该用〈个数〉。个位指数字的位置，表示东西的数量要用“个数”。"}, {"text": "我们要尊重每个个位的想法。", "explanation": "这里应该用〈个体〉。个位指数字的位置，指单独的每一个人要用“个体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个位", "is_correct": true, "explanation": "个位是数字所在的位置，可以把数字写在上面，符合句意。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：影子是光线形成的暗像，不能用来写字。"}, {"text": "风", "is_correct": false, "explanation": "语义：风是看不见的空气流动，无法承载文字。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音转瞬即逝，没有可以书写的表面。"}], "explanations": {"个位": "个位是数字所在的位置，可以把数字写在上面，符合句意。", "影子": "搭配：影子是光线形成的暗像，不能用来写字。", "风": "语义：风是看不见的空气流动，无法承载文字。", "声音": "语义：声音转瞬即逝，没有可以书写的表面。"}, "sentence_index": 6, "correct_answer": "个位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这家个位工作了十年。", "explanation": "这里应该用〈单位〉。个位指数字的位置，指工作的机构要用“单位”。"}, {"text": "个位同学，请注意听讲。", "explanation": "这里应该用〈各位〉。个位指数字的位置，称呼大家要用“各位”，二者同音却不能混用。"}, {"text": "我们在个位上吃饭。", "explanation": "这里应该用〈餐厅〉。个位指数字的位置，不是可以吃饭的场所，吃饭要去“餐厅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请个位上写一个五。", "corrected_sentence": "请在个位上写一个五。", "error_description": "错误形式：“请个位上写一个五”；正确形式：“请在个位上写一个五”。“个位”作处所时前面要加介词“在”，缺了“在”句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个数地个位是五。", "corrected_sentence": "这个数的个位是五。", "error_description": "错误形式：“这个数地个位是五”；正确形式：“这个数的个位是五”。“个位”前表示领属的修饰语要用“的”，用“地”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
