INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94465, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分内是应该自己做的事。", "primary_collocate": null, "pronunciation": "fèn nèi", "ipa": "fən˥˩ nei˥˩", "syllable_count": 2, "sentences": [{"text": "只要做好分内，老板就会满意。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连分内都没做完，还想去玩吗？", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把分内做好，再去帮别人。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照顾家人是他认为自己的分内。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分内的事应该自己做，别靠别人。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分内和分外，你要分清楚。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做完分内，还主动帮同事。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做好分内，是对工作负责的表现。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这是分内，不用谢。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只管自己的分内，别人的事我不管。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分内事", "label": "复合"}, {"form": "分内之事", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己本分应做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119b896a-7a6c-482d-97ff-7470b8956fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分内", "is_correct": true, "explanation": "正确：「做好分内」指做好自己应做的事，符合句意。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：「做」不与「玩笑」搭配，应说「开玩笑」。"}, {"text": "对手", "is_correct": false, "explanation": "语义：「对手」指竞争的人，不是可以做好的事情。"}, {"text": "闲事", "is_correct": false, "explanation": "语义：「闲事」是不该管的事，做好它不会让老板满意。"}], "explanations": {"分内": "正确：「做好分内」指做好自己应做的事，符合句意。", "玩笑": "搭配：「做」不与「玩笑」搭配，应说「开玩笑」。", "对手": "语义：「对手」指竞争的人，不是可以做好的事情。", "闲事": "语义：「闲事」是不该管的事，做好它不会让老板满意。"}, "sentence_index": 0, "correct_answer": "分内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于找到了一份分内，高兴极了。", "explanation": "这里应该用〈工作〉。分内指自己应做的事，不是可以找到的职位。"}, {"text": "他很分内，每次都按时完成任务。", "explanation": "这里应该用〈勤快〉。分内修饰的是事情，形容人做事的积极程度要用勤快。"}, {"text": "他接到了一封分内，立刻拆开看。", "explanation": "这里应该用〈信〉。分内是应该自己做的事，不是可以拆开看的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分内", "is_correct": true, "explanation": "正确：「做完分内」指做完自己应做的事，符合句意。"}, {"text": "病", "is_correct": false, "explanation": "搭配：「做」不与「病」搭配，应说「生病」。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：「做」不与「雨」搭配，应说「下雨」。"}, {"text": "理想", "is_correct": false, "explanation": "语义：「理想」是人的愿望，不能「做完」，与句意不符。"}], "explanations": {"分内": "正确：「做完分内」指做完自己应做的事，符合句意。", "病": "搭配：「做」不与「病」搭配，应说「生病」。", "雨": "搭配：「做」不与「雨」搭配，应说「下雨」。", "理想": "语义：「理想」是人的愿望，不能「做完」，与句意不符。"}, "sentence_index": 6, "correct_answer": "分内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去商店买了一个分内。", "explanation": "这里应该用〈东西〉。分内指应该自己做的事，是无形的责任，不能拿去买。"}, {"text": "他被调到新的分内上，压力很大。", "explanation": "这里应该用〈岗位〉。分内不说调到，调到的位置要用岗位。"}, {"text": "他有分内照顾年迈的父母。", "explanation": "这里应该用〈义务〉。有义务要说有义务，分内不用于说「有」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先做很分内，再去休息吧。", "corrected_sentence": "先做好分内，再去休息吧。", "error_description": "错误：「做很分内」。正确：「做好分内」。「好」是「做」的结果补语，不能换成程度副词「很」；「分内」是名词，不能被「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作是我分内地职责，我必须做好。", "corrected_sentence": "这份工作是我分内的职责，我必须做好。", "error_description": "错误：「分内地职责」。正确：「分内的职责」。「分内」修饰名词「职责」，定语后要用「的」，「地」用于状语，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分外", "is_correct": true, "explanation": "正确：「分外」指超出本分的，与「分内」相对。"}, {"text": "普通", "is_correct": false, "explanation": "「普通」指一般、不特别，与「分内」没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "「简单」指不复杂，与「分内」没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "「复杂」指头绪多、难理解，与「分内」没有反义关系。"}], "correct_answer": "分外", "explanations": {"分外": "正确：「分外」指超出本分的，与「分内」相对。", "普通": "「普通」指一般、不特别，与「分内」没有反义关系。", "简单": "「简单」指不复杂，与「分内」没有反义关系。", "复杂": "「复杂」指头绪多、难理解，与「分内」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分外", "is_correct": true, "explanation": "正确：「分外」指超出本分的，与「分内」相对。"}, {"text": "陌生", "is_correct": false, "explanation": "「陌生」指不熟悉，与「分内」没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "「宽敞」指空间大，与「分内」没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "「轻松」指不费力，与「分内」没有反义关系。"}], "correct_answer": "分外", "explanations": {"分外": "正确：「分外」指超出本分的，与「分内」相对。", "陌生": "「陌生」指不熟悉，与「分内」没有反义关系。", "宽敞": "「宽敞」指空间大，与「分内」没有反义关系。", "轻松": "「轻松」指不费力，与「分内」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本分以内的，应当做的。", "primary_collocate": null, "pronunciation": "fèn nèi", "ipa": "fən˥˩ nei˥˩", "syllable_count": 2, "sentences": [{"text": "照顾好病人是护士分内的工作。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些都是我分内的事，不用谢。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做好作业是学生分内的事。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只做分内的工作，从来不多管闲事。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫办公室是清洁工分内的责任。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助客人是服务员分内的事。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，认真上课是你们分内的事。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把分内的工作做完，才下班回家。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护公园的花草是管理员分内的工作。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不是我分内的事，你去问经理吧。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分内事", "label": "复合"}, {"form": "分内之事", "label": "复合"}], "register": "中性", "sense_fingerprint": "属于本分，应当做的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119b896a-7a6c-482d-97ff-7470b8956fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分内", "is_correct": true, "explanation": "正确：「分内」指属于本分、应当做的，照顾病人正是护士的本分。"}, {"text": "业余", "is_correct": false, "explanation": "语义：「业余」与「护士」的职业身份矛盾，照顾病人不是业余的工作。"}, {"text": "违法", "is_correct": false, "explanation": "语义：照顾病人是合法的职业工作，不能说违法的工作。"}, {"text": "圆形", "is_correct": false, "explanation": "搭配：「圆形」描述形状，不能修饰「工作」。"}], "explanations": {"分内": "正确：「分内」指属于本分、应当做的，照顾病人正是护士的本分。", "业余": "语义：「业余」与「护士」的职业身份矛盾，照顾病人不是业余的工作。", "违法": "语义：照顾病人是合法的职业工作，不能说违法的工作。", "圆形": "搭配：「圆形」描述形状，不能修饰「工作」。"}, "sentence_index": 0, "correct_answer": "分内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为人很分内，从不说谎。", "explanation": "这里应该用〈老实〉。分内只说事情或职责是否属于本分，不用来形容人的品性。"}, {"text": "这首歌很分内，听了很舒服。", "explanation": "这里应该用〈动听〉。分内只修饰事情，不用来形容歌曲的好听程度。"}, {"text": "他是个分内的人。", "explanation": "这里应该用〈本分〉。本分可以修饰人，分内只修饰事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分内", "is_correct": true, "explanation": "正确：「分内」指属于本分、应当做的，认真上课正是学生的本分。"}, {"text": "无关", "is_correct": false, "explanation": "语义：「无关」与「认真上课是你们的事」相矛盾。"}, {"text": "蓝色", "is_correct": false, "explanation": "搭配：「蓝色」是颜色，不能修饰「事」。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：上课是学生熟悉的事，用「陌生」与句意不符。"}], "explanations": {"分内": "正确：「分内」指属于本分、应当做的，认真上课正是学生的本分。", "无关": "语义：「无关」与「认真上课是你们的事」相矛盾。", "蓝色": "搭配：「蓝色」是颜色，不能修饰「事」。", "陌生": "语义：上课是学生熟悉的事，用「陌生」与句意不符。"}, "sentence_index": 6, "correct_answer": "分内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对客人很分内，主动帮忙。", "explanation": "这里应该用〈热情〉。分内只修饰事情，待人的态度要用热情。"}, {"text": "这把椅子很分内，坐着很舒服。", "explanation": "这里应该用〈舒适〉。分内只修饰事情，不用来形容物品，坐着的感受要用舒适。"}, {"text": "他做事分内，每件事都做好。", "explanation": "这里应该用〈认真〉。分内不用来形容一个人做事的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些工作都是我分内了的，别担心。", "corrected_sentence": "这些工作都是我分内的，别担心。", "error_description": "「分内」修饰名词时只用「的」，不能加「了」，应说「分内的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
