INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "制服是同一个学校或单位的人穿的一样的衣服。", "primary_collocate": null, "pronunciation": "zhì fú", "ipa": "ʈʂɻ̩⁵¹ fu³⁵", "syllable_count": 2, "sentences": [{"text": "我们学校的制服是蓝色的。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着新制服去上班。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个服务员都要穿制服。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿今天忘了带制服。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套制服太小了，我不能穿。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把制服洗干净了。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的制服上有学校的名字。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察穿着制服站在门口。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们公司的制服是什么颜色？", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上学的时候，我们每天都穿制服。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套制服", "label": "量词"}, {"form": "一身制服", "label": "量词"}], "register": "中性", "sense_fingerprint": "同一学校或单位的人穿的相同衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b1368f-3c85-4d4d-9d9f-204f7c23b63d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制服", "is_correct": true, "explanation": "正确答案。制服是同一学校或单位的人穿的一样的衣服。"}, {"text": "致富", "is_correct": false, "explanation": "zhì fù 与 zhì fú 只有末字声调不同（fù 第四声，fú 第二声），“致富”意思是使自己变得富有。"}, {"text": "字符", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），“字符”意思是文字、数字等符号。"}, {"text": "支付", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，fù（第四声）与 fú（第二声）声调也不同，“支付”意思是付钱。"}], "explanations": {"制服": "正确答案。制服是同一学校或单位的人穿的一样的衣服。", "致富": "zhì fù 与 zhì fú 只有末字声调不同（fù 第四声，fú 第二声），“致富”意思是使自己变得富有。", "字符": "zì 与 zhì 声母不同（z 与 zh），“字符”意思是文字、数字等符号。", "支付": "zhī（第一声）与 zhì（第四声）声调不同，fù（第四声）与 fú（第二声）声调也不同，“支付”意思是付钱。"}, "sentence_index": null, "correct_answer": "制服"}, "level_3": {"options": [{"text": "制服", "is_correct": true, "explanation": "正确答案。“制服”指学校统一规定的服装，可以是蓝色的。"}, {"text": "校长", "is_correct": false, "explanation": "语义：校长是人，不能说“是蓝色的”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是有颜色的东西，不能说“是蓝色的”。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“蓝色的”一般不修饰“成绩”，这样说不符合搭配习惯。"}], "explanations": {"制服": "正确答案。“制服”指学校统一规定的服装，可以是蓝色的。", "校长": "语义：校长是人，不能说“是蓝色的”。", "考试": "语义：考试不是有颜色的东西，不能说“是蓝色的”。", "成绩": "搭配：“蓝色的”一般不修饰“成绩”，这样说不符合搭配习惯。"}, "sentence_index": 0, "correct_answer": "制服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次去爬山，我特意买了一套制服。", "explanation": "这里应该用〈登山服〉。制服是统一规定式样的服装，爬山要穿登山服，不用“制服”。"}, {"text": "他结婚那天穿了一套制服。", "explanation": "这里应该用〈西服〉。制服指机关、学校等统一规定式样的服装，个人结婚时穿的西服不用“制服”。"}, {"text": "他周末去打篮球，特意穿了一套制服。", "explanation": "这里应该用〈运动服〉。打篮球要穿运动服，制服是统一规定式样的服装，不用于运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制服", "is_correct": true, "explanation": "正确答案。“制服”是统一式样的服装，可以写上学校的名字。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，不能在上面写学校的名字。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气上”不是可以写字的表面，“天气”与“上有……名字”不搭配。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是可以写字的物体，不能说“数学上有学校的名字”。"}], "explanations": {"制服": "正确答案。“制服”是统一式样的服装，可以写上学校的名字。", "声音": "语义：声音看不见，不能在上面写学校的名字。", "天气": "搭配：“天气上”不是可以写字的表面，“天气”与“上有……名字”不搭配。", "数学": "语义：数学是一门学科，不是可以写字的物体，不能说“数学上有学校的名字”。"}, "sentence_index": 6, "correct_answer": "制服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都穿着制服睡觉。", "explanation": "这里应该用〈睡衣〉。制服是统一规定式样的服装，睡觉时穿的衣服不用“制服”。"}, {"text": "他周末去跳舞，一直穿着制服。", "explanation": "这里应该用〈舞衣〉。跳舞要穿舞衣，制服是统一规定式样的服装，不用于跳舞。"}, {"text": "夏天我们去海边都穿着制服游泳。", "explanation": "这里应该用〈泳衣〉。游泳要穿泳衣，不能穿制服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他戴着一套制服去开会。", "corrected_sentence": "他穿着一套制服去开会。", "error_description": "动词搭配错误：穿制服应说“穿”，“戴”用于帽子、眼镜等，不能说“戴制服”。应改为“他穿着一套制服去开会。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天上班都穿着一把制服。", "corrected_sentence": "他每天上班都穿着一套制服。", "error_description": "量词错误：“制服”要用“套”或“身”，不能用“把”（“把”用于有柄的东西等）。应改为“一套制服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好看，耐看，看着舒服。", "primary_collocate": null, "pronunciation": "shòu kàn", "ipa": "ʂoʊ˥˩ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服颜色简单，穿起来很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子收拾得整齐，看上去很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她长得不算漂亮，可是很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画虽然简单，但是挺受看的。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新做的窗帘颜色很淡，十分受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上这身西装，特别受看。", "target_word": "受看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些花摆在桌上，真受看。", "target_word": "受看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裙子样子普通，却很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的字写得整齐，看起来很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的街道不大，却干净受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不受看", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "样子耐看，看着舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119b896a-7a6c-482d-97ff-7470b8956fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受看", "is_correct": true, "explanation": "正确：“受看”指样子耐看、看着舒服，可以用来描述“穿起来”的样子。"}, {"text": "花哨", "is_correct": false, "explanation": "语义：“花哨”指颜色、图案繁多，与前文“颜色简单”相矛盾。"}, {"text": "苦", "is_correct": false, "explanation": "语义：「苦」指味道，不能用来形容衣服穿起来的样子。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”说声音，不能用来形容衣服。"}], "explanations": {"受看": "正确：“受看”指样子耐看、看着舒服，可以用来描述“穿起来”的样子。", "花哨": "语义：“花哨”指颜色、图案繁多，与前文“颜色简单”相矛盾。", "苦": "语义：「苦」指味道，不能用来形容衣服穿起来的样子。", "吵": "语义：“吵”说声音，不能用来形容衣服。"}, "sentence_index": 0, "correct_answer": "受看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手在年轻人中很受看，演唱会的票很快就卖光了。", "explanation": "这里应该用〈受欢迎〉。受看只说样子好看，说一个人或事物被大家喜爱要用受欢迎。"}, {"text": "这个方案在公司里很受看，领导也很看重。", "explanation": "这里应该用〈受重视〉。受看说外表，不能用来表示被领导看重。"}, {"text": "这家餐厅的服务很受看，顾客都很满意。", "explanation": "这里应该用〈受好评〉。服务的好坏要说受好评，受看只形容样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受看", "is_correct": true, "explanation": "正确：“受看”指样子耐看，与“真”搭配，用来评价摆在桌上的花。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”指味道，不能用来形容花的样子。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”一般说味道，不能用来形容摆在桌上的花。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地，与花好看与否无关。"}], "explanations": {"受看": "正确：“受看”指样子耐看，与“真”搭配，用来评价摆在桌上的花。", "苦": "语义：“苦”指味道，不能用来形容花的样子。", "辣": "搭配：“辣”一般说味道，不能用来形容摆在桌上的花。", "硬": "语义：“硬”指质地，与花好看与否无关。"}, "sentence_index": 6, "correct_answer": "受看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题最近很受看，讨论的人越来越多。", "explanation": "这里应该用〈受关注〉。受看只说样子好看，表示问题引起大家注意要用受关注。"}, {"text": "这种产品很受看，订单多到做不完。", "explanation": "这里应该用〈受青睐〉。受看只说样子耐看，说产品被很多人喜爱、大量购买要用受青睐。"}, {"text": "这款包很受看，很多明星都在追捧它。", "explanation": "这里应该用〈受追捧〉。受看只形容外表，表示被热烈追捧要用受追捧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间小屋布置得简单，看上去比受看。", "corrected_sentence": "这间小屋布置得简单，看上去很受看。", "error_description": "错误：「比受看」。正确：「很受看」。「比」表示比较，需要比较对象；这里表示程度，应用程度副词「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这束花插很受看，放在窗台上。", "corrected_sentence": "这束花插得很受看，放在窗台上。", "error_description": "错误：“插很受看”，缺少补语标记“得”。正确：“插得很受看”。动词后接表示状态的补语时，中间要加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
