INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "呕吐：胃里的东西从嘴里涌出来。", "primary_collocate": null, "pronunciation": "tù", "ipa": "tʰu˥˩", "syllable_count": 1, "sentences": [{"text": "他坐船坐久了，吐得很厉害。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃多了，晚上吐了两次。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一闻到那个味道就想吐。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天喝了太多酒，他一直在吐。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发烧了，吃什么都吐。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得太快，弟弟吐了一路。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了坏东西，我又吐又拉肚子。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问她吐过几次。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吐得脸都白了。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐过山车以后，好几个人都吐了。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吐了", "label": "体标"}, {"form": "吐过", "label": "体标"}, {"form": "呕吐", "label": "复合"}], "register": "口语", "sense_fingerprint": "吐·tù·呕吐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f834fce6-8bd2-470f-a5c3-a80bfad7aa75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。吐（tù，第四声）是呕吐的意思。"}, {"text": "土", "is_correct": false, "explanation": "tǔ（第三声）与 tù 声调不同，意思是泥土。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tù 声调不同，意思是突然。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 tù 声调不同，意思是图画。"}], "explanations": {"吐": "正确。吐（tù，第四声）是呕吐的意思。", "土": "tǔ（第三声）与 tù 声调不同，意思是泥土。", "突": "tū（第一声）与 tù 声调不同，意思是突然。", "图": "tú（第二声）与 tù 声调不同，意思是图画。"}, "sentence_index": null, "correct_answer": "吐"}, "level_3": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。“吐得很厉害”说的是坐船后呕吐得厉害。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是歌唱，与坐船后的身体不适无关。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写得很厉害”说的是写字，不能用来描述身体反应。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”是在水里活动，句子说的是坐船后的不适，不能说“游得很厉害”。"}], "explanations": {"吐": "正确。“吐得很厉害”说的是坐船后呕吐得厉害。", "唱": "语义：“唱”是歌唱，与坐船后的身体不适无关。", "写": "搭配：“写得很厉害”说的是写字，不能用来描述身体反应。", "游": "语义：“游”是在水里活动，句子说的是坐船后的不适，不能说“游得很厉害”。"}, "sentence_index": 0, "correct_answer": "吐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吐了两声，喉咙很痛。", "explanation": "这里应该用〈咳〉。吐指呕吐或把东西弄出来，不能用来表示发出咳嗽的声音。"}, {"text": "他热得直吐汗。", "explanation": "这里应该用〈流〉。汗是从皮肤流出来的，不能说吐汗。"}, {"text": "他把书吐在了桌子上。", "explanation": "这里应该用〈放〉。吐指呕吐或把嘴里的东西弄出来，书不是从嘴里出来的，要用放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。吐（tù，第四声）是呕吐的意思。"}, {"text": "度", "is_correct": false, "explanation": "dù 与 tù 声母不同（d 与 t），意思是程度。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tù 声调不同，意思是没有头发。"}, {"text": "涂", "is_correct": false, "explanation": "tú（第二声）与 tù 声调不同，意思是涂抹。"}], "explanations": {"吐": "正确。吐（tù，第四声）是呕吐的意思。", "度": "dù 与 tù 声母不同（d 与 t），意思是程度。", "秃": "tū（第一声）与 tù 声调不同，意思是没有头发。", "涂": "tú（第二声）与 tù 声调不同，意思是涂抹。"}, "sentence_index": null, "correct_answer": "吐"}, "level_3": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。“又吐又拉肚子”描述的是吃了坏东西后的呕吐和腹泻。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”与拉肚子不搭，这里描述的是身体不适。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备别人，与吃坏东西后的症状无关。"}, {"text": "数", "is_correct": false, "explanation": "搭配：“又数又拉肚子”不通，“数”不能描述身体的症状。"}], "explanations": {"吐": "正确。“又吐又拉肚子”描述的是吃了坏东西后的呕吐和腹泻。", "笑": "语义：“笑”与拉肚子不搭，这里描述的是身体不适。", "骂": "语义：“骂”是责备别人，与吃坏东西后的症状无关。", "数": "搭配：“又数又拉肚子”不通，“数”不能描述身体的症状。"}, "sentence_index": 6, "correct_answer": "吐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他哭得一脸的眼泪都吐了出来。", "explanation": "这里应该用〈流〉。“吐”指呕吐或把嘴里的东西弄出来，眼泪应该用流。"}, {"text": "他哭了一晚上，吐了一地的头发。", "explanation": "这里应该用〈掉〉。“吐”指把嘴里的东西弄出来，头发掉落要用掉。"}, {"text": "他把一百块钱吐给了老板。", "explanation": "这里应该用〈付〉。“吐”指呕吐或把嘴里的东西弄出来，付钱要用付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她发烧了，吐很厉害。", "corrected_sentence": "她发烧了，吐得很厉害。", "error_description": "补语缺少“得”：说“吐得很厉害”时必须用“得”把补语接在动词后面，直接说“吐很厉害”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喝醉以后吐了过两次。", "corrected_sentence": "他喝醉以后吐过两次。", "error_description": "体标顺序错误：“吐过”的“过”表示经历，“了”与“过”不能同时出现在动词后，应说“吐过两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
