INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "向前是朝着前面的方向走。", "primary_collocate": null, "pronunciation": "xiàng qián", "ipa": "ɕjɑŋ˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "请大家向前走三步。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向前走了几步，路上一个人也没有。", "target_word": "向前", "complexity_tier": "T3", "furigana": "tā xiàng qián zǒu le jǐ bù, lù shàng yí gè rén yě méi yǒu.", "sentence_source": "generated"}, {"text": "队伍慢慢向前走着。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机说，请向前走，不要停。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们向前跑，想先到河边。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开了，他向前迈了一步。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪很大，我们还是向前走。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让第一排的同学向前站。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向前走了几步，看见一座桥。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一亮，大家就向前走。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向前走", "label": "复合"}], "register": "中性", "sense_fingerprint": "向前·xiàng qián·朝着前面的方向走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f834fce6-8bd2-470f-a5c3-a80bfad7aa75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久持续，与“走三步”这种有限的动作不合。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”表示意外发生，不能与“请大家……走三步”这类指令搭配。"}, {"text": "向前", "is_correct": true, "explanation": "向前：表示朝前方走，与“走三步”搭配，是指示大家朝前走的动作。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“请大家”的要求不合。"}], "explanations": {"永远": "语义：“永远”表示长久持续，与“走三步”这种有限的动作不合。", "突然": "搭配：“突然”表示意外发生，不能与“请大家……走三步”这类指令搭配。", "向前": "向前：表示朝前方走，与“走三步”搭配，是指示大家朝前走的动作。", "偶尔": "语义：“偶尔”表示不常发生，与“请大家”的要求不合。"}, "sentence_index": 0, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向前在屋里坐了一下午。", "explanation": "这里不应用〈向前〉。“向前”只表示朝前方的移动，不表示动作的持续；动作持续要说〈一直〉。"}, {"text": "这个问题我向前想了很久。", "explanation": "这里不应用〈向前〉。“向前”表示空间方向，思考没有位移；想问题的程度要说〈认真〉或〈反复〉。"}, {"text": "他向前退了两步，挡在门口。", "explanation": "这里应该用〈向后〉。“退”是向后移动，与“向前”的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已完成，与“还是”表示仍然相悖。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”多用于叮嘱，与“还是”的陈述语气不合。"}, {"text": "向前", "is_correct": true, "explanation": "向前：朝前方走，与“我们还是……走”搭配，表示雪大仍然朝前走。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突发，与“还是”表示持续的语气不搭配。"}], "explanations": {"已经": "语义：“已经”表示已完成，与“还是”表示仍然相悖。", "千万": "语义：“千万”多用于叮嘱，与“还是”的陈述语气不合。", "向前": "向前：朝前方走，与“我们还是……走”搭配，表示雪大仍然朝前走。", "忽然": "搭配：“忽然”表示突发，与“还是”表示持续的语气不搭配。"}, "sentence_index": 6, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师向前布置了作业。", "explanation": "这里应该用〈提前〉。“向前”只表示空间上朝前，不表示时间上的提前；布置作业的早晚要说〈提前〉。"}, {"text": "我们向前再说吧。", "explanation": "这里应该用〈以后〉。“向前”只表示朝前方的空间方向，不表示将来的时间；“再说”的时间要说〈以后〉。"}, {"text": "这次比赛他向前拿到了冠军。", "explanation": "这里不应用〈向前〉。“向前”只表示空间方向，表示名次要说“第一”或“名列前茅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他慢慢向前了走，没有回头。", "corrected_sentence": "他慢慢向前走，没有回头。", "error_description": "多加了“了”：“向前”后面直接接动词“走”，中间不能插入“了”，应说“向前走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人慢慢了向前走，手里拿着拐杖。", "corrected_sentence": "老人慢慢向前走，手里拿着拐杖。", "error_description": "“了”位置错误：“了”不能插在“慢慢”和“向前”之间，此处不需要“了”，应说“老人慢慢向前走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "朝前方；往前进。", "primary_collocate": null, "pronunciation": "xiàng qián", "ipa": "ɕjɑŋ˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "车慢慢向前开，路上有点堵。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管有多难，我们都要向前看。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在大风里一直向前行。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力向前推，门终于开了。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们互相帮助，一步一步向前。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时，身体要向前倾一点。", "target_word": "向前", "complexity_tier": "T3", "furigana": "pǎo bù shí, shēn tǐ yào xiàng qián qīng yì diǎn.", "sentence_source": "generated"}, {"text": "她向前伸出手，想拉住孩子。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，大家都向前冲。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活就要向前，不要停在原地。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车向前开动，站台越来越远。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向前走", "label": "复合"}], "register": "中性", "sense_fingerprint": "向前·xiàng qián·朝前方、往前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f834fce6-8bd2-470f-a5c3-a80bfad7aa75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“慢慢”的持续缓慢相矛盾。"}, {"text": "向前", "is_correct": true, "explanation": "向前：表示朝前方行进，与“车慢慢开”搭配，描述车朝前慢行。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”表示瞬间完成，不能与“慢慢”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与车持续慢开、路上堵车的情景不合。"}], "explanations": {"突然": "语义：“突然”表示事情忽然发生，与“慢慢”的持续缓慢相矛盾。", "向前": "向前：表示朝前方行进，与“车慢慢开”搭配，描述车朝前慢行。", "一下子": "搭配：“一下子”表示瞬间完成，不能与“慢慢”搭配。", "偶尔": "语义：“偶尔”表示不常发生，与车持续慢开、路上堵车的情景不合。"}, "sentence_index": 0, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向前睡觉，一直睡到中午。", "explanation": "这里不应用〈向前〉。“向前”只表示朝前方的空间移动，睡觉不涉及位移，也不表示先后；动作在先要说〈先〉。"}, {"text": "我向前喜欢这首歌，每天都听。", "explanation": "这里应该用〈很〉。“向前”只表示朝前的空间方向，不表示喜欢的程度；表示喜欢的程度要用〈很〉。"}, {"text": "他向前拒绝了这份工作。", "explanation": "这里不应用〈向前〉。“向前”只表示朝前方的空间移动，不能修饰“拒绝”这类与位移无关的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求多个主体共同行动，“她”单独一人不能“一起伸出手”。"}, {"text": "向前", "is_correct": true, "explanation": "向前：表示朝前方伸出，与“想拉住孩子”的动作一致。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”多用于叮嘱或劝阻，与叙述“伸出手”这一动作不合。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久持续，与“伸出手”这一次性动作不合。"}], "explanations": {"一起": "搭配：“一起”要求多个主体共同行动，“她”单独一人不能“一起伸出手”。", "向前": "向前：表示朝前方伸出，与“想拉住孩子”的动作一致。", "千万": "语义：“千万”多用于叮嘱或劝阻，与叙述“伸出手”这一动作不合。", "永远": "语义：“永远”表示长久持续，与“伸出手”这一次性动作不合。"}, "sentence_index": 6, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向前在北京工作过，后来才调走。", "explanation": "这里应该用〈以前〉。“向前”只表示空间上朝前，不表示过去的时间；过去的经历要说〈以前〉。"}, {"text": "他向前退了一步，差点撞到墙上。", "explanation": "这里应该用〈向后〉。“退”是向后移动，与“向前”的方向相反，两者不能搭配。"}, {"text": "这次考试他向前拿了第一名。", "explanation": "这里不应用〈向前〉。“向前”只表示空间方向，表示名次靠前要说“第一”或“名列前茅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她向前了走两步，停了下来。", "corrected_sentence": "她向前走了两步，停了下来。", "error_description": "错误形式：向前了走；正确形式：向前走了。“了”应放在动词之后，表示动作完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一直向进。", "corrected_sentence": "我们一直向前进。", "error_description": "漏字：“向前”少写了“前”，“向”后须接方向成分，应为“一直向前进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb901d60-4293-40bc-b31e-475b9b6d552e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种极小的长度单位，等于十的负十次方米（即十分之一纳米），用于量原子、波长等极小的距离。", "primary_collocate": null, "pronunciation": "āi", "ipa": "ai̯˥", "syllable_count": 1, "sentences": [{"text": "一埃等于十分之一纳米。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氢原子的直径大约是一埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种光的波长只有几千埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用埃来量原子之间的距离。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个原子相隔约两埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个晶体里，原子的间距是三埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一埃非常短，眼睛根本看不到。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水分子的大小只有几埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，一米等于一百亿埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写道：一埃是十的负十次方米。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "长度单位埃，用于量原子、波长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f23a97a0-1d54-4234-ade3-1bbe96a40f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃（āi，第一声）是本条目所教的长度单位。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。"}, {"text": "爱", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是喜欢。"}, {"text": "挨", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是靠近或遭受。"}], "explanations": {"埃": "埃（āi，第一声）是本条目所教的长度单位。", "矮": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。", "爱": "ài（第四声）与 āi（第一声）声调不同，意思是喜欢。", "挨": "ái（第二声）与 āi（第一声）声调不同，意思是靠近或遭受。"}, "sentence_index": null, "correct_answer": "埃"}, "level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃是长度单位，约为十分之一纳米，与句中的换算关系一致，正确。"}, {"text": "米", "is_correct": false, "explanation": "语义：米比纳米大十亿倍，“一米等于十分之一纳米”与事实不符，句意不通。"}, {"text": "毫米", "is_correct": false, "explanation": "语义：毫米远大于埃，一毫米不可能只等于十分之一纳米。"}, {"text": "纳米", "is_correct": false, "explanation": "搭配：句末已用纳米作比较标准，前面再用纳米自比，“一纳米等于十分之一纳米”没有意义。"}], "explanations": {"埃": "埃是长度单位，约为十分之一纳米，与句中的换算关系一致，正确。", "米": "语义：米比纳米大十亿倍，“一米等于十分之一纳米”与事实不符，句意不通。", "毫米": "语义：毫米远大于埃，一毫米不可能只等于十分之一纳米。", "纳米": "搭配：句末已用纳米作比较标准，前面再用纳米自比，“一纳米等于十分之一纳米”没有意义。"}, "sentence_index": 0, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高是一百七十埃。", "explanation": "这里应该用〈厘米〉。埃是极小的长度单位，只用于原子、波长等微观距离，人的身高要用厘米。"}, {"text": "这袋大米重五埃。", "explanation": "这里应该用〈千克〉。埃是长度单位，只用于原子、波长等极小的长度，不能表示重量。"}, {"text": "我们等了五埃才上车。", "explanation": "这里应该用〈分钟〉。埃是长度单位，不能用来计算时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃（āi，第一声）是本条目所教的长度单位。"}, {"text": "艾", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}, {"text": "开", "is_correct": false, "explanation": "kāi 与 āi 声母不同，声调相同，意思是打开。"}], "explanations": {"埃": "埃（āi，第一声）是本条目所教的长度单位。", "艾": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。", "癌": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。", "开": "kāi 与 āi 声母不同，声调相同，意思是打开。"}, "sentence_index": null, "correct_answer": "埃"}, "level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃是极小的长度单位，与“非常短，眼睛根本看不到”相符，正确。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里远比埃长，与“非常短”矛盾，也不符合“眼睛根本看不到”。"}, {"text": "千米", "is_correct": false, "explanation": "语义：千米同样是很长的距离，与“非常短”矛盾。"}, {"text": "光年", "is_correct": false, "explanation": "搭配：光年是天文距离单位，用来形容极远的距离，与句中“非常短”冲突。"}], "explanations": {"埃": "埃是极小的长度单位，与“非常短，眼睛根本看不到”相符，正确。", "公里": "语义：公里远比埃长，与“非常短”矛盾，也不符合“眼睛根本看不到”。", "千米": "语义：千米同样是很长的距离，与“非常短”矛盾。", "光年": "搭配：光年是天文距离单位，用来形容极远的距离，与句中“非常短”冲突。"}, "sentence_index": 6, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的电费是五十埃。", "explanation": "这里应该用〈元〉。埃是长度单位，不能用来表示钱款，电费的数目要用元来计。"}, {"text": "这间房的面积是五十埃。", "explanation": "这里应该用〈平方米〉。埃是长度单位，不能直接表示面积。"}, {"text": "这辆车每小时跑三埃。", "explanation": "这里应该用〈千米〉。埃表示长度，不能表示速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这层膜的厚度大约是五十个埃。", "corrected_sentence": "这层膜的厚度大约是五十埃。", "error_description": "错误形式：五十个埃；正确形式：五十埃。埃是长度单位，数词后直接接埃，不能再加量词个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种晶体的间距约为埃五。", "corrected_sentence": "这种晶体的间距约为五埃。", "error_description": "错误形式：埃五；正确形式：五埃。数词应放在单位之前，埃是长度单位，要说五埃。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c7249b-68b3-4546-8ec3-81d6de8ebd4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
