INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定的时间、地点和情况。", "primary_collocate": null, "pronunciation": "chǎng hé", "ipa": "ʈʂʰaŋ˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "在正式的场合，你应该穿西装。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种场合不适合开玩笑。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公共场合大声说话，大家都看他。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加婚礼这样的场合，要穿得整齐一点。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的场合，要说不同的话。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人很多的场合，他紧张得说不出话。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是工作场合，请不要聊私事。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢在吵闹的场合吃饭。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重要的比赛是严肃的场合，大家都很认真。", "target_word": "场合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在朋友聚会的场合，你可以随便一点。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共场合", "label": "复合"}, {"form": "場合", "label": "繁体"}], "register": "中性", "sense_fingerprint": "特定的时间、地点和情况，如正式场合、公共场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场合", "is_correct": true, "explanation": "场合：指特定的时间、地点和情况，可以说“正式的场合”。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”是具体的东西，不能说“正式的食物”，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然事物，不能用“正式的”来修饰。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“正式的”不修饰“价格”，“正式的价格”不是常见说法。"}], "explanations": {"场合": "场合：指特定的时间、地点和情况，可以说“正式的场合”。", "食物": "语义：“食物”是具体的东西，不能说“正式的食物”，句子不通。", "河流": "语义：“河流”是自然事物，不能用“正式的”来修饰。", "价格": "搭配：“正式的”不修饰“价格”，“正式的价格”不是常见说法。"}, "sentence_index": 0, "correct_answer": "场合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个健身场合每天开到晚上十点。", "explanation": "这里应该用〈场所〉。场合指时间、地点和情况，不是可以营业的场地，不能说“场合开到晚上十点”。"}, {"text": "比赛开始后，场合非常激烈。", "explanation": "这里应该用〈场面〉。场面指眼前的情景，可以说“激烈”；场合指时间、地点和情况，不能说“场合非常激烈”。"}, {"text": "我的场合很干净，昨天刚打扫过。", "explanation": "这里应该用〈房间〉。场合是抽象的时间、地点和情况，不能指可以打扫的具体房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场合", "is_correct": true, "explanation": "场合：指特定的时间、地点和情况，“工作场合”是常见说法。"}, {"text": "花园", "is_correct": false, "explanation": "语义：这里讲的是工作时的情境，“花园”不是情境，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“工作”不修饰“天气”，“工作天气”不能说。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”是食物，不能作为“请不要聊私事”所依据的情境。"}], "explanations": {"场合": "场合：指特定的时间、地点和情况，“工作场合”是常见说法。", "花园": "语义：这里讲的是工作时的情境，“花园”不是情境，句子不通。", "天气": "搭配：“工作”不修饰“天气”，“工作天气”不能说。", "饭菜": "语义：“饭菜”是食物，不能作为“请不要聊私事”所依据的情境。"}, "sentence_index": 6, "correct_answer": "场合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "场合上有很多学生在跑步。", "explanation": "这里应该用〈操场〉。场合不是可以跑步的场地，“场合上”不成立。"}, {"text": "场合里很安静，大家都在学习。", "explanation": "这里应该用〈教室〉。场合不指房间，不能说“场合里很安静”。"}, {"text": "这个场合坏了，你别坐。", "explanation": "这里应该用〈椅子〉。场合指时间、地点和情况，不是可以坐的家具，不能说“场合坏了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在每场合，他都很有礼貌。", "corrected_sentence": "在每个场合，他都很有礼貌。", "error_description": "错误：“每场合”。“每”后接名词要带量词，应说“每个场合”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张场合，大家都要注意礼貌。", "corrected_sentence": "那种场合，大家都要注意礼貌。", "error_description": "错误：“那张场合”。“张”用于平面物，不能修饰“场合”。应说“那种场合”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
