INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "古代君主把土地分给贵族管理的社会制度。", "primary_collocate": null, "pronunciation": "fēng jiàn", "ipa": "fɤŋ⁵⁵ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "古代的封建制度让贵族管理土地。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的封建社会有两千多年。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "封建国家的君主把土地分给贵族。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究中国古代的封建制度。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在封建社会，贵族有很大的权力。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城是封建时期留下来的。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，封建社会的土地归君主所有。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧洲的封建贵族住在城堡里。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "封建时代的君主要靠贵族管理国家。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上我们学过封建制度。", "target_word": "封建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封建社会", "label": "复合"}, {"form": "封建制度", "label": "复合"}, {"form": "封建时代", "label": "复合"}], "register": "书面", "sense_fingerprint": "古代君主分土地给贵族管理的社会制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b1368f-3c85-4d4d-9d9f-204f7c23b63d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "封建", "is_correct": true, "explanation": "正确答案。“封建制度”指古代君主把土地分给贵族管理的社会制度。"}, {"text": "民主", "is_correct": false, "explanation": "语义：民主制度下贵族不会替君主管理土地，与句中的“古代”语境不符。"}, {"text": "现代", "is_correct": false, "explanation": "语义：“古代的现代制度”自相矛盾。"}, {"text": "电子", "is_correct": false, "explanation": "搭配：“电子制度”不是常用说法，不能用来修饰“古代”的制度。"}], "explanations": {"封建": "正确答案。“封建制度”指古代君主把土地分给贵族管理的社会制度。", "民主": "语义：民主制度下贵族不会替君主管理土地，与句中的“古代”语境不符。", "现代": "语义：“古代的现代制度”自相矛盾。", "电子": "搭配：“电子制度”不是常用说法，不能用来修饰“古代”的制度。"}, "sentence_index": 0, "correct_answer": "封建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古代的封建制度让人民每四年投票选出君主。", "explanation": "这里应该用〈民主〉。封建制度是君主把土地分给贵族，不是由人民投票选出君主，这里应该说“民主制度”。"}, {"text": "古代的封建住在大宫殿里。", "explanation": "这里应该用〈君主〉。“封建”指制度，不指人，不能说它住在大宫殿里。"}, {"text": "这个国家历史上有过封建的工厂。", "explanation": "这里应该用〈近代〉。封建是古代分封土地的制度，不能用来修饰近代工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封建", "is_correct": true, "explanation": "正确答案。“封建社会”的土地归君主所有，符合这一历史情形。"}, {"text": "资本主义", "is_correct": false, "explanation": "语义：资本主义社会的土地归君主所有，与历史情形相矛盾。"}, {"text": "社会主义", "is_correct": false, "explanation": "语义：社会主义社会的土地归集体，不归君主所有。"}, {"text": "老百姓", "is_correct": false, "explanation": "搭配：“老百姓”不能修饰“社会”，“老百姓社会”不成词。"}], "explanations": {"封建": "正确答案。“封建社会”的土地归君主所有，符合这一历史情形。", "资本主义": "语义：资本主义社会的土地归君主所有，与历史情形相矛盾。", "社会主义": "语义：社会主义社会的土地归集体，不归君主所有。", "老百姓": "搭配：“老百姓”不能修饰“社会”，“老百姓社会”不成词。"}, "sentence_index": 6, "correct_answer": "封建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个封建每天在工厂里工作八小时。", "explanation": "这里应该用〈工人〉。“封建”指制度，不指人，不能去工厂工作。"}, {"text": "封建每天在教室里给学生讲课。", "explanation": "这里应该用〈老师〉。“封建”指制度，不指人，不能给学生讲课。"}, {"text": "历史课上我们学过封建的股票市场。", "explanation": "这里应该用〈资本主义〉。股票市场属于资本主义经济，封建社会没有，不能用“封建”修饰它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中国古代的一只封建制度持续了很久。", "corrected_sentence": "中国古代的一种封建制度持续了很久。", "error_description": "量词错误：“封建制度”前应用“种”，不能用“只”（“只”用于鸟、猫等动物或成对的东西中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古代的国家实行过一只封建制度。", "corrected_sentence": "古代的国家实行过一种封建制度。", "error_description": "量词错误：“封建制度”前应用“种”，不能用“只”（“只”用于鸟、猫等动物或成对的东西中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
