INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94495, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94495, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专利是发明人自己想出的新东西，别人不能随便学着做。", "primary_collocate": null, "pronunciation": "zhuān lì", "ipa": "ʈʂwan˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个新机器有专利，别人不能随便做。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出了一个好办法，这个办法就是他的专利。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司有很多专利。", "target_word": "专利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个专利是他的，你不能随便用。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个专利是我爸爸想出来的。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的新发明很受欢迎，很多人都想仿做她的专利。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种杯子有专利，别的店不能卖。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的专利很有用，很多人想买。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法有专利，你得先问他。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，好想法也可以变成专利。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "专利权", "label": "复合"}, {"form": "專利", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：自己想出的新东西，别人不能随便仿做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94495, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专利", "is_correct": true, "explanation": "“专利”指受法律保护的新发明，与“别人不能随便做”相呼应。"}, {"text": "缺点", "is_correct": false, "explanation": "语义：“缺点”与后句“别人不能随便做”没有关联，句子不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，不能用来说机器“有”它，与后句也没有关联。"}, {"text": "诏令", "is_correct": false, "explanation": "语域：“诏令”是古代的文书用语，不用于描述现代的机器。"}], "explanations": {"专利": "“专利”指受法律保护的新发明，与“别人不能随便做”相呼应。", "缺点": "语义：“缺点”与后句“别人不能随便做”没有关联，句子不通。", "工资": "语义：“工资”是劳动报酬，不能用来说机器“有”它，与后句也没有关联。", "诏令": "语域：“诏令”是古代的文书用语，不用于描述现代的机器。"}, "sentence_index": 0, "correct_answer": "专利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的专利归他所有，别人不能随便用。", "explanation": "这里应该用〈版权〉。专利保护的是技术发明，歌曲等作品要用“版权”。"}, {"text": "这幅画的专利很好看，大家都想买。", "explanation": "这里应该用〈著作权〉。画作等艺术作品的权利要用“著作权”，专利保护的是技术发明。"}, {"text": "这套房子的专利已经过户到他的名下了。", "explanation": "这里应该用〈产权〉。专利保护的是发明成果，房屋的所有权和过户要用“产权”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专利", "is_correct": true, "explanation": "“专利”指受法律保护的发明，所以别的店不能卖，与句意相符。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于食物或饮品，杯子不说“有口味”。"}, {"text": "诗意", "is_correct": false, "explanation": "语域：“诗意”是文学用语，不能用来说明杯子能否被售卖。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“别的店不能卖”没有因果关系，句子不通。"}], "explanations": {"专利": "“专利”指受法律保护的发明，所以别的店不能卖，与句意相符。", "口味": "搭配：“口味”用于食物或饮品，杯子不说“有口味”。", "诗意": "语域：“诗意”是文学用语，不能用来说明杯子能否被售卖。", "颜色": "语义：“颜色”与“别的店不能卖”没有因果关系，句子不通。"}, "sentence_index": 6, "correct_answer": "专利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个品牌的专利是他注册的。", "explanation": "这里应该用〈商标〉。品牌名称受保护要用“商标”，专利保护的是技术发明。"}, {"text": "他把这个专利拍成了电影，很多人去看。", "explanation": "这里应该用〈剧本〉。专利保护的是技术发明，能拍成电影的是剧本、小说等作品。"}, {"text": "这部小说的专利属于作者。", "explanation": "这里应该用〈著作权〉。作品的权利要用“著作权”，专利保护的是技术发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他申请了一只专利。", "corrected_sentence": "他申请了一项专利。", "error_description": "错误形式：量词用了“只”。正确形式：专利的量词是“项”，应为“一项专利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种杯子有一本专利，别的店不能卖。", "corrected_sentence": "这种杯子有一项专利，别的店不能卖。", "error_description": "错误形式：量词用了“本”。正确形式：专利的量词是“项”，应为“一项专利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
