INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家授予发明者在一定期限内独占使用其发明的权利。", "primary_collocate": null, "pronunciation": "zhuān lì", "ipa": "ʈʂwan˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "国家给这项发明颁发了专利。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专利的保护期一般是二十年。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司在十年前获得了这项专利。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专利到期后，别人也可以使用这项技术。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把专利卖给了一家大公司。", "target_word": "专利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项发明已经获得国家专利。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有专利，别人就能免费使用这项技术。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "申请专利要向国家交费，还要等很长时间。", "target_word": "专利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专利保护发明人在一定时间内的权利。", "target_word": "专利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司靠专利每年赚很多钱。", "target_word": "专利", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "专利权", "label": "复合"}, {"form": "專利", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词：国家授予发明者的限期独占权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专利", "is_correct": true, "explanation": "国家颁发给发明者的是专利证书性质的权利，与“这项发明”相呼应。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：“冠军”指比赛的名次，不是国家颁给发明的东西。"}, {"text": "口号", "is_correct": false, "explanation": "语义：“口号”是宣传用语，不能由国家颁发给发明。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是艺术作品，与“这项发明”不相关，不能被颁发。"}], "explanations": {"专利": "国家颁发给发明者的是专利证书性质的权利，与“这项发明”相呼应。", "冠军": "语义：“冠军”指比赛的名次，不是国家颁给发明的东西。", "口号": "语义：“口号”是宣传用语，不能由国家颁发给发明。", "歌曲": "语义：“歌曲”是艺术作品，与“这项发明”不相关，不能被颁发。"}, "sentence_index": 0, "correct_answer": "专利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个品牌的专利已经注册十年了。", "explanation": "这里应该用〈商标〉。品牌名称受保护要用“商标”，专利保护的是技术发明。"}, {"text": "这部小说的专利保护期是五十年。", "explanation": "这里应该用〈著作权〉。作品的保护期要用“著作权”，专利保护的是技术发明。"}, {"text": "这套房子的专利涨了很多，我们买不起。", "explanation": "这里应该用〈房价〉。专利指受保护的发明，房子的价钱要用“房价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专利", "is_correct": true, "explanation": "有受保护的专利，别人就不能免费使用这项技术，与句意相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”与能否免费使用技术无关，句子不通。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”不能决定技术能否被免费使用，与后句没有关联。"}, {"text": "诏书", "is_correct": false, "explanation": "语域：“诏书”是古代的文书，不用于现代的技术保护说明。"}], "explanations": {"专利": "有受保护的专利，别人就不能免费使用这项技术，与句意相符。", "温度": "语义：“温度”与能否免费使用技术无关，句子不通。", "口音": "语义：“口音”不能决定技术能否被免费使用，与后句没有关联。", "诏书": "语域：“诏书”是古代的文书，不用于现代的技术保护说明。"}, "sentence_index": 6, "correct_answer": "专利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的专利在市中心。", "explanation": "这里应该用〈地址〉。专利指受法律保护的发明，公司所在的位置要用“地址”。"}, {"text": "这次旅行的专利很紧，每天都要赶路。", "explanation": "这里应该用〈行程〉。专利指受保护的发明，旅行的安排要用“行程”。"}, {"text": "这首歌靠专利每年赚很多钱。", "explanation": "这里应该用〈版权〉。歌曲等作品的收益要用“版权”，专利保护的是技术发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司获得了一座专利。", "corrected_sentence": "公司获得了一项专利。", "error_description": "错误形式：量词用了“座”。正确形式：专利的量词是“项”，应为“一项专利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司有一把专利，靠它赚钱。", "corrected_sentence": "这家公司有一项专利，靠它赚钱。", "error_description": "错误形式：量词用了“把”。正确形式：专利的量词是“项”，应为“一项专利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
