INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "询问做什么事情或为什么这样做。", "primary_collocate": null, "pronunciation": "gàn shén me", "ipa": "kan˥˩ ʂən˧˥ mɤ", "syllable_count": 3, "sentences": [{"text": "你找我干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "都十点了，你还出去干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么晚打电话来，是想干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着刀站在门口，到底要干什么？", "target_word": "干什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下这么大的雨，你出去干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你整天不上课，到底都干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你站在那里不动，干什么呢？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没钱还买这么贵的包，干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我又没做错事，你骂我干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都在笑，你哭干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "幹什麼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "口语中询问目的或原因，带有不解或不满的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干什么", "is_correct": true, "explanation": "干什么：询问目的或原因，此处语义和语境都吻合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：句子问的是找我的目的，“谁”问的是人，句意不通。"}, {"text": "这样", "is_correct": false, "explanation": "搭配：“找我”后接“这样”不成句。"}, {"text": "天平", "is_correct": false, "explanation": "语义：“天平”是称重的器具，不能作为“找我”的对象，句子不通。"}], "explanations": {"干什么": "干什么：询问目的或原因，此处语义和语境都吻合。", "谁": "语义：句子问的是找我的目的，“谁”问的是人，句意不通。", "这样": "搭配：“找我”后接“这样”不成句。", "天平": "语义：“天平”是称重的器具，不能作为“找我”的对象，句子不通。"}, "sentence_index": 0, "correct_answer": "干什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喜欢干什么类型的电影？", "explanation": "这里应该用〈哪种〉。干什么不能修饰“类型”，应说“他喜欢哪种类型的电影”。"}, {"text": "这东西要放在干什么位置？", "explanation": "这里应该用〈哪个〉。干什么不表示位置，应说“这东西要放在哪个位置”。"}, {"text": "我们班是干什么年级的？", "explanation": "这里应该用〈哪个〉。干什么不能修饰“年级”，应说“我们班是哪个年级的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干什么", "is_correct": true, "explanation": "干什么：询问原因，带有不满的语气，此处语义和语境都吻合。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：句子问的是原因，“哪儿”问的是地点，句意不通。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问的是数量，句子问的是为什么不动。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“不动，”后接“这么呢”不成句。"}], "explanations": {"干什么": "干什么：询问原因，带有不满的语气，此处语义和语境都吻合。", "哪儿": "语义：句子问的是原因，“哪儿”问的是地点，句意不通。", "多少": "语义：“多少”问的是数量，句子问的是为什么不动。", "这么": "搭配：“不动，”后接“这么呢”不成句。"}, "sentence_index": 6, "correct_answer": "干什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是干什么品牌的包？", "explanation": "这里应该用〈哪家〉。干什么不能修饰“品牌”，应说“这是哪家的包”。"}, {"text": "我们应该向干什么方向出发？", "explanation": "这里应该用〈哪边〉。干什么不能修饰“方向”，应说“我们应该向哪边出发”。"}, {"text": "他是干什么学校的老师？", "explanation": "这里应该用〈哪所〉。干什么不能修饰“学校”，应说“他是哪所学校的老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么晚了，你还不睡，干什么吗？", "corrected_sentence": "这么晚了，你还不睡，干什么呢？", "error_description": "错误：“干什么”后用了“吗”。“干什么”已是疑问代词，句末不能再加“吗”，应说“干什么呢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都在等你，你干什么吗？", "corrected_sentence": "大家都在等你，你干什么呢？", "error_description": "错误：句末用了“吗”。“干什么”已是疑问代词，句末不能再加“吗”，应说“你干什么呢？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
