INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94507, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "才分是一个人天生就会做某些事的本事。", "primary_collocate": null, "pronunciation": "cái fèn", "ipa": "tsʰai˧˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "她从小就很有才分，一学就会。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子画画很有才分。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在音乐上的才分让老师很吃惊。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才分是天生的，不是练出来的。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光有才分不够，还要每天努力练习。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一眼就看出了小云的才分。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才分在跳舞上，不在唱歌上。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我没有写作的才分。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小男孩的才分真让人羡慕。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的才分用在了画画上。", "target_word": "才分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "天生就会做某些事的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c6295ca-33a1-4cb5-9a44-6d80043396b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才分", "is_correct": true, "explanation": "「才分」指天生的学习本事，与“从小就很有”和“一学就会”相符。"}, {"text": "勇气", "is_correct": false, "explanation": "语义：“勇气”指敢做敢当的胆量，与“一学就会”说的学习能力无关。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指体力，与“一学就会”说的学习能力不符。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“很有脾气”说的是性情，不能用来形容学得快。"}], "explanations": {"才分": "「才分」指天生的学习本事，与“从小就很有”和“一学就会”相符。", "勇气": "语义：“勇气”指敢做敢当的胆量，与“一学就会”说的学习能力无关。", "力气": "语义：“力气”指体力，与“一学就会”说的学习能力不符。", "脾气": "搭配：“很有脾气”说的是性情，不能用来形容学得快。"}, "sentence_index": 0, "correct_answer": "才分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次数学考试的才分很好。", "explanation": "这里应该用〈成绩〉。才分指天生就会做某事的本事，考试的结果要用“成绩”。"}, {"text": "他有一只很好的才分。", "explanation": "这里应该用〈种〉。才分是抽象的本事，要用“种”计量，不用于具体事物的量词。"}, {"text": "他每天都在练才分。", "explanation": "这里应该用〈技能〉。才分是天生的本事，不能靠反复练习获得；能练习的是后天学会的技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才分", "is_correct": true, "explanation": "「才分」指天生的本事，可以说“在某方面的才分”，与“在跳舞上，不在唱歌上”相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，不能说“在跳舞上”。"}, {"text": "嗓子", "is_correct": false, "explanation": "搭配：“在……上”后接能力范围，“嗓子”是器官，不能这样说。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指身体的重量，与跳舞或唱歌的能力无关。"}], "explanations": {"才分": "「才分」指天生的本事，可以说“在某方面的才分”，与“在跳舞上，不在唱歌上”相符。", "身高": "体貌：身高是外形特征，不能说“在跳舞上”。", "嗓子": "搭配：“在……上”后接能力范围，“嗓子”是器官，不能这样说。", "体重": "语义：体重指身体的重量，与跳舞或唱歌的能力无关。"}, "sentence_index": 6, "correct_answer": "才分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们公司最好的才分。", "explanation": "这里应该用〈人才〉。才分指个人天生的本事，不能指有能力的人。"}, {"text": "我借了他的才分，考试时用一下。", "explanation": "这里应该用〈书〉。书、钱等可以归还的东西才能被借用；才分是天生的本事，不是物品，不能被别人拿去用。"}, {"text": "他把才分卖给了别人。", "explanation": "这里应该用〈房子〉。房子等商品可以买卖；才分是天生的本事，不是买卖的商品，不能转让。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这孩子有很才分，老师都很喜欢他。", "corrected_sentence": "这孩子很有才分，老师都很喜欢他。", "error_description": "错误：“很”放在了“有”后面，说成“有很才分”。正确：“很”应放在“有”前，说“很有才分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小女孩的才分很的突出。", "corrected_sentence": "这个小女孩的才分很突出。", "error_description": "错误：“很”后面不能直接加“的”再接形容词，多出的“的”需要去掉。正确：应说“很突出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
