INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94509, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "采是用手把花、果或叶子摘下来。", "primary_collocate": null, "pronunciation": "cǎi", "ipa": "tsʰaɪ²¹⁴", "syllable_count": 1, "sentences": [{"text": "春天，孩子们在山上采野花。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她蹲在地上采草莓。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶一早就去茶山采茶。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，我们去果园采苹果。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈采了一些桑叶喂蚕。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩采着花，唱着歌。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些红果子是我昨天采的。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要采路边的花，让大家看。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踮起脚，采下了一朵白花。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她采过很多次茶叶，手很快。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采了", "label": "体标"}, {"form": "采过", "label": "体标"}, {"form": "采着", "label": "体标"}, {"form": "採", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手把花、果、叶摘下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 踮 (Zipf 2.12)']::text[], '69b1368f-3c85-4d4d-9d9f-204f7c23b63d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94509, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "采", "is_correct": true, "explanation": "正确答案：采（cǎi），意思是用手摘取。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。"}, {"text": "才", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是“才”。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 cǎi 韵母不同（ao 与 ai），意思是草。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。"}], "explanations": {"采": "正确答案：采（cǎi），意思是用手摘取。", "菜": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。", "才": "cái（第二声）与 cǎi（第三声）声调不同，意思是“才”。", "草": "cǎo 与 cǎi 韵母不同（ao 与 ai），意思是草。", "惨": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。"}, "sentence_index": null, "correct_answer": "采"}, "level_3": {"options": [{"text": "采", "is_correct": true, "explanation": "“采”指用手把野花摘下来，与“山上”“野花”搭配。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要说明送给谁，“在山上送野花”没有接受者，不通。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”指用钱换东西，与孩子在山上自己摘花的场景不符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是字、文章，不能说写野花。"}], "explanations": {"采": "“采”指用手把野花摘下来，与“山上”“野花”搭配。", "送": "配价：“送”需要说明送给谁，“在山上送野花”没有接受者，不通。", "买": "语义：“买”指用钱换东西，与孩子在山上自己摘花的场景不符。", "写": "搭配：“写”的对象是字、文章，不能说写野花。"}, "sentence_index": 0, "correct_answer": "采"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去超市采苹果。", "explanation": "这里应该用〈买〉。“采”指从植物上摘下来，超市里的苹果要买，不能说采。"}, {"text": "他去菜园采了几根大萝卜，洗干净准备做饭。", "explanation": "这里应该用〈拔〉。“采”指摘取花、果、叶等，地里的萝卜要用“拔”。"}, {"text": "他采下了那顶帽子，放在桌上。", "explanation": "这里应该用〈摘〉。“摘”可以指把帽子等东西从身上或高处取下，“采”只能用于从植物上摘取花、果、叶，不能用于帽子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94509, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "采", "is_correct": true, "explanation": "正确答案：采（cǎi），意思是用手摘取。"}, {"text": "猜", "is_correct": false, "explanation": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。"}, {"text": "财", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是财产。"}, {"text": "改", "is_correct": false, "explanation": "gǎi 与 cǎi 声母不同（g 与 c），意思是改变。"}, {"text": "海", "is_correct": false, "explanation": "hǎi 与 cǎi 声母不同（h 与 c），意思是海洋。"}], "explanations": {"采": "正确答案：采（cǎi），意思是用手摘取。", "猜": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。", "财": "cái（第二声）与 cǎi（第三声）声调不同，意思是财产。", "改": "gǎi 与 cǎi 声母不同（g 与 c），意思是改变。", "海": "hǎi 与 cǎi 声母不同（h 与 c），意思是海洋。"}, "sentence_index": null, "correct_answer": "采"}, "level_3": {"options": [{"text": "采", "is_correct": true, "explanation": "“采的”指用手摘下来的，“是……的”句式与“红果子”“昨天”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱红果子。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：“弹”指用手指拨动或弹射，与红果子搭配不当，句子不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于修理器物，不能用于果子。"}], "explanations": {"采": "“采的”指用手摘下来的，“是……的”句式与“红果子”“昨天”搭配。", "唱": "搭配：“唱”的对象是歌曲，不能说唱红果子。", "弹": "搭配：“弹”指用手指拨动或弹射，与红果子搭配不当，句子不通。", "修": "搭配：“修”用于修理器物，不能用于果子。"}, "sentence_index": 6, "correct_answer": "采"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在树下采了几个落果，装进篮子里。", "explanation": "这里应该用〈捡〉。“采”指从树上、植物上摘下来，地上的落果要用“捡”。"}, {"text": "她在菜市场采了几条鱼。", "explanation": "这里应该用〈挑〉。“采”指从植物上摘取，挑选鱼要用“挑”。"}, {"text": "她在井边采了一桶水，准备烧开喝。", "explanation": "这里应该用〈打〉。“采”指从植物上摘取，井里取水要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在院子里采出了几个柿子。", "corrected_sentence": "妈妈在院子里采下了几个柿子。", "error_description": "“采出”错误，正确是“采下”。“出”表示由内向外取出，多用于矿物、石油；摘柿子这种果实要用“采下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他采了过很多次野花，很熟悉山路。", "corrected_sentence": "他采过很多次野花，很熟悉山路。", "error_description": "“采了过”错误，正确是“采过”。“过”表示经历，“了”与“过”不能同时用在动词后面，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
