INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94510, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摘取；选取。", "primary_collocate": null, "pronunciation": "cǎi", "ipa": "tsʰaɪ²¹⁴", "syllable_count": 1, "sentences": [{"text": "山里的农民上山采药。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂飞到花上采蜜。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在森林里采蘑菇。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前常去山上采药材。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民下海采珍珠。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们到湖边采了很多野菜。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "松鼠忙着在树上采松果。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道怎样采蘑菇才不会中毒吗？", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人背着篮子去山上采野果。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们每天在海边采海带。", "target_word": "采", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采了", "label": "体标"}, {"form": "采过", "label": "体标"}, {"form": "采着", "label": "体标"}, {"form": "採", "label": "繁体"}], "register": "中性", "sense_fingerprint": "摘取、取得野生的药材、蜜、菌类等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b1368f-3c85-4d4d-9d9f-204f7c23b63d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "采", "is_correct": true, "explanation": "正确答案：采（cǎi），意思是摘取。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。"}, {"text": "才", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是“才”。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 cǎi 韵母不同（ao 与 ai），意思是草。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。"}], "explanations": {"采": "正确答案：采（cǎi），意思是摘取。", "菜": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。", "才": "cái（第二声）与 cǎi（第三声）声调不同，意思是“才”。", "草": "cǎo 与 cǎi 韵母不同（ao 与 ai），意思是草。", "惨": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。"}, "sentence_index": null, "correct_answer": "采"}, "level_3": {"options": [{"text": "采", "is_correct": true, "explanation": "“采药”指到野外摘取药材，与“上山”“药”搭配。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是字、文章，不能说写药材。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱药材。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理器物，与上山采药的语境无关。"}], "explanations": {"采": "“采药”指到野外摘取药材，与“上山”“药”搭配。", "写": "搭配：“写”的对象是字、文章，不能说写药材。", "唱": "搭配：“唱”的对象是歌曲，不能说唱药材。", "修": "语义：“修”指修理器物，与上山采药的语境无关。"}, "sentence_index": 0, "correct_answer": "采"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "收购站每年都采很多药材。", "explanation": "这里应该用〈收购〉。“采”指到野外摘取，收购站是从农民手里买药材，要说收购。"}, {"text": "他去药店采了几副中药，回家煎给奶奶喝。", "explanation": "这里应该用〈抓〉。药店按方配药说“抓药”，“采”指到山野摘取药材，不能用于在药店买药。"}, {"text": "他在商场里采了很久的衣服。", "explanation": "这里应该用〈选〉。“采”只用于摘取野生药材、蜂蜜、菌类等，挑选衣服要用“选”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94510, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "采", "is_correct": true, "explanation": "正确答案：采（cǎi），意思是摘取。"}, {"text": "猜", "is_correct": false, "explanation": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。"}, {"text": "财", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是财产。"}, {"text": "改", "is_correct": false, "explanation": "gǎi 与 cǎi 声母不同（g 与 c），意思是改变。"}, {"text": "海", "is_correct": false, "explanation": "hǎi 与 cǎi 声母不同（h 与 c），意思是海洋。"}], "explanations": {"采": "正确答案：采（cǎi），意思是摘取。", "猜": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。", "财": "cái（第二声）与 cǎi（第三声）声调不同，意思是财产。", "改": "gǎi 与 cǎi 声母不同（g 与 c），意思是改变。", "海": "hǎi 与 cǎi 声母不同（h 与 c），意思是海洋。"}, "sentence_index": null, "correct_answer": "采"}, "level_3": {"options": [{"text": "采", "is_correct": true, "explanation": "“采松果”指摘下树上的果实，与“树上”“松鼠”搭配。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”需要买卖的场景，松鼠在树上不会买东西，不符合语境。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，松果不能喝。"}, {"text": "刷", "is_correct": false, "explanation": "搭配：“刷”指用刷子擦洗或涂抹，不能用于松果。"}], "explanations": {"采": "“采松果”指摘下树上的果实，与“树上”“松鼠”搭配。", "买": "语义：“买”需要买卖的场景，松鼠在树上不会买东西，不符合语境。", "喝": "搭配：“喝”的对象是液体，松果不能喝。", "刷": "搭配：“刷”指用刷子擦洗或涂抹，不能用于松果。"}, "sentence_index": 6, "correct_answer": "采"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里采麦子，忙了一整天。", "explanation": "这里应该用〈割〉。“采”用于摘取花、果、叶等，成片的麦子要用“割”。"}, {"text": "渔民下海采了一网鱼。", "explanation": "这里应该用〈捕〉。“采”指摘取植物、药材等，海里捞鱼要用“捕”。"}, {"text": "我们在超市采了一些海带。", "explanation": "这里应该用〈买〉。“采”指在野外摘取，超市里的海带要买，不能说采。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每年夏天都到山里踩蜂蜜。", "corrected_sentence": "她每年夏天都到山里采蜂蜜。", "error_description": "用词错误：“踩”是用脚压的动作，不能用于摘取蜂蜜；此处应用“采”，说“采蜂蜜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人背着篮子上山，采出了一把野菜。", "corrected_sentence": "老人背着篮子上山，采下了一把野菜。", "error_description": "“采出”错误，正确是“采下”。“出”表示由内向外取出，多用于矿物、石油；摘野菜要用“采下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "击败是比赛或打仗时赢了别人。", "primary_collocate": null, "pronunciation": "jī bài", "ipa": "tɕi˥ pai˥˩", "syllable_count": 2, "sentences": [{"text": "中国队击败了日本队。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在决赛中击败了对手。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队昨天击败了最强的队。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王击败了去年的冠军。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队击败了入侵的敌人。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个年轻选手击败过很多高手。", "target_word": "击败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用三比一击败了客队。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我希望下次能击败他。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老虎队击败了狮子队，进了决赛。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟在象棋比赛中击败了爸爸。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "击败了", "label": "体标（完成）"}, {"form": "击败过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "比赛或战争中赢了对手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b1368f-3c85-4d4d-9d9f-204f7c23b63d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "击败", "is_correct": true, "explanation": "“击败”指在比赛或战争中胜过对方，与“中国队”“日本队”的比赛语境搭配。"}, {"text": "邀请", "is_correct": false, "explanation": "语义：“邀请”指请对方来做客或参加活动，与两队比赛胜负的语境不符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、方案，不能直接用于一支队伍。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”指以礼相待，与比赛胜负的语境不符。"}], "explanations": {"击败": "“击败”指在比赛或战争中胜过对方，与“中国队”“日本队”的比赛语境搭配。", "邀请": "语义：“邀请”指请对方来做客或参加活动，与两队比赛胜负的语境不符。", "讨论": "搭配：“讨论”的对象是问题、方案，不能直接用于一支队伍。", "欢迎": "语义：“欢迎”指以礼相待，与比赛胜负的语境不符。"}, "sentence_index": 0, "correct_answer": "击败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子弹击败了目标。", "explanation": "这里应该用〈击中〉。“击败”指在比赛或战争中胜过对手，子弹射中目标要用“击中”。"}, {"text": "他用力击败了地上的灰尘，弄得满屋都是。", "explanation": "这里应该用〈扫〉。“击败”指在比赛或战争中胜过对手，清扫地上的灰尘要用“扫”。"}, {"text": "他用力击败那面鼓。", "explanation": "这里应该用〈击打〉。“击败”的对象必须是对手或敌人，敲鼓要用“击打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "击败", "is_correct": true, "explanation": "“击败”指胜过对方，与“三比一”的比分和比赛语境搭配。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”指表示庆贺，与比分“三比一”的胜负语境不符。"}, {"text": "观察", "is_correct": false, "explanation": "搭配：“观察”的对象可以是人，但“用三比一观察”不通，与比分语境不符。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：“打扰”指妨碍他人，与比分语境不符。"}], "explanations": {"击败": "“击败”指胜过对方，与“三比一”的比分和比赛语境搭配。", "祝贺": "语义：“祝贺”指表示庆贺，与比分“三比一”的胜负语境不符。", "观察": "搭配：“观察”的对象可以是人，但“用三比一观察”不通，与比分语境不符。", "打扰": "语义：“打扰”指妨碍他人，与比分语境不符。"}, "sentence_index": 6, "correct_answer": "击败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "炸弹击败了那座大桥。", "explanation": "这里应该用〈击毁〉。“击败”用于在竞争中胜过对手，把大桥炸毁要用“击毁”。"}, {"text": "重锤击败了那块玻璃。", "explanation": "这里应该用〈击碎〉。“击败”的对象是对手，玻璃被打碎要用“击碎”。"}, {"text": "妈妈在厨房击败了几个鸡蛋，准备做饭。", "explanation": "这里应该用〈打〉。“击败”的对象是对手或敌人，打鸡蛋要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支球队曾经击败了过所有对手。", "corrected_sentence": "这支球队曾经击败过所有对手。", "error_description": "“了”和“过”不能同时用在动词后面：表示曾经有过的经历用“击败过”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个队在上赛季击败着三支强队。", "corrected_sentence": "这个队在上赛季击败了三支强队。", "error_description": "“着”错误，正确是“了”。“着”表示动作正在进行或状态持续；描述已经完成的比赛结果要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
