INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为实现某种政治目标而发动的大规模群众活动。", "primary_collocate": null, "pronunciation": "zhèng zhì yùn dòng", "ipa": "ʈʂɤŋ˥˩ ʈʂɨ˥˩ yn˥˩ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个国家发动了一场政治运动。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治运动的目标是改变社会制度。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次政治运动得到了群众的支持。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政党发动群众，开展政治运动。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场政治运动影响了整个国家。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上讲了几次大的政治运动。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治运动结束后，社会慢慢恢复了平静。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究的是二十世纪的政治运动。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次政治运动都有明确的目标。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治运动需要很多群众一起参加。", "target_word": "政治运动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "政治運動", "label": "繁体"}, {"form": "一场政治运动", "label": "量词"}], "register": "中性", "sense_fingerprint": "为政治目标发动的大规模群众活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9536ccae-044a-44e6-b63c-3b9235ea771b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治运动", "is_correct": true, "explanation": "“政治运动”是为政治目标发动的群众活动，与“发动”搭配自然。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“发动”不接“感冒”，不能说“发动一场感冒”。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是文学作品，不是可以被发动的活动。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是机器，不是可以被发动的活动。"}], "explanations": {"政治运动": "“政治运动”是为政治目标发动的群众活动，与“发动”搭配自然。", "感冒": "搭配：“发动”不接“感冒”，不能说“发动一场感冒”。", "小说": "语义：“小说”是文学作品，不是可以被发动的活动。", "电脑": "语义：“电脑”是机器，不是可以被发动的活动。"}, "sentence_index": 0, "correct_answer": "政治运动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早上我们做了政治运动。", "explanation": "这里应该用〈体操〉。“做”后接体育锻炼，政治运动不是锻炼项目。"}, {"text": "新闻里提到一条政治运动。", "explanation": "这里应该用〈场〉或〈次〉。“条”用于河流、道路等细长的事物，不用于政治运动。"}, {"text": "孩子们在广场跳政治运动。", "explanation": "这里应该用〈舞〉。“跳”的对象是舞蹈，政治运动不能用“跳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治运动", "is_correct": true, "explanation": "“政治运动”结束后，社会恢复平静，语义完整。"}, {"text": "手术", "is_correct": false, "explanation": "语义：“手术”是医疗行为，与“社会慢慢恢复平静”没有关联。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”不说“结束后”，也不与“社会恢复平静”搭配。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”是记录做菜方法的书，不能让社会恢复平静。"}], "explanations": {"政治运动": "“政治运动”结束后，社会恢复平静，语义完整。", "手术": "语义：“手术”是医疗行为，与“社会慢慢恢复平静”没有关联。", "课本": "搭配：“课本”不说“结束后”，也不与“社会恢复平静”搭配。", "菜谱": "语义：“菜谱”是记录做菜方法的书，不能让社会恢复平静。"}, "sentence_index": 6, "correct_answer": "政治运动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在台上唱政治运动。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，政治运动不能被演唱。"}, {"text": "他写了一场政治运动。", "explanation": "这里应该用〈文章〉。“写”的对象是文字作品，政治运动不能被书写。"}, {"text": "桌上放着一块政治运动。", "explanation": "这里应该用〈场〉或〈次〉。“块”用于成块的东西，不用于计量政治运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗政治运动吸引了很多年轻人。", "corrected_sentence": "这次政治运动吸引了很多年轻人。", "error_description": "“颗”是用于圆形小物体的量词，不能修饰“政治运动”。应说“这次政治运动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首政治运动影响了很多人的生活。", "corrected_sentence": "这次政治运动影响了很多人的生活。", "error_description": "“首”是用于诗词、歌曲的量词，不能修饰“政治运动”。应说“这次政治运动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
