INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "整是一点也不少，是全部的。", "primary_collocate": null, "pronunciation": "zhěng", "ipa": "ʈʂɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他一口气喝完了整瓶水。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子饿坏了，一个人吃了整碗饭。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了整晚书，一分钟也没睡。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把整桶水倒进了池子里，一滴也没剩。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要买整箱牛奶，不要只买一瓶。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这锅汤太好喝，他一个人喝了整锅。", "target_word": "整", "complexity_tier": "T3", "furigana": "zhěng", "sentence_source": "generated"}, {"text": "他很饿，把整盘菜都吃光了。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电了，整栋楼都没有灯。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天下雨，整班同学都没来。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做了整桌菜，请大家来吃。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整整", "label": "重叠"}, {"form": "整个", "label": "复合"}, {"form": "整天", "label": "复合"}], "register": "中性", "sense_fingerprint": "整：全部、一点不少（整瓶水、三点整）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c6295ca-33a1-4cb5-9a44-6d80043396b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是一点不少、全部。"}, {"text": "争", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。"}, {"text": "证", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。"}, {"text": "政", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是一点不少、全部。", "争": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。", "蒸": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。", "证": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。", "政": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示全部、一点不少，与“一口气喝完了”的瓶装水相符。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”指没有东西，与“喝完了水”矛盾。"}, {"text": "零", "is_correct": false, "explanation": "数词：「零」表示没有，「零瓶水」与「一口气喝完」的数量矛盾。"}, {"text": "碎", "is_correct": false, "explanation": "搭配：“碎”说物体破裂，不能修饰装水的“瓶”，“碎瓶水”不成立。"}], "explanations": {"整": "「整」表示全部、一点不少，与“一口气喝完了”的瓶装水相符。", "空": "语义：“空”指没有东西，与“喝完了水”矛盾。", "零": "数词：「零」表示没有，「零瓶水」与「一口气喝完」的数量矛盾。", "碎": "搭配：“碎”说物体破裂，不能修饰装水的“瓶”，“碎瓶水”不成立。"}, "sentence_index": 0, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把整张桶倒进了池子里，一滴也没剩。", "explanation": "这里应该用〈整个〉。桶用“个”计量，“张”用于纸、桌面等平面的东西。"}, {"text": "我们要整一整教室。", "explanation": "这里是“整顿、使有秩序”的意思，与“全部、一点不少”无关。"}, {"text": "我把整根水都倒进了池子里，一滴也没剩。", "explanation": "这里应该用〈整桶〉。水要用“桶”计量，“根”用于细长的条状东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是一点不少、全部。"}, {"text": "正", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。"}, {"text": "挣", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。"}, {"text": "征", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。"}, {"text": "睁", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是一点不少、全部。", "正": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。", "挣": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。", "征": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。", "睁": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示全部，与“把整盘菜都吃光了”相符。"}, {"text": "烂", "is_correct": false, "explanation": "语义：“烂”指腐坏，与“吃光了”的正常饭菜不合。"}, {"text": "脏", "is_correct": false, "explanation": "语义：“脏”指不干净，与饿了要吃光的语境不符。"}, {"text": "生", "is_correct": false, "explanation": "搭配：“生”多指未煮熟的食材，不能说“生盘菜”。"}], "explanations": {"整": "「整」表示全部，与“把整盘菜都吃光了”相符。", "烂": "语义：“烂”指腐坏，与“吃光了”的正常饭菜不合。", "脏": "语义：“脏”指不干净，与饿了要吃光的语境不符。", "生": "搭配：“生”多指未煮熟的食材，不能说“生盘菜”。"}, "sentence_index": 6, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做了整只菜，请大家来吃。", "explanation": "这里应该用〈整道〉。菜用“道”计量，“只”用于动物、器物等。"}, {"text": "妈妈把屋子整了一遍，请大家来吃。", "explanation": "这里是“整理、使有秩序”的意思，与“全部的菜”无关。"}, {"text": "妈妈把整根蛋糕都端上来了。", "explanation": "这里应该用〈整个〉。蛋糕用“个”计量，“根”用于细长的条状东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUD