INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一口气喝完了整张牛奶。", "corrected_sentence": "他一口气喝完了整箱牛奶。", "error_description": "错误：“张”用于纸、桌子等平面的东西，牛奶要用“箱”计量，应说“整箱牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把锅整汤都倒掉了。", "corrected_sentence": "妈妈把整锅汤都倒掉了。", "error_description": "错误：“整”与量词“锅”的语序颠倒，说成“锅整汤”。正确：应说“整锅汤”，“整”放在量词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
