INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "完整无缺，未被切开或拆散。", "primary_collocate": null, "pronunciation": "zhěng", "ipa": "ʈʂɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "盘子里放着整条鱼，鱼头鱼尾都在。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕还没切，我们买的是整块的。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师手里拿着整张地图，没有撕坏。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书很贵，我想买整套，不想只买一本。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把整句话读一遍，不要只读一半。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站远一点，才能看到整幅画。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子摔碎了，没有一块是整的。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想要整只鸡，不要鸡腿。", "target_word": "整", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书虽然旧了，但整本都在，没有缺页。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们从山上搬回了整棵树，根也没断。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整整", "label": "重叠"}, {"form": "整个", "label": "复合"}, {"form": "整天", "label": "复合"}], "register": "中性", "sense_fingerprint": "整：完整无缺的，用在量词前（整条鱼、整块蛋糕）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c6295ca-33a1-4cb5-9a44-6d80043396b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是完整、全部。"}, {"text": "正", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。"}, {"text": "争", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。"}, {"text": "证", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是完整、全部。", "正": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。", "蒸": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。", "争": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。", "证": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示完整，与“鱼头鱼尾都在”相符，量词“条”前用“整”。"}, {"text": "残", "is_correct": false, "explanation": "语义：“残”指残缺，与“鱼头鱼尾都在”矛盾。"}, {"text": "碎", "is_correct": false, "explanation": "搭配：“碎”不能直接修饰量词“条”，“碎条鱼”不成立。"}, {"text": "烂", "is_correct": false, "explanation": "语义：“烂”指腐坏，与“鱼头鱼尾都在”的描述不符。"}], "explanations": {"整": "「整」表示完整，与“鱼头鱼尾都在”相符，量词“条”前用“整”。", "残": "语义：“残”指残缺，与“鱼头鱼尾都在”矛盾。", "碎": "搭配：“碎”不能直接修饰量词“条”，“碎条鱼”不成立。", "烂": "语义：“烂”指腐坏，与“鱼头鱼尾都在”的描述不符。"}, "sentence_index": 0, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一口气吃完了整张鸡。", "explanation": "这里应该用〈整只〉。鸡用“只”计量，“张”用于纸张、桌面等平面的东西。"}, {"text": "他老是整同学，大家都不喜欢他。", "explanation": "这里是“捉弄、惩治人”的口语意思，与“完整无缺”无关，也不是“使有秩序”的意思。"}, {"text": "我想买整只书，不想只买一本。", "explanation": "这里应该用〈整本〉。书用“本”计量，“只”用于动物、器物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是完整、全部。"}, {"text": "政", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。"}, {"text": "挣", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。"}, {"text": "征", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。"}, {"text": "睁", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是完整、全部。", "政": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。", "挣": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。", "征": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。", "睁": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示完整，与“没有一块是整的”相符，说明碎片都不完整。"}, {"text": "破", "is_correct": false, "explanation": "语义：“破”指损坏，说“没有一块是破的”与“摔碎了”的语境相反。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”说新旧，与句子讨论碎片是否完整的语境无关。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，与摔碎的杯子碎片无关，不能说「没有一块是甜的」。"}], "explanations": {"整": "「整」表示完整，与“没有一块是整的”相符，说明碎片都不完整。", "破": "语义：“破”指损坏，说“没有一块是破的”与“摔碎了”的语境相反。", "新": "语义：“新”说新旧，与句子讨论碎片是否完整的语境无关。", "甜": "语义：「甜」形容味道，与摔碎的杯子碎片无关，不能说「没有一块是甜的」。"}, "sentence_index": 6, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家人吃掉了整条西瓜。", "explanation": "这里应该用〈整个〉。西瓜用“个”计量，“条”用于鱼、裤子等细长的东西。"}, {"text": "他买了一整棵鱼。", "explanation": "这里应该用〈整条〉。鱼用“条”计量，“棵”用于树木。"}, {"text": "他们从山上搬回了整棵石头。", "explanation": "这里应该用〈整块〉。石头用“块”计量，“棵”用于树木、植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了套整家具，搬进了新家。", "corrected_sentence": "他买了整套家具，搬进了新家。", "error_description": "错误：“整”放在了量词“套”后面，说成“套整”。正确：“整”应放在量词前，说“整套家具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他整把块蛋糕吃完了。", "corrected_sentence": "他把整块蛋糕吃完了。", "error_description": "错误：“把”与“整”的顺序颠倒。正确：“把”要放在处置对象前，应说“把整块蛋糕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f346e99b-a2d6-4513-9ca3-f17a2c0889b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
