INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94521, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "服务器是一台很大的电脑，别的电脑从它那里拿东西。", "primary_collocate": null, "pronunciation": "fú wù qì", "ipa": "fu˧˥ u˥˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "这台服务器很大。", "target_word": "服务器", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司的服务器放在一个房间里。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的电脑连不上服务器。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务器里有很多照片和文件。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天检查一次服务器。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务器坏了，我们不能上网。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台服务器的声音很大。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们从服务器上下载作业。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校买了两台新服务器。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务器需要一直开着。", "target_word": "服务器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台服务器", "label": "量词"}, {"form": "服务器端", "label": "复合"}, {"form": "服務器", "label": "繁体"}], "register": "中性", "sense_fingerprint": "服务器|名词|别的电脑从它那里拿东西的大电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服务器", "is_correct": true, "explanation": "服务器：计算机，量词用“台”，与“很大”相符。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：量词“台”用于机器，不能说“这台教室”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是机器，不能用“台”计量，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：河流不用量词“台”，不能说“这台河流”。"}], "explanations": {"服务器": "服务器：计算机，量词用“台”，与“很大”相符。", "教室": "搭配：量词“台”用于机器，不能说“这台教室”。", "天空": "语义：天空不是机器，不能用“台”计量，句子不通。", "河流": "搭配：河流不用量词“台”，不能说“这台河流”。"}, "sentence_index": 0, "correct_answer": "服务器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务器很好。", "explanation": "这里应该用〈服务〉。服务指为顾客提供帮助，服务器是计算机，不能指服务态度。"}, {"text": "饭店的服务器给我们倒了茶。", "explanation": "这里应该用〈服务员〉。服务员是人，负责给顾客倒茶；服务器是计算机，不能给顾客倒茶。"}, {"text": "服务器每天给病人看病。", "explanation": "这里应该用〈医生〉。医生是人，负责给病人看病；服务器是计算机，不能给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服务器", "is_correct": true, "explanation": "服务器：机器能发出声音，与“声音很大”相符。"}, {"text": "观众", "is_correct": false, "explanation": "搭配：量词“台”不用于人，“这台观众”不能说。"}, {"text": "雷雨", "is_correct": false, "explanation": "语义：雷雨是天气现象，不能说“这台雷雨”。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：狗的量词是“只”，不用“台”。"}], "explanations": {"服务器": "服务器：机器能发出声音，与“声音很大”相符。", "观众": "搭配：量词“台”不用于人，“这台观众”不能说。", "雷雨": "语义：雷雨是天气现象，不能说“这台雷雨”。", "狗": "搭配：狗的量词是“只”，不用“台”。"}, "sentence_index": 6, "correct_answer": "服务器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天用服务器做饭。", "explanation": "这里应该用〈炉子〉。服务器是计算机，不能用来做饭。"}, {"text": "服务器在柜台上卖东西。", "explanation": "这里应该用〈售货员〉。售货员是人，负责在柜台卖东西；服务器是计算机，不能卖东西。"}, {"text": "我查服务器找生词。", "explanation": "这里应该用〈字典〉。字典用于查生词；服务器是计算机，不能用来查生词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个网站用了一只服务器。", "corrected_sentence": "这个网站用了一台服务器。", "error_description": "量词错误。“只”用于动物，服务器是机器，应说“一台服务器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台服务器一直开了着。", "corrected_sentence": "这台服务器一直开着。", "error_description": "多出了“了”。“开”后面应直接接“着”，说“一直开着”，“开了着”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
