INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在网络中为其他计算机提供数据和服务的计算机。", "primary_collocate": null, "pronunciation": "fú wù qì", "ipa": "fu˧˥ u˥˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "这个网站的服务器在国外。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的服务器今天晚上要维修。", "target_word": "服务器", "complexity_tier": "T3", "furigana": "fú wù qì", "sentence_source": "generated"}, {"text": "服务器太忙，网页打不开。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机把照片发到服务器上。", "target_word": "服务器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器收到了你的请求。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司租了一台服务器。", "target_word": "服务器", "complexity_tier": "T3", "furigana": "fú wù qì", "sentence_source": "generated"}, {"text": "服务器每秒处理很多数据。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为服务器出了问题，网站不能用。", "target_word": "服务器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的服务器二十四小时开着。", "target_word": "服务器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先登录服务器再改文件。", "target_word": "服务器", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台服务器", "label": "量词"}, {"form": "服务器端", "label": "复合"}, {"form": "服務器", "label": "繁体"}], "register": "中性", "sense_fingerprint": "服务器|名词|网络中提供数据和服务的计算机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服务器", "is_correct": true, "explanation": "服务器：网络中提供数据的计算机，与“网站”“在国外”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：网站的设备不可能是“老师”，句子不通。"}, {"text": "首长", "is_correct": false, "explanation": "语域：“首长”是对领导的敬称，不能用来指网站的设备。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师是人，不能作为网站的设备放在国外。"}], "explanations": {"服务器": "服务器：网络中提供数据的计算机，与“网站”“在国外”相符。", "老师": "语义：网站的设备不可能是“老师”，句子不通。", "首长": "语域：“首长”是对领导的敬称，不能用来指网站的设备。", "厨师": "语义：厨师是人，不能作为网站的设备放在国外。"}, "sentence_index": 0, "correct_answer": "服务器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机是服务器，可以随时下载资料。", "explanation": "这里应该用〈客户端〉。客户端向服务器请求数据，手机下载资料时是客户端，不是服务器。"}, {"text": "我查服务器找生词。", "explanation": "这里应该用〈字典〉。字典用于查生词，服务器是提供数据的计算机，不能用来查生词。"}, {"text": "服务器把信号传到每个房间。", "explanation": "这里应该用〈路由器〉。路由器负责转发信号；服务器负责为其他计算机提供数据和服务，不负责把信号传到房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服务器", "is_correct": true, "explanation": "服务器：计算机，能处理数据，与“每秒处理很多数据”相符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不能处理数据，句子不通。"}, {"text": "鱼群", "is_correct": false, "explanation": "语义：鱼群不能处理数据，句子不通。"}, {"text": "秒针", "is_correct": false, "explanation": "语义：秒针只指示时间，不能处理数据，句子不通。"}], "explanations": {"服务器": "服务器：计算机，能处理数据，与“每秒处理很多数据”相符。", "花朵": "语义：花朵不能处理数据，句子不通。", "鱼群": "语义：鱼群不能处理数据，句子不通。", "秒针": "语义：秒针只指示时间，不能处理数据，句子不通。"}, "sentence_index": 6, "correct_answer": "服务器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用服务器给朋友打电话。", "explanation": "这里应该用〈手机〉。服务器是提供数据和服务的计算机，不能用来打电话。"}, {"text": "服务器给我们端了菜。", "explanation": "这里应该用〈服务员〉。服务员是人，负责给顾客端菜；服务器是为其他计算机提供数据的计算机，不能端菜。"}, {"text": "服务器在医院看病。", "explanation": "这里应该用〈医生〉。医生是人，负责在医院看病；服务器是计算机，不能看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个视频网站有一只服务器。", "corrected_sentence": "这个视频网站有一台服务器。", "error_description": "量词错误。“只”用于动物，服务器是机器，应说“一台服务器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司的服务器一直开了着。", "corrected_sentence": "我们公司的服务器一直开着。", "error_description": "多出了“了”。“开”后面应直接接“着”，说“一直开着”，“开了着”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
