INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "档是按高低大小分出的层级，如风扇的几档、价格分几档。", "primary_collocate": null, "pronunciation": "dàng", "ipa": "taŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这台风扇有三档风。", "target_word": "档", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把空调调到二档。", "target_word": "档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜按价格分三档。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电饭锅的火力分两档，火大火小不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水开了，把火调小一档。", "target_word": "档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的价格分几档，你要哪一档？", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大了，调低一档吧。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店的房间分三档，价钱不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电吹风的风速分两档，风大风小不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台洗衣机的转速分两档，快慢不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "档案", "label": "复合"}, {"form": "档次", "label": "复合"}, {"form": "檔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按高低大小分出的层级，如风扇的几档、价格分几档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: 4 words above tier T2 (max 3): 这台 (Zipf 3.53), 洗衣机 (Zipf 3.69), 转速 (Zipf 3.51), 快慢 (Zipf 3.13)']::text[], '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "档", "is_correct": true, "explanation": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。"}, {"text": "当", "is_correct": false, "explanation": "当 dāng（第一声）与 dàng 只差声调，意思是承担或正在，不是档。"}, {"text": "挡", "is_correct": false, "explanation": "挡 dǎng（第三声）与 dàng 只差声调，意思是阻挡。"}, {"text": "党", "is_correct": false, "explanation": "党 dǎng（第三声）与 dàng 只差声调，意思是政党。"}, {"text": "但", "is_correct": false, "explanation": "但 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是但是。"}, {"text": "烫", "is_correct": false, "explanation": "烫 tàng 与 dàng 只差声母 t/d，意思是温度高。"}], "explanations": {"档": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。", "当": "当 dāng（第一声）与 dàng 只差声调，意思是承担或正在，不是档。", "挡": "挡 dǎng（第三声）与 dàng 只差声调，意思是阻挡。", "党": "党 dǎng（第三声）与 dàng 只差声调，意思是政党。", "但": "但 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是但是。", "烫": "烫 tàng 与 dàng 只差声母 t/d，意思是温度高。"}, "sentence_index": null, "correct_answer": "档"}, "level_3": {"options": [{"text": "档", "is_correct": true, "explanation": "档指风扇的风力等级，填入后「这台风扇有三档风」通顺。"}, {"text": "季", "is_correct": false, "explanation": "语义：季风是按季节吹的风，风扇不分季节，不能说「三季风」。"}, {"text": "阵", "is_correct": false, "explanation": "搭配：「阵」用于一阵风这类间歇出现的风，不用于数风扇的档位。"}, {"text": "声", "is_correct": false, "explanation": "语义：「声」指声音，风扇的风力不能按声计数，句子不通。"}], "explanations": {"档": "档指风扇的风力等级，填入后「这台风扇有三档风」通顺。", "季": "语义：季风是按季节吹的风，风扇不分季节，不能说「三季风」。", "阵": "搭配：「阵」用于一阵风这类间歇出现的风，不用于数风扇的档位。", "声": "语义：「声」指声音，风扇的风力不能按声计数，句子不通。"}, "sentence_index": 0, "correct_answer": "档"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼有三档，每档有五间房。", "explanation": "这里应该用〈层〉。楼房的层数要用〈层〉，档只用于按高低大小分出的层级，不用于楼层。"}, {"text": "这列火车有八档车厢。", "explanation": "这里应该用〈节〉。车厢数量要用〈节〉，档不能用来数车厢。"}, {"text": "电影院有十档座位。", "explanation": "这里应该用〈排〉。座位的前后排列要用〈排〉，档不能用于座位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "档", "is_correct": true, "explanation": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。"}, {"text": "定", "is_correct": false, "explanation": "定 dìng（第四声）与 dàng 只差元音 i/a，意思是固定或决定。"}, {"text": "浪", "is_correct": false, "explanation": "浪 làng 与 dàng 只差声母 l/d，意思是波浪。"}, {"text": "弹", "is_correct": false, "explanation": "弹 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是弹药。"}, {"text": "巷", "is_correct": false, "explanation": "巷 hàng 与 dàng 只差声母 h/d，意思是小巷。"}], "explanations": {"档": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。", "定": "定 dìng（第四声）与 dàng 只差元音 i/a，意思是固定或决定。", "浪": "浪 làng 与 dàng 只差声母 l/d，意思是波浪。", "弹": "弹 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是弹药。", "巷": "巷 hàng 与 dàng 只差声母 h/d，意思是小巷。"}, "sentence_index": null, "correct_answer": "档"}, "level_3": {"options": [{"text": "档", "is_correct": true, "explanation": "档指风力等级，「调低一档」表示把风力降低一级。"}, {"text": "种", "is_correct": false, "explanation": "语义：「种」指类别，「调低一种」说不通，风力只能说调低一档。"}, {"text": "套", "is_correct": false, "explanation": "搭配：「套」用于成套的物品，不能用来数风力等级。"}, {"text": "片", "is_correct": false, "explanation": "搭配：「片」用于成片的事物，不能说「调低一片」。"}], "explanations": {"档": "档指风力等级，「调低一档」表示把风力降低一级。", "种": "语义：「种」指类别，「调低一种」说不通，风力只能说调低一档。", "套": "搭配：「套」用于成套的物品，不能用来数风力等级。", "片": "搭配：「片」用于成片的事物，不能说「调低一片」。"}, "sentence_index": 6, "correct_answer": "档"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语档很高。", "explanation": "这里应该用〈水平〉。〈档〉指按高低分出的层级，不能用来说人的能力高低；说能力的高低要用〈水平〉。"}, {"text": "这次地震的档很严重。", "explanation": "这里应该用〈程度〉。〈档〉指按高低分出的等级，不能用来说事情的严重程度；形容严重程度要用〈程度〉。"}, {"text": "这台风扇有三只档。", "explanation": "这里应该直接说〈三档〉。〈档〉在此指风力等级，是抽象的层级，不是能用量词一个个数的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台空调有四只档风。", "corrected_sentence": "这台空调有四档风。", "error_description": "错误：「四只档风」。正确：「四档风」。「只」用于动物或成对物品中的一件，不能修饰「档」；表示风力等级时，数词直接接「档」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风太小了，调高档一吧。", "corrected_sentence": "风太小了，调高一档吧。", "error_description": "错误：「调高档一吧」。正确：「调高一档吧」。数量词「一档」要放在动词后面，不能把数词放到「档」的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。"}, {"text": "打开", "is_correct": false, "explanation": "无关：“打开”不表示传承或保留，与“流传”没有反义关系。"}, {"text": "关闭", "is_correct": false, "explanation": "无关：“关闭”指使门窗、开关等停止开放，与“流传”没有反义关系。"}, {"text": "移动", "is_correct": false, "explanation": "无关：“移动”指位置的改变，与“一代代传下去”这一义无关。"}], "correct_answer": "失传", "explanations": {"失传": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。", "打开": "无关：“打开”不表示传承或保留，与“流传”没有反义关系。", "关闭": "无关：“关闭”指使门窗、开关等停止开放，与“流传”没有反义关系。", "移动": "无关：“移动”指位置的改变，与“一代代传下去”这一义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。"}, {"text": "收回", "is_correct": false, "explanation": "无关：“收回”指把已经给出的东西要回来，与“一代代传下去”没有关系。"}, {"text": "逃跑", "is_correct": false, "explanation": "无关：“逃跑”指迅速离开以躲避危险，与“一代代传下去”没有关系。"}, {"text": "扔掉", "is_correct": false, "explanation": "无关：“扔掉”指丢弃，与“一代代传下去”没有反义关系。"}], "correct_answer": "失传", "explanations": {"失传": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。", "收回": "无关：“收回”指把已经给出的东西要回来，与“一代代传下去”没有关系。", "逃跑": "无关：“逃跑”指迅速离开以躲避危险，与“一代代传下去”没有关系。", "扔掉": "无关：“扔掉”指丢弃，与“一代代传下去”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "故事、传说、习俗等一代代传下去，保留至今。", "primary_collocate": null, "pronunciation": "liú chuán", "ipa": "ljoʊ˧˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "这个故事在我们村里流传了几百年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说这个习俗是祖先流传下来的。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首民歌从古代一直流传到现在。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家的菜谱代代流传着。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于长城的传说流传了两千多年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老故事从奶奶传给妈妈，一直流传下来。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书在中国流传了很多年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地流传着一个古老的传说。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多古诗至今还在流传。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法已经流传了上百年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流传着", "label": "体标"}, {"form": "流传过", "label": "体标"}, {"form": "流传下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "故事、传说、习俗等一代一代往下传，保留至今", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流传", "is_correct": true, "explanation": "正确：“流传了几百年”指故事在村里一代代传下来，符合语境。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的对象是活动、展览，故事不能说“举办了几百年”。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”指事情在某一时刻出现，不能表示延续几百年。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品或资料，故事不能被“收藏了几百年”。"}], "explanations": {"流传": "正确：“流传了几百年”指故事在村里一代代传下来，符合语境。", "举办": "搭配：“举办”的对象是活动、展览，故事不能说“举办了几百年”。", "发生": "语义：“发生”指事情在某一时刻出现，不能表示延续几百年。", "收藏": "搭配：“收藏”的对象是物品或资料，故事不能被“收藏了几百年”。"}, "sentence_index": 0, "correct_answer": "流传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要流传民族文化。", "explanation": "这里应该用〈传承〉。流传指消息、传说自然传开，有意识地把文化一代代接续下去要用〈传承〉。"}, {"text": "他每天流传三次药。", "explanation": "这里应该用〈服〉。流传指消息、传统在人群中传开或传下去，吃药要用〈服〉。"}, {"text": "他流传了父亲的事业。", "explanation": "这里应该用〈继承〉。流传说的是事物在人群中传开，接收前人留下的事业要用〈继承〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流传", "is_correct": true, "explanation": "正确：“流传了很多年”指书在中国一直被传阅、保存，符合语境。"}, {"text": "施工", "is_correct": false, "explanation": "搭配：“施工”的对象是建筑、工程，书不能“施工了很多年”。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等建筑，书不能被“修建”。"}, {"text": "发射", "is_correct": false, "explanation": "语义：“发射”指把物体射出或送入太空，与书在中国传阅的情境不符。"}], "explanations": {"流传": "正确：“流传了很多年”指书在中国一直被传阅、保存，符合语境。", "施工": "搭配：“施工”的对象是建筑、工程，书不能“施工了很多年”。", "修建": "搭配：“修建”的对象是房屋、道路等建筑，书不能被“修建”。", "发射": "语义：“发射”指把物体射出或送入太空，与书在中国传阅的情境不符。"}, "sentence_index": 6, "correct_answer": "流传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的深色眼睛流传自母亲。", "explanation": "这里应该用〈遗传〉。流传指消息、传说辗转传开，眼睛颜色这类特征由父母传给子女要用〈遗传〉。"}, {"text": "博物馆流传了很多古画。", "explanation": "这里应该用〈收藏〉。流传指事物一代代传下去，博物馆把古画收存保管要用〈收藏〉。"}, {"text": "这场火灾很快流传到了整栋楼。", "explanation": "这里应该用〈扩散〉。流传指消息、说法辗转传开，火势向四周蔓延要用〈扩散〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门手艺一直流传来。", "corrected_sentence": "这门手艺一直流传下来。", "error_description": "错误：“流传来”；正确：“流传下来”。“流传”后须接趋向补语“下来”，表示一代代传下去，缺少“下”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个古老的歌谣被流传了好几代。", "corrected_sentence": "这个古老的歌谣流传了好几代。", "error_description": "错误：“被流传”；正确：“流传”。“流传”是不及物动词，不能用“被”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
