INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94534, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消息、说法、歌曲等辗转被人一个传一个，传播开来。", "primary_collocate": null, "pronunciation": "liú chuán", "ipa": "ljoʊ˧˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "这个消息很快就在网上流传开了。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于他的谣言在公司里流传着。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌在年轻人中间流传得很广。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张照片在朋友圈里流传了好几天。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里流传着一个奇怪的消息。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种说法在学生中流传很久了。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个笑话在我们学校流传过一阵子。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一张旧照片在网上流传，大家都看过。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏消息一天就流传到了全城。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言一旦流传开，就很难停下来。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流传着", "label": "体标"}, {"form": "流传过", "label": "体标"}, {"form": "流传下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "消息、说法、歌曲等被人一个传一个，传播开来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流传", "is_correct": true, "explanation": "正确：“流传”指消息在网上一个传一个地传开，与“很快就在网上……开了”相符。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是把内容去掉，与消息“很快传开”的意思相反。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品或内容，不能说消息被“收藏开”。"}, {"text": "封锁", "is_correct": false, "explanation": "语义：“封锁”是阻断、不让通过，与消息在网上迅速扩散的情境不符。"}], "explanations": {"流传": "正确：“流传”指消息在网上一个传一个地传开，与“很快就在网上……开了”相符。", "删除": "语义：“删除”是把内容去掉，与消息“很快传开”的意思相反。", "收藏": "搭配：“收藏”的对象是物品或内容，不能说消息被“收藏开”。", "封锁": "语义：“封锁”是阻断、不让通过，与消息在网上迅速扩散的情境不符。"}, "sentence_index": 0, "correct_answer": "流传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种病毒通过空气迅速流传。", "explanation": "这里应该用〈传播〉。流传指消息、说法辗转传开，病毒等通过空气扩散要用〈传播〉。"}, {"text": "这种感冒很快流传到了全班。", "explanation": "这里应该用〈传染〉。流传不指疾病在人与人之间感染，那要用〈传染〉。"}, {"text": "他把会议精神流传给大家。", "explanation": "这里应该用〈传达〉。流传是自然地辗转传开，有意地把指示、精神告诉别人要用〈传达〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流传", "is_correct": true, "explanation": "正确：“流传过一阵子”指笑话在学校里一个传一个地传过一段时间，符合语境。"}, {"text": "失传", "is_correct": false, "explanation": "语义：“失传”指技艺、文化因无人传承而消失，不能用于笑话的传播。"}, {"text": "施工", "is_correct": false, "explanation": "搭配：“施工”的对象是建筑、工程，笑话不能“施工过一阵子”。"}, {"text": "封印", "is_correct": false, "explanation": "语义：“封印”是封存、加封条，与笑话在学校被人讲述的情境不符。"}], "explanations": {"流传": "正确：“流传过一阵子”指笑话在学校里一个传一个地传过一段时间，符合语境。", "失传": "语义：“失传”指技艺、文化因无人传承而消失，不能用于笑话的传播。", "施工": "搭配：“施工”的对象是建筑、工程，笑话不能“施工过一阵子”。", "封印": "语义：“封印”是封存、加封条，与笑话在学校被人讲述的情境不符。"}, "sentence_index": 6, "correct_answer": "流传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "野草很快流传到了整个山坡。", "explanation": "这里应该用〈蔓延〉。流传指消息、说法辗转传开，草木向四周扩展要用〈蔓延〉。"}, {"text": "墨水很快流传进了纸里。", "explanation": "这里应该用〈渗透〉。流传指消息、说法辗转传开，液体渗入物体内部要用〈渗透〉。"}, {"text": "厨房里流传着浓浓的香味。", "explanation": "这里应该用〈散发〉。流传不用于气味的扩散，香味向外散出要用〈散发〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个传言在学校里很快就流传了开。", "corrected_sentence": "这个传言在学校里很快就流传开了。", "error_description": "错误：“流传了开”；正确：“流传开了”。趋向补语“开”应紧跟动词“流传”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个老段子在大家之间很流传了很多年。", "corrected_sentence": "这个老段子在大家之间流传了很多年。", "error_description": "错误：“很流传”；正确：“流传”（或“流传得很广”）。“流传”是动词，一般不受程度副词“很”直接修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "淘汰是比赛时输了的人要离开，不能再比。", "primary_collocate": null, "pronunciation": "táo tài", "ipa": "tʰɑʊ˧˥ tʰai˥˩", "syllable_count": 2, "sentences": [{"text": "这场比赛淘汰了八个队。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一轮比赛淘汰了一半的人。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "输了的队就淘汰了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛一共淘汰了五个选手。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队在半决赛淘汰了对手。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "输一场就淘汰，所以大家都很紧张。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥昨天在比赛里淘汰了三个人。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们队很快就淘汰出局了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛每天淘汰一个人，最后只有三个人。", "target_word": "淘汰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在歌唱比赛中被淘汰了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "淘汰了", "label": "体标（完成）"}, {"form": "被淘汰", "label": "被动式"}], "register": "中性", "sense_fingerprint": "比赛中输的人出局，不能继续比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b1368f-3c85-4d4d-9d9f-204f7c23b63d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：比赛中输掉的队伍出局，不能继续比赛，符合句意。"}, {"text": "参加", "is_correct": false, "explanation": "语义：“参加”的主语应是队伍或人，比赛本身不能参加，句意不通。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的宾语是活动，不是队伍，“举办八个队”搭配不当。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“表演”的宾语是节目，不能用于“队”。"}], "explanations": {"淘汰": "淘汰：比赛中输掉的队伍出局，不能继续比赛，符合句意。", "参加": "语义：“参加”的主语应是队伍或人，比赛本身不能参加，句意不通。", "举办": "搭配：“举办”的宾语是活动，不是队伍，“举办八个队”搭配不当。", "表演": "搭配：“表演”的宾语是节目，不能用于“队”。"}, "sentence_index": 0, "correct_answer": "淘汰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们队淘汰了这次比赛。", "explanation": "这里应该用〈赢得〉。淘汰只用于队伍或选手出局，比赛本身不能被淘汰。"}, {"text": "学校淘汰了这次歌唱比赛的奖金。", "explanation": "这里应该用〈发放〉。淘汰是使选手或队伍出局，奖金不能被淘汰，应说发放。"}, {"text": "他淘汰了这座城市。", "explanation": "这里应该用〈离开〉。淘汰是使选手或队伍出局，城市不能被淘汰，应说“他离开了这座城市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：在比赛中输掉而出局，符合句意。"}, {"text": "辩论", "is_correct": false, "explanation": "语义：“辩论”是就问题争论，与在比赛里淘汰人不符。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”的对象是作品或方案，不能说“设计三个人”。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”的对象是文章或计划，不能说“修改三个人”。"}], "explanations": {"淘汰": "淘汰：在比赛中输掉而出局，符合句意。", "辩论": "语义：“辩论”是就问题争论，与在比赛里淘汰人不符。", "设计": "搭配：“设计”的对象是作品或方案，不能说“设计三个人”。", "修改": "搭配：“修改”的对象是文章或计划，不能说“修改三个人”。"}, "sentence_index": 6, "correct_answer": "淘汰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在歌唱比赛中淘汰了一首歌。", "explanation": "这里应该用〈演唱〉。淘汰用于选手或队伍出局，歌曲不能被淘汰出局，应说演唱。"}, {"text": "评委淘汰了她的掌声。", "explanation": "这里应该用〈获得〉。淘汰是使选手或队伍出局，掌声不能被淘汰，应说获得。"}, {"text": "选手淘汰了领先。", "explanation": "这里应该用〈保持〉。淘汰是使人出局，“领先”这种状态不能被淘汰，应说保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裁判把那个队淘汰。", "corrected_sentence": "裁判把那个队淘汰了。", "error_description": "“把”字句中，“淘汰”后面要带“了”才完整。“裁判把那个队淘汰”不完整，应说“裁判把那个队淘汰了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场比赛被淘汰了四个队。", "corrected_sentence": "这场比赛淘汰了四个队。", "error_description": "“淘汰”带宾语“四个队”时不能加“被”。“这场比赛被淘汰了四个队”错误，应去掉“被”，说“这场比赛淘汰了四个队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
