INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "王子是国王的儿子。", "primary_collocate": null, "pronunciation": "wáng zǐ", "ipa": "waŋ˧˥ tsɹ̩˨˩", "syllable_count": 2, "sentences": [{"text": "王子是国王的儿子。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩在书里看到了一个年轻的王子。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王很爱自己的王子。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子骑着白马来到城门前。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子和公主在城堡里结婚了。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的王子勇敢又善良。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王死后,王子成了新国王。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子今年十岁,正在学骑马。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主喜欢邻国的王子。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子把剑给了国王。", "target_word": "王子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小王子", "label": "复合"}, {"form": "王子们", "label": "复数"}], "register": "中性", "sense_fingerprint": "国王的儿子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119b896a-7a6c-482d-97ff-7470b8956fae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "王子", "is_correct": true, "explanation": "王子 wáng zǐ 指国王的儿子，是本词。"}, {"text": "房子", "is_correct": false, "explanation": "声母不同：房 fáng 是 f，王 wáng 是 w。房子意思是房屋，不是国王的儿子。"}, {"text": "丸子", "is_correct": false, "explanation": "韵母不同：丸 wán 是 -an，王 wáng 是 -ang。丸子意思是肉丸。"}, {"text": "网子", "is_correct": false, "explanation": "声调不同：网 wǎng 是第三声，王 wáng 是第二声。网子意思是网状物。"}], "explanations": {"王子": "王子 wáng zǐ 指国王的儿子，是本词。", "房子": "声母不同：房 fáng 是 f，王 wáng 是 w。房子意思是房屋，不是国王的儿子。", "丸子": "韵母不同：丸 wán 是 -an，王 wáng 是 -ang。丸子意思是肉丸。", "网子": "声调不同：网 wǎng 是第三声，王 wáng 是第二声。网子意思是网状物。"}, "sentence_index": null, "correct_answer": "王子"}, "level_3": {"options": [{"text": "王子", "is_correct": true, "explanation": "王子指国王的儿子，与句中的定义一致。"}, {"text": "公主", "is_correct": false, "explanation": "语义：公主指国王的女儿，与“儿子”冲突。"}, {"text": "国王", "is_correct": false, "explanation": "语义：国王是儿子的父亲，不能同时是儿子。"}, {"text": "城堡", "is_correct": false, "explanation": "搭配：“儿子”只能指人，城堡不能是国王的儿子。"}], "explanations": {"王子": "王子指国王的儿子，与句中的定义一致。", "公主": "语义：公主指国王的女儿，与“儿子”冲突。", "国王": "语义：国王是儿子的父亲，不能同时是儿子。", "城堡": "搭配：“儿子”只能指人，城堡不能是国王的儿子。"}, "sentence_index": 0, "correct_answer": "王子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "王子是国王的女儿，她很温柔。", "explanation": "这里应该用〈公主〉。王子指男性，国王的女儿要用“公主”。"}, {"text": "王子十八岁那年就嫁进王宫，为国王生下了第一个儿子。", "explanation": "这里应该用〈王后〉。王后是国王的妻子，能为国王生育；王子指国王的儿子，是男性，不能生育。"}, {"text": "王子怀孕六个月，宫里的人都在为他准备婴儿的衣服。", "explanation": "这里应该用〈女王〉。女王是女性，能怀孕；王子指男性的儿子，不能怀孕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "王子", "is_correct": true, "explanation": "王子是国王的儿子，国王死后他成为新国王，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能成为国王。"}, {"text": "城堡", "is_correct": false, "explanation": "搭配：“成为国王”的主语必须是人，城堡不能。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是人，不能当新国王。"}], "explanations": {"王子": "王子是国王的儿子，国王死后他成为新国王，符合句意。", "石头": "语义：石头不能成为国王。", "城堡": "搭配：“成为国王”的主语必须是人，城堡不能。", "花园": "语义：花园不是人，不能当新国王。"}, "sentence_index": 6, "correct_answer": "王子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "王子是国王的妻子，每天陪着国王。", "explanation": "这里应该用〈王妃〉。王子指男性的儿子，国王的妻子要用“王妃”。"}, {"text": "王子的父亲是一名卖菜的小贩，每天早上五点就去市场。", "explanation": "这里应该用〈小贩的儿子〉。王子指国王的儿子，句中父亲是小贩，与词义矛盾。"}, {"text": "这位王子的父亲是一名普通的农民，每天在田里干活。", "explanation": "这里应该用〈农民的儿子〉。王子的父亲必须是国王，句中父亲是农民，与词义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城堡里住着一只王子。", "corrected_sentence": "城堡里住着一位王子。", "error_description": "量词错误：“王子”指人，应说“一位王子”。“只”多用于动物，不能用于王子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宴会上来了三个王子们。", "corrected_sentence": "宴会上来了三个王子。", "error_description": "复数错误：“三个”已经表示数量，后面不能再加“们”，应说“三个王子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '037d054d-74be-4854-8e2d-240468c4802e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
