INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94545, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "甲是排在第一个的那个，常常用来叫一个人。", "primary_collocate": null, "pronunciation": "jiǎ", "ipa": "tɕja²¹⁴", "syllable_count": 1, "sentences": [{"text": "甲和乙是好朋友。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲说他今天很忙。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲问乙：“你去不去？”", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，甲得了第一，乙得了第二。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲先走，乙在家等他。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲给了乙一本书。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲今天来得很早，乙来得很晚。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，甲不知道，乙也不知道。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲把钥匙给了乙。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲和乙在公园里跳舞。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "甲方", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来称呼第一个人，常与乙并用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2667f8-e9d0-427d-8665-36e8f6ad299f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94545, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。甲是排在第一个的那个，常用来称呼一个人。"}, {"text": "家", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。"}, {"text": "姐", "is_correct": false, "explanation": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是姐姐。"}, {"text": "解", "is_correct": false, "explanation": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是解开。"}], "explanations": {"甲": "正确。甲是排在第一个的那个，常用来称呼一个人。", "家": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。", "价": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。", "姐": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是姐姐。", "解": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是解开。"}, "sentence_index": null, "correct_answer": "甲"}, "level_3": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。甲指排第一的那个人，可以与乙并称。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能和乙做朋友。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能和人交朋友。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“是好朋友”的主语要指人，不能说空气和乙是好朋友。"}], "explanations": {"甲": "正确。甲指排第一的那个人，可以与乙并称。", "桌子": "语义：桌子是物品，不能和乙做朋友。", "石头": "语义：石头没有生命，不能和人交朋友。", "空气": "搭配：“是好朋友”的主语要指人，不能说空气和乙是好朋友。"}, "sentence_index": 0, "correct_answer": "甲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵穿上甲，冲进了敌阵。", "explanation": "这里的甲指古代护身的铠甲，是另一个意思，与用来称呼第一个人的甲无关。"}, {"text": "这家饭店的服务甲天下。", "explanation": "这里的甲是“第一、最好”的意思，取自“甲天下”，不是称呼人的甲。"}, {"text": "他考试得了甲，老师很高兴。", "explanation": "这里的甲指成绩等级，是另一个意思，与“排第一的那个人”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94545, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。甲是排在第一个的那个，常用来称呼一个人。"}, {"text": "加", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。"}, {"text": "夹", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是夹住。"}, {"text": "架", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 jiǎ 韵尾不同（多了 n），意思是减少。"}], "explanations": {"甲": "正确。甲是排在第一个的那个，常用来称呼一个人。", "加": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。", "夹": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是夹住。", "架": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。", "减": "jiǎn 与 jiǎ 韵尾不同（多了 n），意思是减少。"}, "sentence_index": null, "correct_answer": "甲"}, "level_3": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。甲今天先到，符合“来得很早”的句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不会“来得很早”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“来得很早”说的是人或事情的到达，窗户不能说来。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔没有行动，不能说“来得很早”。"}], "explanations": {"甲": "正确。甲今天先到，符合“来得很早”的句意。", "书包": "语义：书包是物品，不会“来得很早”。", "窗户": "搭配：“来得很早”说的是人或事情的到达，窗户不能说来。", "铅笔": "语义：铅笔没有行动，不能说“来得很早”。"}, "sentence_index": 6, "correct_answer": "甲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乌龟的甲很硬，能保护它的身体。", "explanation": "这里的甲指龟的外壳，是另一个义项，与用来称呼人的甲无关。"}, {"text": "她每天都会把甲修剪得很短。", "explanation": "这里的甲指指甲，是另一个义项，与用来称呼人的甲无关。"}, {"text": "天干里，甲排在第一位。", "explanation": "这里的甲指天干的第一个字，是另一个义项，与用来称呼人的甲无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "甲和乙都很来了。", "corrected_sentence": "甲和乙都来了。", "error_description": "错误：程度副词“很”不能修饰动词“来”，应去掉“很”，说“甲和乙都来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "甲朋友住在公园旁边。", "corrected_sentence": "甲的朋友住在公园旁边。", "error_description": "错误：“甲”修饰“朋友”时，中间要加“的”，应说“甲的朋友”，不能说“甲朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
