INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94546, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天干的第一位；排第一；也指指甲、铠甲。", "primary_collocate": null, "pronunciation": "jiǎ", "ipa": "tɕja²¹⁴", "syllable_count": 1, "sentences": [{"text": "天干的第一个字是甲。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲、乙、丙、丁是天干的前四个字。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桂林山水甲天下。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，他得了甲。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在我的作文上写了一个甲。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲排在天干的第一位。", "target_word": "甲", "complexity_tier": "T3", "furigana": "jiǎ", "sentence_source": "generated"}, {"text": "天干里，甲排在乙的前面。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天干有十个字，甲是第一个。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩一直是甲，从来没有得过乙。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打分的时候，最好的是甲，第二是乙。", "target_word": "甲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指甲", "label": "复合"}, {"form": "甲骨文", "label": "复合"}], "register": "中性", "sense_fingerprint": "天干第一位，引申为排第一、等级最高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2667f8-e9d0-427d-8665-36e8f6ad299f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。甲是天干的第一位，也可指排第一。"}, {"text": "加", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。"}, {"text": "价", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。"}, {"text": "姐", "is_correct": false, "explanation": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是姐姐。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 jiǎ 韵尾不同（多了 n），意思是减少。"}], "explanations": {"甲": "正确。甲是天干的第一位，也可指排第一。", "加": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是增加。", "价": "jià（第四声）与 jiǎ（第三声）声调不同，意思是价格。", "姐": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是姐姐。", "减": "jiǎn 与 jiǎ 韵尾不同（多了 n），意思是减少。"}, "sentence_index": null, "correct_answer": "甲"}, "level_3": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。甲是天干的第一个字。"}, {"text": "乙", "is_correct": false, "explanation": "语义：乙是天干的第二个字，与“第一个字”相矛盾。"}, {"text": "丙", "is_correct": false, "explanation": "语义：丙是天干的第三个字，不是第一个。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：天干是字，不能说桌子是天干的第一个字。"}], "explanations": {"甲": "正确。甲是天干的第一个字。", "乙": "语义：乙是天干的第二个字，与“第一个字”相矛盾。", "丙": "语义：丙是天干的第三个字，不是第一个。", "桌子": "搭配：天干是字，不能说桌子是天干的第一个字。"}, "sentence_index": 0, "correct_answer": "甲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "甲和乙下午一起去图书馆。", "explanation": "这里的甲是称呼人的代号，指某个人，与天干第一位、排第一、成绩等级的甲不是同一义项。"}, {"text": "这只乌龟的甲很硬。", "explanation": "这里的甲指龟的外壳，不在本词条所列的指甲、铠甲之内，与成绩等级无关。"}, {"text": "这件事甲不同意，乙也不同意。", "explanation": "这里的甲作为代号指某一方的人，与天干第一位、排第一、成绩等级的甲不是同一义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94546, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。甲是天干的第一位，也可指排第一。"}, {"text": "家", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。"}, {"text": "架", "is_correct": false, "explanation": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。"}, {"text": "解", "is_correct": false, "explanation": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是解开。"}, {"text": "夹", "is_correct": false, "explanation": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是夹住。"}], "explanations": {"甲": "正确。甲是天干的第一位，也可指排第一。", "家": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是家。", "架": "jià（第四声）与 jiǎ（第三声）声调不同，意思是架子。", "解": "jiě 与 jiǎ 韵母不同（ie 与 ia），意思是解开。", "夹": "jiā（第一声）与 jiǎ（第三声）声调不同，意思是夹住。"}, "sentence_index": null, "correct_answer": "甲"}, "level_3": {"options": [{"text": "甲", "is_correct": true, "explanation": "正确。天干里甲排在乙的前面。"}, {"text": "丁", "is_correct": false, "explanation": "语义：丁排在乙的后面，与“排在乙的前面”相矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：天干是字，窗户不能参与排序。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：排序需要排列的对象，空气不能说排在乙的前面。"}], "explanations": {"甲": "正确。天干里甲排在乙的前面。", "丁": "语义：丁排在乙的后面，与“排在乙的前面”相矛盾。", "窗户": "搭配：天干是字，窗户不能参与排序。", "空气": "搭配：排序需要排列的对象，空气不能说排在乙的前面。"}, "sentence_index": 6, "correct_answer": "甲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "甲在门口等了我半个小时。", "explanation": "这里的甲是称呼人的代号，指某个人，与天干第一位、排第一、成绩等级的甲不是同一义项。"}, {"text": "螃蟹脱了甲，就会变得很软。", "explanation": "这里的甲指蟹的外壳，是“甲”的另一个义项，与天干第一位或成绩等级无关。"}, {"text": "设甲为未知数，再解这个方程。", "explanation": "这里的甲是代表未知数的符号，是另一种用法，与天干第一位、排第一、成绩等级的甲不是同一义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天干的第一个字是一位甲。", "corrected_sentence": "天干的第一位是甲。", "error_description": "错误：“位”是指人的量词，不能修饰天干中的字“甲”，应去掉量词，说“天干的第一个字是甲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天干的头一位是甲们，乙排在后面。", "corrected_sentence": "天干的头一位是甲，乙排在后面。", "error_description": "错误：“甲”作字名时后面不加“们”，应说“甲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
