INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94547, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "当事人是这件事里面的那个人。", "primary_collocate": null, "pronunciation": "dāng shì rén", "ipa": "taŋ˥ ʂɻ̩˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "这件事的当事人是我弟弟。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当事人今天没有来学校。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察先问了当事人几个问题。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事只有当事人最清楚。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是这次吵架的当事人之一。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当事人不想谈这件事。", "target_word": "当事人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师请两个当事人一起过来。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情过去了，当事人都不生气了。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者想找当事人聊一聊。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你是当事人，应该自己说清楚。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位当事人", "label": "量词"}, {"form": "當事人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "当事人|名词|事情里面的那个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当事人", "is_correct": true, "explanation": "当事人指这件事里面的那个人，填入后「这件事的当事人是我弟弟」通顺。"}, {"text": "草稿", "is_correct": false, "explanation": "语义：草稿是文字材料，不能是这件事里的人。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具是器具，不能说成这件事里的人。"}, {"text": "当局", "is_correct": false, "explanation": "语义：「当局」指政府机关，不是这件事里的人，不能说「这件事的当局是我弟弟」。"}], "explanations": {"当事人": "当事人指这件事里面的那个人，填入后「这件事的当事人是我弟弟」通顺。", "草稿": "语义：草稿是文字材料，不能是这件事里的人。", "工具": "语义：工具是器具，不能说成这件事里的人。", "当局": "语义：「当局」指政府机关，不是这件事里的人，不能说「这件事的当局是我弟弟」。"}, "sentence_index": 0, "correct_answer": "当事人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官请当事人出庭作证，当事人与案件无关。", "explanation": "这里应该用〈证人〉。当事人与案件有直接关系，不能说与案件无关。"}, {"text": "路过的当事人报了警。", "explanation": "这里应该用〈路人〉。当事人是事件中有直接关系的人，路过的旁人不是当事人。"}, {"text": "我只是当事人，与这件事没有关系。", "explanation": "这里应该用〈旁观者〉。当事人与事件有直接关系，说自己与这件事没有关系，应用〈旁观者〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当事人", "is_correct": true, "explanation": "当事人指与事件有直接关系的人，「老师请两个当事人一起过来」通顺。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是练习题，不能被老师请来一起过来。"}, {"text": "试卷", "is_correct": false, "explanation": "语义：试卷是纸张，不能一起过来。"}, {"text": "当局", "is_correct": false, "explanation": "语义：「当局」指政府机关，不能被老师请来一起过来。"}], "explanations": {"当事人": "当事人指与事件有直接关系的人，「老师请两个当事人一起过来」通顺。", "作业": "语义：作业是练习题，不能被老师请来一起过来。", "试卷": "语义：试卷是纸张，不能一起过来。", "当局": "语义：「当局」指政府机关，不能被老师请来一起过来。"}, "sentence_index": 6, "correct_answer": "当事人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事只有一只当事人最清楚。", "explanation": "这里应该用〈位〉。〈当事人〉指人，应数作〈位〉，不能用来数动物或成对物品。"}, {"text": "这件事只有一本当事人最清楚。", "explanation": "这里应该用〈位〉。〈当事人〉指人，应数作〈位〉，不能用来数书籍等物品。"}, {"text": "这件事只有一条当事人最清楚。", "explanation": "这里应该用〈位〉。〈当事人〉指人，应数作〈位〉，不能用来数细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的两只当事人都在场。", "corrected_sentence": "这件事的两位当事人都在场。", "error_description": "错误：「两只当事人」。正确：「两位当事人」。「只」用于动物或成对物品中的一件，指人应用「位」或「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请两当事人明天一起来。", "corrected_sentence": "请两位当事人明天一起来。", "error_description": "错误：「两当事人」。正确：「两位当事人」。数词和名词之间要加量词，指人的「当事人」应用量词「位」，不能省去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
