INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "确切的一百年时间，即一个世纪。", "primary_collocate": null, "pronunciation": "bǎi nián", "ipa": "paɪ̯²¹⁴ nʲɛn³⁵", "syllable_count": 2, "sentences": [{"text": "这所学校有百年历史。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个世纪就是百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔从动工到竣工，前后恰好百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年是学校成立百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是百年的故事。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "百年里，这座城市换了三个名字。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵老树已经站了百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，他家的茶店开了百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去百年中，世界变化很大。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河百年前很干净，现在不行了。", "target_word": "百年", "complexity_tier": "T3", "furigana": "zhè tiáo hé bǎi nián qián hěn gān jìng, xiàn zài bù xíng le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "百年老店", "label": "复合"}], "register": "中性", "sense_fingerprint": "确切的一百年时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2667f8-e9d0-427d-8665-36e8f6ad299f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：百年，bǎi nián，指确切的一百年。"}, {"text": "拜年", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是新年互相问候。"}, {"text": "半年", "is_correct": false, "explanation": "bàn（第四声）与 bǎi（第三声）韵母不同（an 与 ai），声调也不同，意思是六个月。"}, {"text": "百炼", "is_correct": false, "explanation": "百炼（bǎi liàn）与百年声母 n／l 不同，声调也不同（第四声），意思是经过反复锤炼。"}], "explanations": {"百年": "正确：百年，bǎi nián，指确切的一百年。", "拜年": "bài（第四声）与 bǎi（第三声）声调不同，意思是新年互相问候。", "半年": "bàn（第四声）与 bǎi（第三声）韵母不同（an 与 ai），声调也不同，意思是六个月。", "百炼": "百炼（bǎi liàn）与百年声母 n／l 不同，声调也不同（第四声），意思是经过反复锤炼。"}, "sentence_index": null, "correct_answer": "百年"}, "level_3": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：“百年历史”指一百年的历史，是确切的时间。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”不是时间，不能用来表示学校有多少年的历史。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“名声”不能用来衡量“历史”的长短，“有……历史”需要时间词。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”指房间，不能说“有教室历史”来表示年数。"}], "explanations": {"百年": "正确：“百年历史”指一百年的历史，是确切的时间。", "食堂": "语义：“食堂”不是时间，不能用来表示学校有多少年的历史。", "名声": "搭配：“名声”不能用来衡量“历史”的长短，“有……历史”需要时间词。", "教室": "语义：“教室”指房间，不能说“有教室历史”来表示年数。"}, "sentence_index": 0, "correct_answer": "百年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔只用了三个礼拜就建好了，却说花了百年。", "explanation": "这里应该用〈几周〉。三周就能建好的工程不能说花了“百年”，“百年”指确切的一百年，与几周的时长不符。"}, {"text": "他今年百年了。", "explanation": "这里应该用〈百岁〉。说人的年龄用“百岁”，“百年”不用于人的年纪。"}, {"text": "他百年都在这所学校工作。", "explanation": "这里应该用〈一辈子〉。“百年”指一个世纪或很长的时间，不能当作“一辈子”来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：“站了”后接时间长度，“百年”可作时量补语。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”指一顿饭，不是时间长度，不能用来表示站立的时间。"}, {"text": "歌曲", "is_correct": false, "explanation": "配价：“站”是不及物动词，后面不能接“歌曲”这样的名词作宾语。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是物品，不能用来计算站立的时长。"}], "explanations": {"百年": "正确：“站了”后接时间长度，“百年”可作时量补语。", "午饭": "语义：“午饭”指一顿饭，不是时间长度，不能用来表示站立的时间。", "歌曲": "配价：“站”是不及物动词，后面不能接“歌曲”这样的名词作宾语。", "眼镜": "语义：“眼镜”是物品，不能用来计算站立的时长。"}, "sentence_index": 6, "correct_answer": "百年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的时长是百年。", "explanation": "这里应该用〈三分钟〉。歌曲时长以分钟计，“百年”指确切的一百年，不能用来表示歌曲的长度。"}, {"text": "这辆车的百年只有五年。", "explanation": "这里应该用〈寿命〉。说物体能用多久要用“寿命”，“百年”不能指车的使用年限。"}, {"text": "他百年都在这条河边生活。", "explanation": "这里应该用〈一生〉。“百年”指一个世纪或很长的时间，不能当作“一生”来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校已经有一位百年了。", "corrected_sentence": "这所学校已经有百年了。", "error_description": "量词错误：“位”只用于人，不能修饰时间词“百年”，应说“有百年了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河很百年了，现在不行了。", "corrected_sentence": "这条河百年了，现在不行了。", "error_description": "副词错误：“很”不修饰“百年”这样的时间词，应说“百年了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
