INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大家；许多人。", "primary_collocate": null, "pronunciation": "zhòng rén", "ipa": "tʂʊŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这位医生的好心，众人都知道。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门，众人都站了起来。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里要修桥，众人你一言我一语地讨论着。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请众人坐下，然后开始开会。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法是众人想出来的。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板向众人表示感谢。", "target_word": "众人", "complexity_tier": "T3", "furigana": "lǎobǎn xiàng zhòngrén biǎoshì gǎnxiè", "sentence_source": "generated"}, {"text": "天黑了，众人还在山上找孩子。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把好消息告诉了众人。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的歌手一唱，众人跟着唱了起来。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，众人都回老家吃饭。", "target_word": "众人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "眾人", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "泛指大家、许多人，可作主语或宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3325f6b1-73dc-4a1c-9d96-b519a163574c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墙", "is_correct": false, "explanation": "语义：墙不会知道别人的事情。"}, {"text": "众人", "is_correct": true, "explanation": "众人：泛指大家，与“都知道”搭配自然。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车没有知觉，不会知道别人的好心。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有知觉，不可能知道事情。"}], "explanations": {"墙": "语义：墙不会知道别人的事情。", "众人": "众人：泛指大家，与“都知道”搭配自然。", "汽车": "语义：汽车没有知觉，不会知道别人的好心。", "石头": "语义：石头没有知觉，不可能知道事情。"}, "sentence_index": 0, "correct_answer": "众人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三个众人走进了房间。", "explanation": "这里应该用〈三个人〉。众人泛指许多人，不能与“三个”这样的具体数量搭配。"}, {"text": "那只众人刚跑过去。", "explanation": "这里应该用〈那个人〉。众人指许多人，不能用量词“只”计数。"}, {"text": "他的众人都来了。", "explanation": "这里应该用〈亲友〉。众人泛指不特定的许多人，不能用“他的”限定为某个人的亲友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，不能去山上找孩子。"}, {"text": "众人", "is_correct": true, "explanation": "众人：指许多人，与“还在山上找孩子”的情境相符。"}, {"text": "白天", "is_correct": false, "explanation": "语义：“白天”与“天黑了”矛盾，白天不能去找孩子。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会去山上找孩子。"}], "explanations": {"房子": "语义：房子是建筑物，不能去山上找孩子。", "众人": "众人：指许多人，与“还在山上找孩子”的情境相符。", "白天": "语义：“白天”与“天黑了”矛盾，白天不能去找孩子。", "石头": "语义：石头不会去山上找孩子。"}, "sentence_index": 6, "correct_answer": "众人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "众人只是个普通人，没什么特别的。", "explanation": "这里应该用〈我〉。众人指许多人，不能用来指说话的人自己，而且与“个”这种单数量词矛盾。"}, {"text": "这头众人都回老家了。", "explanation": "这里应该用〈这些人〉。众人指人群，不能用动物量词“头”计数。"}, {"text": "他把众人装进了箱子。", "explanation": "这里应该用〈东西〉。众人指人群，不能像物品一样装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划是众人们讨论出来的。", "corrected_sentence": "这个计划是众人讨论出来的。", "error_description": "“众人”本身已表示多人，后面不能再加“们”；写成“众人们”属于重复表示复数，应改为“众人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放假的时候，一个众人都去看望父母。", "corrected_sentence": "放假的时候，众人都去看望父母。", "error_description": "“众人”是泛指的复数概念，不能与数量词“一个”组合；应去掉“一个”，写成“众人都去看望父母”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
