INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94562, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用重物撞击使破碎。", "primary_collocate": null, "pronunciation": "zá", "ipa": "tsa˧˥", "syllable_count": 1, "sentences": [{"text": "他用锤子把石头砸碎了。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用大锤砸开了那堵墙。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地把手机砸在地上。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人用石头砸了商店的玻璃。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷砸开窗户，爬进了屋子。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用石头砸核桃，壳很快就碎了。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰太厚了，我们只能用铁棒砸。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧电视砸了，扔进了垃圾桶。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的球砸破了邻居家的窗。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不小心砸了妈妈的杯子。", "target_word": "砸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "砸了", "label": "体标"}, {"form": "砸过", "label": "体标"}, {"form": "砸碎", "label": "复合"}, {"form": "砸开", "label": "复合"}], "register": "中性", "sense_fingerprint": "用重物撞击，使东西破碎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "砸", "is_correct": true, "explanation": "“砸”表示用重物撞击使破碎，与“用锤子把石头……碎了”相符。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”要用刀具等有刃的工具，不能用锤子来切。"}, {"text": "煮", "is_correct": false, "explanation": "语义：石头不能用来煮，与“石头……碎了”的意思矛盾。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”一般用手或撕裂的动作，与“用锤子”不搭配。"}], "explanations": {"砸": "“砸”表示用重物撞击使破碎，与“用锤子把石头……碎了”相符。", "切": "搭配：“切”要用刀具等有刃的工具，不能用锤子来切。", "煮": "语义：石头不能用来煮，与“石头……碎了”的意思矛盾。", "撕": "搭配：“撕”一般用手或撕裂的动作，与“用锤子”不搭配。"}, "sentence_index": 0, "correct_answer": "砸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他轻轻砸门，没有人回答。", "explanation": "这里应该用〈敲〉。“砸”指用力撞击使破碎，轻轻地敲门要用“敲”。"}, {"text": "他用一根羽毛砸了我一下。", "explanation": "这里应该用〈拂〉。“砸”要用重物用力撞击，用羽毛轻拂则要用“拂”。"}, {"text": "他生气地把信砸了。", "explanation": "这里应该用〈撕〉。信纸不能被重物撞碎，要把纸弄破应说“撕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砸", "is_correct": true, "explanation": "“砸”表示用重物打下去使东西破碎，与“用铁棒”相符。"}, {"text": "烤", "is_correct": false, "explanation": "语义：冰不能用来烤，与“冰太厚了”的语境矛盾。"}, {"text": "煎", "is_correct": false, "explanation": "语义：冰不能用煎的方式处理，与句中的语境不合。"}, {"text": "削", "is_correct": false, "explanation": "搭配：“削”要用刀具，铁棒不能用来削。"}], "explanations": {"砸": "“砸”表示用重物打下去使东西破碎，与“用铁棒”相符。", "烤": "语义：冰不能用来烤，与“冰太厚了”的语境矛盾。", "煎": "语义：冰不能用煎的方式处理，与句中的语境不合。", "削": "搭配：“削”要用刀具，铁棒不能用来削。"}, "sentence_index": 6, "correct_answer": "砸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她砸下了一朵花。", "explanation": "这里应该用〈摘〉。摘花要用手轻轻摘下，“砸”只用于重物撞碎的东西，不能用来摘花。"}, {"text": "他用脚轻轻砸了一下玻璃。", "explanation": "这里应该用〈碰〉。“砸”要用重物用力撞击使东西破碎，轻轻碰一下要用“碰”。"}, {"text": "妈妈不小心砸坏了我的头发。", "explanation": "这里应该用〈剪〉。头发要用剪子剪，“砸”只用于重物撞碎的东西，不能用来处理头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把旧花瓶砸。", "corrected_sentence": "她把旧花瓶砸了。", "error_description": "把字句不完整：“把”字句中的动词后要带“了”或补语，单独的“砸”不能直接作“把”字句的谓语。错误形式「她把旧花瓶砸」，正确形式「她把旧花瓶砸了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们用铁棒把冰开砸了。", "corrected_sentence": "我们用铁棒把冰砸开了。", "error_description": "补语位置错误：结果补语“开”应放在动词“砸”之后，不能放在动词前。错误形式「把冰开砸了」，正确形式「把冰砸开了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
