INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "硕士是在大学毕业后，又继续读书，得到的一种学位。", "primary_collocate": null, "pronunciation": "shuò shì", "ipa": "ʂwɔ˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "大学毕业后，他决定继续读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，读硕士要先考试。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想读硕士，所以每天学习到很晚。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李大学毕业就工作了，没有读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读硕士的时候住在学校里。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟明年考硕士，现在很忙。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读硕士的第一年，他学了很多新东西。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他硕士毕业后，进了一家大公司。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国外读完了硕士，才回国工作。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸希望我大学以后再读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "硕士生", "label": "复合"}, {"form": "硕士学位", "label": "复合"}, {"form": "碩士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大学毕业后继续读书所得的学位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1cc6afb-d9ef-4bf0-9c1b-33171e53fc3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硕士", "is_correct": true, "explanation": "硕士是大学毕业后继续深造所得的学位，与“大学毕业后继续读”相合。"}, {"text": "小学", "is_correct": false, "explanation": "语义：大学毕业后继续读的是更高的学位，“小学”是更低的学段，与语境矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“读”搭配的是书籍、课程等，不能说“读房子”。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”是食物，不能用“读”，“继续读早饭”不通。"}], "explanations": {"硕士": "硕士是大学毕业后继续深造所得的学位，与“大学毕业后继续读”相合。", "小学": "语义：大学毕业后继续读的是更高的学位，“小学”是更低的学段，与语境矛盾。", "房子": "搭配：“读”搭配的是书籍、课程等，不能说“读房子”。", "早饭": "搭配：“早饭”是食物，不能用“读”，“继续读早饭”不通。"}, "sentence_index": 0, "correct_answer": "硕士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "表姐是硕士，还没有毕业。", "explanation": "这里应该用〈研究生〉。硕士是已经取得的学位，不能说“还没有毕业”；研究生指正在读书的学生。"}, {"text": "我哥哥是硕士，还没拿到学位。", "explanation": "这里应该用〈大学生〉。硕士已经拿到学位，不能说“还没拿到学位”；大学生指还在读书的学生。"}, {"text": "他去年参观了硕士。", "explanation": "这里应该用〈学校〉。“参观”的对象是场所，硕士是学位，不能被参观；参观的对象应是学校这类场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硕士", "is_correct": true, "explanation": "“读”后面接学位，硕士是研究生阶段的学位，与“读……的第一年”相合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“读”的对象是学业，不能说“读天气”。"}, {"text": "驾照", "is_correct": false, "explanation": "语义：驾照是考取的证件，不是要读的学业内容，与“读”的语境不合。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“雨伞”是物品，不能用“读”，“读雨伞的第一年”不通。"}], "explanations": {"硕士": "“读”后面接学位，硕士是研究生阶段的学位，与“读……的第一年”相合。", "天气": "搭配：“读”的对象是学业，不能说“读天气”。", "驾照": "语义：驾照是考取的证件，不是要读的学业内容，与“读”的语境不合。", "雨伞": "搭配：“雨伞”是物品，不能用“读”，“读雨伞的第一年”不通。"}, "sentence_index": 6, "correct_answer": "硕士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天把硕士切成了两半。", "explanation": "这里应该用〈蛋糕〉。蛋糕是实物，可以切成两半；硕士是学位，不是可以切开的东西。"}, {"text": "我们把硕士摆在了货架上。", "explanation": "这里应该用〈商品〉。商品可以陈列在货架上；硕士是学位，不是商品。"}, {"text": "他把硕士擦得干干净净。", "explanation": "这里应该用〈证书〉。证书是实物，可以擦拭；硕士是学位，不是可以擦拭的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年考上着硕士。", "corrected_sentence": "他去年考上了硕士。", "error_description": "错误：“考上着硕士”；正确：“考上了硕士”。结果补语“上”后表示完成应用“了”，不用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拿到了一本硕士，现在在大学教书。", "corrected_sentence": "他拿到了一个硕士，现在在大学教书。", "error_description": "错误：“一本硕士”；正确：“一个硕士”。“硕士”是学位，量词应用“个”，“本”用于书册，不能用于学位。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94564, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94564, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学位的一种，高于学士，低于博士。", "primary_collocate": null, "pronunciation": "shuò shì", "ipa": "ʂwɔ˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "她去年读完了硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学历是硕士，比学士高。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去英国读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥大学毕业后，又读了三年硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读完硕士以后，她想再读博士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作要求硕士以上学历。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先拿了学士，又拿了硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在北京大学读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读硕士比读学士多学两三年。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没读硕士，直接去工作了。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "硕士生", "label": "复合"}, {"form": "硕士学位", "label": "复合"}, {"form": "碩士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学位等级，高于学士、低于博士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1cc6afb-d9ef-4bf0-9c1b-33171e53fc3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硕士", "is_correct": true, "explanation": "硕士是学位，“读完了”后面接学位，与“去年”读完的语境相合。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“读”搭配的是书籍、课程等，不能说“读完了房子”。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”是食物，不能用“读”，“读完了早饭”不通。"}, {"text": "驾照", "is_correct": false, "explanation": "语义：“读完”指学完课程，驾照是考取的证件，不是学业内容。"}], "explanations": {"硕士": "硕士是学位，“读完了”后面接学位，与“去年”读完的语境相合。", "房子": "搭配：“读”搭配的是书籍、课程等，不能说“读完了房子”。", "早饭": "搭配：“早饭”是食物，不能用“读”，“读完了早饭”不通。", "驾照": "语义：“读完”指学完课程，驾照是考取的证件，不是学业内容。"}, "sentence_index": 0, "correct_answer": "硕士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我表哥现在是硕士，还没有毕业。", "explanation": "这里应该用〈研究生〉。硕士是已经取得的学位，不能说“还没有毕业”；研究生指正在读书的学生。"}, {"text": "我弟弟是硕士，明年才会毕业。", "explanation": "这里应该用〈本科生〉。硕士已经取得学位，不能说“明年才毕业”；本科生指还在读大学的学生。"}, {"text": "他的硕士写了三年，终于完成了。", "explanation": "这里应该用〈硕士论文〉。“写”的对象是论文，硕士是学位，不能被写；硕士是完成学业后获得的资格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硕士", "is_correct": true, "explanation": "“先拿了学士，又拿了”之后应是更高一级的学位，硕士高于学士，符合语境。"}, {"text": "小学", "is_correct": false, "explanation": "语义：“小学”是学段，不是可以“拿”的学位，且低于学士，与“先拿了学士，又拿了”不合。"}, {"text": "高中", "is_correct": false, "explanation": "语义：“高中”是学段，不是学位，与前面的“学士”不成为同类，语境不合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“拿”的对象要能拿在手里，不能说“拿了天气”。"}], "explanations": {"硕士": "“先拿了学士，又拿了”之后应是更高一级的学位，硕士高于学士，符合语境。", "小学": "语义：“小学”是学段，不是可以“拿”的学位，且低于学士，与“先拿了学士，又拿了”不合。", "高中": "语义：“高中”是学段，不是学位，与前面的“学士”不成为同类，语境不合。", "天气": "搭配：“拿”的对象要能拿在手里，不能说“拿了天气”。"}, "sentence_index": 6, "correct_answer": "硕士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年出版了硕士。", "explanation": "这里应该用〈论文〉。论文可以出版，硕士是学位，不能被出版。"}, {"text": "他把硕士装进了书包。", "explanation": "这里应该用〈证书〉。证书是实物，可以装进书包；硕士是学位，不能装进书包。"}, {"text": "妈妈把硕士扔进了垃圾桶。", "explanation": "这里应该用〈废纸〉。废纸可以扔进垃圾桶；硕士是学位，不是可以丢弃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐明年就能拿到一只硕士。", "corrected_sentence": "姐姐明年就能拿到一个硕士。", "error_description": "错误：“一只硕士”；正确：“一个硕士”。“硕士”是学位，量词应用“个”，“只”一般用于动物等，不用于学位。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥读过着硕士，现在在大学教书。", "corrected_sentence": "我哥哥读过硕士，现在在大学教书。", "error_description": "错误：“读过着硕士”；正确：“读过硕士”。“过”表示经历，动词后不能同时再加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
