INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结束，停止。", "primary_collocate": null, "pronunciation": "zhōng zhǐ", "ipa": "tʂʊŋ˥ tʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司决定终止和他的合同。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雨，裁判终止了比赛。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司终止了合作。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方不同意，我们只好终止谈判。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行已经终止了这项服务。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们明年一月会终止这份协议。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师决定终止这次实验，因为机器坏了。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，这个计划今天必须终止。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房合同到月底就终止了。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为生病，不得不终止学业。", "target_word": "终止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "终止了", "label": "体标（了）"}, {"form": "终止过", "label": "体标（过）"}, {"form": "終止", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "正式地结束合同、合作、谈判等事情，使其不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3325f6b1-73dc-4a1c-9d96-b519a163574c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的宾语是人或活动，不能带“合同”作宾语。"}, {"text": "终止", "is_correct": true, "explanation": "终止：正式结束已签订的合同，与“合同”搭配自然。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是散开步行的动作，与合同无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不是合同，这句话讲的是结束合同。"}], "explanations": {"欢迎": "搭配：“欢迎”的宾语是人或活动，不能带“合同”作宾语。", "终止": "终止：正式结束已签订的合同，与“合同”搭配自然。", "散步": "语义：“散步”是散开步行的动作，与合同无关。", "唱": "语义：“唱”的对象不是合同，这句话讲的是结束合同。"}, "sentence_index": 0, "correct_answer": "终止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的眼泪突然终止了，大家都松了口气。", "explanation": "这里应该用〈止住〉。终止指正式或整体的结束，眼泪停下来要说“止住”，不能用“终止”。"}, {"text": "他终止了那个苹果，然后吃掉了。", "explanation": "这里应该用〈吃掉〉。终止用于活动、合同等过程，苹果是具体东西，不能被终止。"}, {"text": "他的讲话终止了一会儿。", "explanation": "这里应该用〈中断〉。终止是彻底结束，不能用于暂时停顿，暂时停下要说“中断”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆祝", "is_correct": false, "explanation": "语义：机器坏了，实验无法进行，不宜“庆祝”。"}, {"text": "终止", "is_correct": true, "explanation": "终止：结束这次实验，与“因为机器坏了”的原因相符。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”的宾语是东西或能力，不能说“拥有实验”。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”多用于视频、音乐等，不能用于“实验”。"}], "explanations": {"庆祝": "语义：机器坏了，实验无法进行，不宜“庆祝”。", "终止": "终止：结束这次实验，与“因为机器坏了”的原因相符。", "拥有": "搭配：“拥有”的宾语是东西或能力，不能说“拥有实验”。", "播放": "搭配：“播放”多用于视频、音乐等，不能用于“实验”。"}, "sentence_index": 6, "correct_answer": "终止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终止了篮球队，不再参加比赛。", "explanation": "这里应该用〈解散〉。终止多用于合同、合作、学业等事务的结束，球队这类组织的撤销要说“解散”。"}, {"text": "他一进屋就终止了所有的灯。", "explanation": "这里应该用〈关〉。终止指结束正式或较大的事务，关灯这类小动作要说“关”。"}, {"text": "这次实验的结果终止了，大家都很惊讶。", "explanation": "这里应该用〈得出〉。终止指正在进行的过程被结束，实验结果是得出的，不能说“终止”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在终止了合作。", "corrected_sentence": "我们正在终止合作。", "error_description": "“正在”表示动作正在进行，“了”表示动作已经完成，二者不能同时用在同一个动作上，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项协议到年底就终止着。", "corrected_sentence": "这项协议到年底就终止了。", "error_description": "“终止”表示结束这一瞬间的动作，不能用“着”表示持续状态，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
