INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94571, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "万岁是大家高兴时喊的话，祝愿一个人或一件事长久。", "primary_collocate": null, "pronunciation": "wàn suì", "ipa": "wan˥˩ sweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "比赛赢了，大家一起喊：“中国队万岁！”", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地叫：“放假了，万岁！”", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到明天不上课，同学们都喊万岁。", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日晚会上，大家举着杯子喊：“万岁！”", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球进了！球迷们站起来高喊“万岁”。", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说今天不考试，大家马上喊起“万岁”。", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿到奖金，高兴得大喊万岁。", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，我们跑到外面喊：“太阳万岁！”", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天放假，他举起手喊了一声万岁。", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起举杯，笑着喊：“友谊万岁！”", "target_word": "万岁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "高兴时欢呼喊出的祝愿口号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2667f8-e9d0-427d-8665-36e8f6ad299f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万岁", "is_correct": true, "explanation": "正确：“万岁”是高兴时的欢呼，用在“中国队万岁”这样的祝愿中。"}, {"text": "唉", "is_correct": false, "explanation": "语义：“唉”表示叹气或失望，不能用来为“中国队”欢呼。"}, {"text": "哎呀", "is_correct": false, "explanation": "语义：“哎呀”表示惊讶或疼痛，与比赛赢了之后的高兴不符。"}, {"text": "嘿", "is_correct": false, "explanation": "搭配：“嘿”是招呼或引起注意的口语，不用来为“中国队”高声祝愿。"}], "explanations": {"万岁": "正确：“万岁”是高兴时的欢呼，用在“中国队万岁”这样的祝愿中。", "唉": "语义：“唉”表示叹气或失望，不能用来为“中国队”欢呼。", "哎呀": "语义：“哎呀”表示惊讶或疼痛，与比赛赢了之后的高兴不符。", "嘿": "搭配：“嘿”是招呼或引起注意的口语，不用来为“中国队”高声祝愿。"}, "sentence_index": 0, "correct_answer": "万岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "分别时，大家流着泪喊：“万岁！”", "explanation": "这里应该用〈再见〉。分别时要说“再见”，“万岁”是高兴时的欢呼，不能在流泪告别时喊。"}, {"text": "比赛开始了，大家喊：“万岁！”", "explanation": "这里应该用〈加油〉。赛前鼓劲要说“加油”，“万岁”是庆祝或高兴时的欢呼。"}, {"text": "他因病去世，大家哭着喊：“万岁！”", "explanation": "这里应该用〈哀悼〉。“万岁”是高兴时的欢呼，哀悼去世的人时不能喊万岁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万岁", "is_correct": true, "explanation": "正确：“万岁”是高兴时的欢呼，与“高兴得大喊”搭配。"}, {"text": "呸", "is_correct": false, "explanation": "语义：“呸”表示唾弃或厌恶，与高兴的情绪相反。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛或吃惊，不是高兴时的欢呼。"}, {"text": "嗯", "is_correct": false, "explanation": "语域：“嗯”是应答声，口语随意，不用于大声高喊。"}], "explanations": {"万岁": "正确：“万岁”是高兴时的欢呼，与“高兴得大喊”搭配。", "呸": "语义：“呸”表示唾弃或厌恶，与高兴的情绪相反。", "哎哟": "语义：“哎哟”表示疼痛或吃惊，不是高兴时的欢呼。", "嗯": "语域：“嗯”是应答声，口语随意，不用于大声高喊。"}, "sentence_index": 6, "correct_answer": "万岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他送我礼物，我连忙低声说：“万岁。”", "explanation": "这里应该用〈谢谢〉。接受礼物要说“谢谢”，“万岁”是高声欢呼，不能低声说来道谢。"}, {"text": "他不小心踩了我的脚，我说：“万岁！”", "explanation": "这里应该用〈对不起〉。踩到别人要道歉说“对不起”，“万岁”不用于道歉。"}, {"text": "晚饭时，爸爸举起酒杯，叹了口气说：“万岁。”", "explanation": "这里应该用〈干杯〉。举杯祝酒要说“干杯”，“万岁”是高声欢呼，不能用叹气时的语气说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到明天不上课，同学们都喊了一个万岁。", "corrected_sentence": "听到明天不上课，同学们都喊了一声万岁。", "error_description": "量词错误：“万岁”作一次喊声时用量词“声”，应说“喊了一声万岁”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友们，我们的团队万岁了！", "corrected_sentence": "朋友们，我们的团队万岁！", "error_description": "语法错误：“万岁”是祝愿用语，不能带表示完成的“了”，应说“朋友们，我们的团队万岁！”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
