INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "路人是在路上走的、不认识的人。", "primary_collocate": null, "pronunciation": "lù rén", "ipa": "lu˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "一个路人把钱包还给了我。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请路人帮我拍照。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位路人不认识我，却对我笑了笑。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有很多路人，没有一个我认识。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个路人递给她一把伞。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问路人：“火车站怎么走？”", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让路人看到我哭。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路人听见孩子在叫，赶紧过来了。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是路人，以前从没见过。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个路人在雨中站着等车。", "target_word": "路人", "complexity_tier": "T3", "furigana": "yí gè lù rén zài yǔ zhōng zhàn zhe děng chē", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "路人甲", "label": "复合"}], "register": "中性", "sense_fingerprint": "在路上走的、素不相识的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“路人”指路上偶然遇到的、不认识的人，能拾到钱包并归还，符合语境。"}, {"text": "失主", "is_correct": false, "explanation": "语义：“失主”是丢东西的人，不会把钱包还给别人。"}, {"text": "电线杆", "is_correct": false, "explanation": "语义：“电线杆”是物体，不能把钱包还给人。"}, {"text": "钱包", "is_correct": false, "explanation": "搭配：“还给”的主语须是有意识的人，“钱包”不能作主语。"}], "explanations": {"路人": "正确：“路人”指路上偶然遇到的、不认识的人，能拾到钱包并归还，符合语境。", "失主": "语义：“失主”是丢东西的人，不会把钱包还给别人。", "电线杆": "语义：“电线杆”是物体，不能把钱包还给人。", "钱包": "搭配：“还给”的主语须是有意识的人，“钱包”不能作主语。"}, "sentence_index": 0, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "聚会上来的都是我的路人。", "explanation": "这里应该用〈熟人〉。路人指素不相识的人，与“我的”相矛盾，要用〈熟人〉。"}, {"text": "会场里坐满了路人。", "explanation": "这里应该用〈听众〉。路人不是来听讲座的，坐在会场里听讲的要用〈听众〉。"}, {"text": "车上坐满了路人。", "explanation": "这里应该用〈乘客〉。路人指路上走的人，坐在车上的人要用〈乘客〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“路人”指路上不认识的人，可以在这里看到我哭，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不会看东西，不能“看到我哭”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能看见东西，与“看到我哭”不搭。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不会看东西，不能“看到我哭”。"}], "explanations": {"路人": "正确：“路人”指路上不认识的人，可以在这里看到我哭，符合语境。", "桌子": "语义：“桌子”不会看东西，不能“看到我哭”。", "窗户": "语义：“窗户”不能看见东西，与“看到我哭”不搭。", "雨伞": "语义：“雨伞”不会看东西，不能“看到我哭”。"}, "sentence_index": 6, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路人住在我家隔壁。", "explanation": "这里应该用〈邻居〉。路人指在路上走过、与自己无关的人，不会长期住在隔壁，住隔壁的要用〈邻居〉。"}, {"text": "路人正在开车。", "explanation": "这里应该用〈司机〉。路人只是路上走的人，驾驶车辆的人要用〈司机〉。"}, {"text": "路人正在带队训练。", "explanation": "这里应该用〈教练〉。路人不负责带队训练，指导队伍训练的人要用〈教练〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只路人叫住了我，问我去车站怎么走。", "corrected_sentence": "一个路人叫住了我，问我去车站怎么走。", "error_description": "错误：“一只路人”；正确：“一个路人”。“只”用于动物或成对的东西，路人指人，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路人的都主动帮我推开了车门。", "corrected_sentence": "路人都主动帮我推开了车门。", "error_description": "错误：“路人的都”；正确：“路人都”。“路人”作主语后不应加“的”，“都”直接接在主语之后表示总括。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
