INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在路上走的人，与自己无关的人。", "primary_collocate": null, "pronunciation": "lù rén", "ipa": "lu˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "路人都停下来看那只小狗。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了一个路人，他告诉我怎么走。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事和我无关，我只是个路人。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有路人看见他摔倒了，马上跑过来。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分手后，就像路人一样。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的路人都带着伞。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位路人帮我拍了张照片。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了路人一眼，就走了。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我来说只是一个路人。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路人看着他们吵架，没有人说话。", "target_word": "路人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "路人甲", "label": "复合"}], "register": "中性", "sense_fingerprint": "在路上走的人；与自己没有关系的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“路人”指路上走的人，与“都停下来看小狗”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是地方，不会停下来看小狗。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能停下来看东西。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“停下来”的主语须是人，“河流”不能作此主语。"}], "explanations": {"路人": "正确：“路人”指路上走的人，与“都停下来看小狗”的语境相符。", "厨房": "语义：“厨房”是地方，不会停下来看小狗。", "椅子": "语义：“椅子”是家具，不能停下来看东西。", "河流": "搭配：“停下来”的主语须是人，“河流”不能作此主语。"}, "sentence_index": 0, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公交车上坐满了路人。", "explanation": "这里应该用〈乘客〉。路人指路上走的人，坐在车上的人要用〈乘客〉。"}, {"text": "舞台前面坐满了路人。", "explanation": "这里应该用〈观众〉。路人不是来看演出的，台下的看客要用〈观众〉。"}, {"text": "医院的病房里住满了路人。", "explanation": "这里应该用〈病人〉。路人不住院，住在病房里的人要用〈病人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "路人", "is_correct": true, "explanation": "正确：“一位路人”指路上不认识的人，可以顺手帮忙拍照，符合语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”还不会拍照，与“帮我拍照”的语境不符。"}, {"text": "幽灵", "is_correct": false, "explanation": "语义：“幽灵”不能拍照，此处应指路上的人。"}, {"text": "雨伞", "is_correct": false, "explanation": "量词：“一位”只用于人，“雨伞”不能用“位”计量，也不会拍照。"}], "explanations": {"路人": "正确：“一位路人”指路上不认识的人，可以顺手帮忙拍照，符合语境。", "婴儿": "语义：“婴儿”还不会拍照，与“帮我拍照”的语境不符。", "幽灵": "语义：“幽灵”不能拍照，此处应指路上的人。", "雨伞": "量词：“一位”只用于人，“雨伞”不能用“位”计量，也不会拍照。"}, "sentence_index": 6, "correct_answer": "路人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的路人昨天来看我了。", "explanation": "这里应该用〈朋友〉。路人指不认识、只是路过的人，与“来看我”的熟人关系不符，要用〈朋友〉。"}, {"text": "路口的路人正在卖水果。", "explanation": "这里应该用〈小贩〉。路人指在路上走、与自己无关的人，不会在路口摆摊卖东西，那要用〈小贩〉。"}, {"text": "厨房里的路人正在做饭。", "explanation": "这里应该用〈厨师〉。路人不在厨房工作，做饭的人要用〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只路人帮我捡起了掉在地上的书。", "corrected_sentence": "一个路人帮我捡起了掉在地上的书。", "error_description": "错误：“一只路人”；正确：“一个路人”。“只”用于动物或成对的东西，路人是人，应用“个”或“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路人的都停下来看我。", "corrected_sentence": "路人都停下来看我。", "error_description": "错误：“路人的都”；正确：“路人都”。“路人”作主语后不应加“的”，“都”直接接在主语之后表示总括。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "反义：“集合”指聚到一起，“分散”指散开，二者意思相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞与“集合”之间没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "读书与“集合”之间没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与“集合”之间没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "反义：“集合”指聚到一起，“分散”指散开，二者意思相反。", "跳舞": "跳舞与“集合”之间没有反义关系。", "读书": "读书与“集合”之间没有反义关系。", "跑步": "跑步与“集合”之间没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "反义：“集合”指聚到一起，“分散”指散开，二者意思相反。"}, {"text": "写字", "is_correct": false, "explanation": "写字与“集合”之间没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与“集合”之间没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "画画与“集合”之间没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "反义：“集合”指聚到一起，“分散”指散开，二者意思相反。", "写字": "写字与“集合”之间没有反义关系。", "游泳": "游泳与“集合”之间没有反义关系。", "画画": "画画与“集合”之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "集合是大家来到同一个地方，站在一起。", "primary_collocate": null, "pronunciation": "jí hé", "ipa": "tɕi˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "上课前，同学们在走廊集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全班同学在操场集合站好。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到老师的话，大家排队集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军人们每天早上六点集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家在门口集合，我们要拍照。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛开始前，两队选手先集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游说，十点在酒店门口集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们已经集合好了。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们几点在哪儿集合？", "target_word": "集合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在门口集合，等着老师来。", "target_word": "集合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集合了", "label": "体标"}, {"form": "集合过", "label": "体标"}, {"form": "集合点", "label": "复合"}], "register": "中性", "sense_fingerprint": "集合|动词|大家到同一地方站在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "集合：指人到同一地点，与“上课前”和“走廊”的语境相符。"}, {"text": "下课", "is_correct": false, "explanation": "语义：下课在上课之后，“上课前”不能下课。"}, {"text": "制造", "is_correct": false, "explanation": "配价：“制造”是及物动词，后面要带宾语，这里没有宾语。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是敬辞，只用于来宾，不能用于同学们。"}], "explanations": {"集合": "集合：指人到同一地点，与“上课前”和“走廊”的语境相符。", "下课": "语义：下课在上课之后，“上课前”不能下课。", "制造": "配价：“制造”是及物动词，后面要带宾语，这里没有宾语。", "莅临": "语域：“莅临”是敬辞，只用于来宾，不能用于同学们。"}, "sentence_index": 0, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他集合了很好的成绩。", "explanation": "这里应该用〈取得〉。集合指人或物聚到同一处，成绩不能聚拢，应说「取得很好的成绩」。"}, {"text": "这两家公司去年集合了。", "explanation": "这里应该用〈合并〉。合并指把几个单位合成一个；集合指人或物聚到同一处，不能说公司集合。"}, {"text": "他把全部精力集合在作业上。", "explanation": "这里应该用〈集中〉。集中指把精力、注意力聚到一点；集合指人或物聚到同一处，不能用于精力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "集合：指人到同一地点，与“导游说”“十点”“酒店门口”的安排相符。"}, {"text": "熄灯", "is_correct": false, "explanation": "语义：熄灯是关灯，不能在酒店门口熄灯。"}, {"text": "降落", "is_correct": false, "explanation": "搭配：“降落”用于飞机、伞等，不用于人在门口。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚指两人成为夫妻，与导游安排的集合时间和地点不合。"}], "explanations": {"集合": "集合：指人到同一地点，与“导游说”“十点”“酒店门口”的安排相符。", "熄灯": "语义：熄灯是关灯，不能在酒店门口熄灯。", "降落": "搭配：“降落”用于飞机、伞等，不用于人在门口。", "结婚": "语义：结婚指两人成为夫妻，与导游安排的集合时间和地点不合。"}, "sentence_index": 6, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脚步集合得很快。", "explanation": "这里应该用〈迈〉。集合指人或物聚到同一处，脚步不能聚拢，应说「脚步迈得很快」。"}, {"text": "他喜欢集合贝壳。", "explanation": "这里应该用〈收集〉。收集指把东西搜罗在一起；集合指人或物按要求聚到同一处，不说“集合贝壳”。"}, {"text": "大家集合钱给老师买花。", "explanation": "这里应该用〈凑〉。凑指把钱拼在一起；集合指人或物聚到同一地点，不能说“集合钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上七点，工人们都到厂门口集合了好。", "corrected_sentence": "早上七点，工人们都到厂门口集合好了。", "error_description": "“了”的位置错误。结果补语“好”应紧跟动词，说“集合好了”，不能说“集合了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "导游让大家车站集合。", "corrected_sentence": "导游让大家在车站集合。", "error_description": "缺少介词“在”。表示地点时要说“在车站集合”，不能直接说“车站集合”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
