INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分散的人或物聚集到一起。", "primary_collocate": null, "pronunciation": "jí hé", "ipa": "tɕi˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "同学们八点在校门口集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家快到操场上集合。", "target_word": "集合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让学生们在教室前集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们明天早上七点半集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客在车站集合了。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请所有队员到这里集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到哨声，孩子们马上集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在公园门口集合过一次。", "target_word": "集合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打电话让大家来集合吧。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发前我们先在学校集合。", "target_word": "集合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "集合了", "label": "体标"}, {"form": "集合过", "label": "体标"}, {"form": "集合点", "label": "复合"}], "register": "中性", "sense_fingerprint": "集合|动词|分散的人或物聚到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd87a71-ffc2-4442-8be5-c6809fccefb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "集合：指人到同一地点站在一起，与“同学们”“八点”“校门口”的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指降生，与“同学们在校门口”的场景矛盾。"}, {"text": "起床", "is_correct": false, "explanation": "语义：“起床”指离开床铺，不能说在校门口起床。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是敬辞，多用于来宾，不能用来指同学们。"}], "explanations": {"集合": "集合：指人到同一地点站在一起，与“同学们”“八点”“校门口”的语境相符。", "出生": "语义：“出生”指降生，与“同学们在校门口”的场景矛盾。", "起床": "语义：“起床”指离开床铺，不能说在校门口起床。", "莅临": "语域：“莅临”是敬辞，多用于来宾，不能用来指同学们。"}, "sentence_index": 0, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他脸上集合了一丝笑意。", "explanation": "这里应该用〈浮现〉。集合指人或物聚到同一处，笑意不能聚拢，应说「脸上浮现一丝笑意」。"}, {"text": "我们下午集合一次会议。", "explanation": "这里应该用〈召开〉。召开指组织召集会议；集合指人聚到同一处，不能说“集合会议”。"}, {"text": "这两所学校去年集合了。", "explanation": "这里应该用〈合并〉。合并指把几个单位合成一个；集合指人或物聚到同一处，不能说学校集合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集合", "is_correct": true, "explanation": "集合：听到哨声后按要求到一起，与“马上”相符。"}, {"text": "召唤", "is_correct": false, "explanation": "配价：“召唤”是及物动词，需要带宾语，这里没有宾语，句子不完整。"}, {"text": "沉睡", "is_correct": false, "explanation": "语义：听到哨声后马上沉睡，与常理矛盾。"}, {"text": "散场", "is_correct": false, "explanation": "搭配：“散场”只用于演出、比赛等结束，不能用于孩子们听到哨声之后。"}], "explanations": {"集合": "集合：听到哨声后按要求到一起，与“马上”相符。", "召唤": "配价：“召唤”是及物动词，需要带宾语，这里没有宾语，句子不完整。", "沉睡": "语义：听到哨声后马上沉睡，与常理矛盾。", "散场": "搭配：“散场”只用于演出、比赛等结束，不能用于孩子们听到哨声之后。"}, "sentence_index": 6, "correct_answer": "集合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的表情集合得很自然。", "explanation": "这里应该用〈显得〉。集合指人或物聚到同一处，表情不能聚拢，应说「显得很自然」。"}, {"text": "他的心跳集合得很快。", "explanation": "这里应该用〈跳〉。集合指人或物聚到同一处，心跳不能聚拢，应说「心跳得很快」。"}, {"text": "他的脾气集合得很大。", "explanation": "这里应该用〈大〉。集合指人或物聚到同一处，脾气不能聚拢，应说「脾气很大」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动会开始前，运动员都到操场上很集合。", "corrected_sentence": "运动会开始前，运动员都到操场上集合。", "error_description": "多出了程度副词“很”。“很”不能修饰动词“集合”，应删去，说“到操场上集合”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到口令，士兵们马上集合过。", "corrected_sentence": "听到口令，士兵们马上集合。", "error_description": "错误：「马上集合过」。正确：「马上集合」。「马上」表示即刻发生，与表示经历的「过」意思矛盾，应去掉「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07dbaf3e-3b92-4286-a59b-24ec25719b6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
