INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94587, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "养殖是养鱼、养虫、养小动物，让它们长大。", "primary_collocate": null, "pronunciation": "yǎng zhí", "ipa": "jaŋ²¹⁴ ʈʂɻ̩³⁵", "syllable_count": 2, "sentences": [{"text": "他们在湖边养殖小龙虾，准备卖给饭店。", "target_word": "养殖", "complexity_tier": "T3", "furigana": "yǎngzhí", "sentence_source": "generated"}, {"text": "我哥哥养殖了一些蚕。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田里养殖泥鳅，拿到集市上卖。", "target_word": "养殖", "complexity_tier": "T3", "furigana": "yǎngzhí", "sentence_source": "generated"}, {"text": "池塘里养殖着很多鱼。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养殖蚯蚓不太难。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农户在大棚里养殖肉兔，供应市场。", "target_word": "养殖", "complexity_tier": "T3", "furigana": "yǎngzhí", "sentence_source": "generated"}, {"text": "他在水缸里养殖金鱼。", "target_word": "养殖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场养殖黄粉虫，用作鸡的饲料。", "target_word": "养殖", "complexity_tier": "T3", "furigana": "yǎngzhí", "sentence_source": "generated"}, {"text": "这批蜗牛是他在果园里养殖的。", "target_word": "养殖", "complexity_tier": "T3", "furigana": "yǎngzhí", "sentence_source": "generated"}, {"text": "他想在院子里养殖一批土鸡卖掉。", "target_word": "养殖", "complexity_tier": "T3", "furigana": "yǎngzhí", "sentence_source": "generated"}], "morphological_forms": [{"form": "养殖业", "label": "复合"}, {"form": "养殖场", "label": "复合"}, {"form": "养殖着", "label": "体标"}], "register": "中性", "sense_fingerprint": "养鱼、养虫等小动物，让它们长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2667f8-e9d0-427d-8665-36e8f6ad299f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "养殖", "is_correct": true, "explanation": "正确。养殖指养小动物让它们长大，这里是养小龙虾。"}, {"text": "背诵", "is_correct": false, "explanation": "语义：背诵的对象是文字，不能用于小龙虾。"}, {"text": "编写", "is_correct": false, "explanation": "搭配：编写的对象是文字或程序，不能说编写小龙虾。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：演唱的对象是歌曲，不能说演唱小龙虾。"}], "explanations": {"养殖": "正确。养殖指养小动物让它们长大，这里是养小龙虾。", "背诵": "语义：背诵的对象是文字，不能用于小龙虾。", "编写": "搭配：编写的对象是文字或程序，不能说编写小龙虾。", "演唱": "搭配：演唱的对象是歌曲，不能说演唱小龙虾。"}, "sentence_index": 0, "correct_answer": "养殖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在田里养殖了大豆。", "explanation": "这里应该用〈种植〉。养殖针对动物，大豆是植物，要用种植。"}, {"text": "我家养殖了一条狗。", "explanation": "这里应该用〈饲养〉。养殖多指成批饲养以供生产，养一条宠物要用饲养。"}, {"text": "他们养殖了许多好习惯。", "explanation": "这里应该用〈培养〉。养殖只用于动植物，习惯要用培养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "养殖", "is_correct": true, "explanation": "正确。养殖指养小动物，金鱼是小动物，可以养殖。"}, {"text": "讲述", "is_correct": false, "explanation": "语义：讲述的对象是故事或经历，不能用于金鱼。"}, {"text": "缝", "is_correct": false, "explanation": "语义：缝需要布料或线，不能用于金鱼。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理的对象是机器或器具，不能说修理金鱼。"}], "explanations": {"养殖": "正确。养殖指养小动物，金鱼是小动物，可以养殖。", "讲述": "语义：讲述的对象是故事或经历，不能用于金鱼。", "缝": "语义：缝需要布料或线，不能用于金鱼。", "修理": "搭配：修理的对象是机器或器具，不能说修理金鱼。"}, "sentence_index": 6, "correct_answer": "养殖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养殖了一家小超市，生意很好。", "explanation": "这里应该用〈经营〉。养殖的对象是动物，超市要用经营。"}, {"text": "他想在院子里养殖一百张邮票。", "explanation": "这里应该用〈收藏〉。养殖的对象是动植物，邮票要用收藏。"}, {"text": "他们养殖了一种新药，效果很好。", "explanation": "这里应该用〈研制〉。养殖只用于动植物，药品要用研制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前养殖了过金鱼。", "corrected_sentence": "他以前养殖过金鱼。", "error_description": "错误：动词后面不能同时用“了”和“过”。“过”表示经历，应说“养殖过金鱼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想在院子里养殖了一些蚕。", "corrected_sentence": "他想在院子里养殖一些蚕。", "error_description": "错误：“想”表示打算，动作还没有发生，“养殖”后面不能加“了”，应说“想在院子里养殖一些蚕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
