INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "农历生肖为马的年份。", "primary_collocate": null, "pronunciation": "mǎ nián", "ipa": "ma˨˩˦ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "农历马年就要到了。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年春节，商店里全是马的玩具。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年的春节，街上很热闹。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年快到了，街上都是红灯笼。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们全家在马年春节回老家过年。", "target_word": "马年", "complexity_tier": "T3", "furigana": "wǒ men quán jiā zài mǎ nián chūn jié huí lǎo jiā guò nián", "sentence_source": "generated"}, {"text": "每到马年，就有很多人买马的画。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马年过去以后，就是羊年。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一个马年，我才十二岁。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在上一个马年出生。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年是蛇年，今年是马年。", "target_word": "马年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "馬年", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农历中生肖是马的年份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "马年", "is_correct": true, "explanation": "“马年”指农历生肖为马的年份，与“农历”相符，也能与“就要到了”搭配。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”不是时间，不能说“就要到了”。"}, {"text": "公历年", "is_correct": false, "explanation": "搭配：“公历”与前面的“农历”互相矛盾，不能同时修饰这里的年份。"}, {"text": "去年", "is_correct": false, "explanation": "语义：去年已经过去，与“就要到了”的意思矛盾。"}], "explanations": {"马年": "“马年”指农历生肖为马的年份，与“农历”相符，也能与“就要到了”搭配。", "蛋糕": "语义：“蛋糕”不是时间，不能说“就要到了”。", "公历年": "搭配：“公历”与前面的“农历”互相矛盾，不能同时修饰这里的年份。", "去年": "语义：去年已经过去，与“就要到了”的意思矛盾。"}, "sentence_index": 0, "correct_answer": "马年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座马年是最热闹的一年。", "explanation": "这里应该用〈个〉。“座”多用于山、房屋等，“马年”是年份，量词要用“个”。"}, {"text": "我的属相是马年。", "explanation": "这里应该用〈马〉。“属相”后接动物名“马”，“马年”指年份，不能作属相。"}, {"text": "他的爸爸是马年，爱喝茶。", "explanation": "这里应该用〈属马〉。说人的生肖要用“属马”，“马年”指年份，不能说“他是马年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "马年", "is_correct": true, "explanation": "“马年”是年份，放在“过去以后，就是羊年”的前面，与句意相符。"}, {"text": "猴年", "is_correct": false, "explanation": "语义：猴年之后是鸡年，不是羊年，与“就是羊年”矛盾。"}, {"text": "生肖", "is_correct": false, "explanation": "搭配：“过去以后”后接的是时间，“生肖”不是时间，不能这样搭配。"}, {"text": "狗年", "is_correct": false, "explanation": "语义：狗年之后是猪年，不是羊年，与“就是羊年”矛盾。"}], "explanations": {"马年": "“马年”是年份，放在“过去以后，就是羊年”的前面，与句意相符。", "猴年": "语义：猴年之后是鸡年，不是羊年，与“就是羊年”矛盾。", "生肖": "搭配：“过去以后”后接的是时间，“生肖”不是时间，不能这样搭配。", "狗年": "语义：狗年之后是猪年，不是羊年，与“就是羊年”矛盾。"}, "sentence_index": 6, "correct_answer": "马年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去草原上看马年。", "explanation": "这里应该用〈骏马〉。草原上看的是动物“马”，“马年”指年份，不能用来指动物。"}, {"text": "马年是中国最重要的节日。", "explanation": "这里应该用〈春节〉。“马年”指年份，不能当作节日名称。"}, {"text": "马年是一年的第一天。", "explanation": "这里应该用〈元旦〉。“马年”指一整年，不能指一年中的某一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下一只马年，我们全家要去看海。", "corrected_sentence": "下一个马年，我们全家要去看海。", "error_description": "量词错误：“马年”是年份，量词应用“个”，不能用“只”。错误形式「下一只马年」，正确形式「下一个马年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年是一只马年，后年是羊年。", "corrected_sentence": "明年是一个马年，后年是羊年。", "error_description": "量词错误：“马年”是年份，量词应用“个”，不能用“只”。错误形式「一只马年」，正确形式「一个马年」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94591, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94591, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94591, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面包是软软的、用面粉烤出来的吃的东西。", "primary_collocate": null, "pronunciation": "miàn bāo", "ipa": "mjɛn˥˩ paʊ˥", "syllable_count": 2, "sentences": [{"text": "妈妈做的面包又软又香。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的早饭是面包和鸡蛋。", "target_word": "面包", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟饿了，我给他一块面包。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包里有葡萄干，很好吃。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的面包每天下午都卖完。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用刀把面包切成了三片。", "target_word": "面包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃面包的时候，我喜欢喝热牛奶。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想吃米饭还是面包？", "target_word": "面包", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园里的小鸟在吃我手里的面包。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包放在桌子上，你饿了就自己拿。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "麵包", "label": "繁体"}, {"form": "面包店", "label": "复合"}], "register": "口语", "sense_fingerprint": "面包：软软的、用面粉烤成的日常食物，常当早饭吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94591, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面包", "is_correct": true, "explanation": "面包 miàn bāo：用面粉烤成的软软的日常食物，正确答案。"}, {"text": "棉包", "is_correct": false, "explanation": "mián bāo（第二声）与 miàn bāo 只有第一个音节声调不同，意思是棉花的包裹。"}, {"text": "棉袍", "is_correct": false, "explanation": "mián páo 与 miàn bāo 第一个音节声调不同，第二个音节的声母也不同（b 与 p），意思是棉布做的长袍。"}, {"text": "面刨", "is_correct": false, "explanation": "miàn bào 与 miàn bāo 只有第二个音节声调不同（第四声），意思是木工用的刨子。"}], "explanations": {"面包": "面包 miàn bāo：用面粉烤成的软软的日常食物，正确答案。", "棉包": "mián bāo（第二声）与 miàn bāo 只有第一个音节声调不同，意思是棉花的包裹。", "棉袍": "mián páo 与 miàn bāo 第一个音节声调不同，第二个音节的声母也不同（b 与 p），意思是棉布做的长袍。", "面刨": "miàn bào 与 miàn bāo 只有第二个音节声调不同（第四声），意思是木工用的刨子。"}, "sentence_index": null, "correct_answer": "面包"}, "level_3": {"options": [{"text": "面包", "is_correct": true, "explanation": "面包是食物，可以又软又香，“妈妈做的”也符合面包的语境。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能吃，也不会“又软又香”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是硬的，不会软，也不会香。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：空调是买的，不说“妈妈做的空调”，“做”与“空调”不搭。"}], "explanations": {"面包": "面包是食物，可以又软又香，“妈妈做的”也符合面包的语境。", "玻璃": "语义：玻璃不能吃，也不会“又软又香”。", "石头": "语义：石头是硬的，不会软，也不会香。", "空调": "搭配：空调是买的，不说“妈妈做的空调”，“做”与“空调”不搭。"}, "sentence_index": 0, "correct_answer": "面包"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一头面包。", "explanation": "这里应该用〈块〉或〈个〉。〈头〉多用于大型牲畜，面包不能用。"}, {"text": "做饺子时，妈妈先把面包和水混在一起。", "explanation": "这里应该用〈面粉〉。和面要用面粉加水揉，面包是成品，不能用来和面。"}, {"text": "妈妈用擀面杖把面团擀成了面包。", "explanation": "这里应该用〈面皮〉。擀出来的是面皮，面包是烤出来的成品，不能擀成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94591, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面包", "is_correct": true, "explanation": "面包是食物，可以“吃”，句子说的是吃东西时喝热牛奶。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：咖啡一般说“喝”，不说“吃咖啡”。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不能吃，句子说的是吃东西。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能吃，与“喝热牛奶”的饮食语境矛盾。"}], "explanations": {"面包": "面包是食物，可以“吃”，句子说的是吃东西时喝热牛奶。", "咖啡": "搭配：咖啡一般说“喝”，不说“吃咖啡”。", "沙子": "语义：沙子不能吃，句子说的是吃东西。", "汽油": "语义：汽油不能吃，与“喝热牛奶”的饮食语境矛盾。"}, "sentence_index": 6, "correct_answer": "面包"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面包要煮二十分钟才能吃。", "explanation": "这里应该用〈米饭〉。米饭要煮，面包要烤，面包不用煮。"}, {"text": "我买了一把面包。", "explanation": "这里应该用〈块〉或〈个〉。〈把〉用于有柄的东西，面包不能用。"}, {"text": "我每天吃一杯面包。", "explanation": "这里应该用〈块〉或〈片〉。〈杯〉多用于液体或装在杯子里的东西，面包是固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟每天早上吃一只面包。", "corrected_sentence": "弟弟每天早上吃一块面包。", "error_description": "量词错误：“只”用于动物，面包应该用“块”或“片”。正确的说法是“一块面包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸把面包切到了两片。", "corrected_sentence": "爸爸把面包切成了两片。", "error_description": "补语错误：“切”后表示结果的补语应用“成”，“切到”是碰到的意思，不能说“切到两片”。正确的说法是“把面包切成了两片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
