INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用面粉发酵后烘烤制成的食品。", "primary_collocate": null, "pronunciation": "miàn bāo", "ipa": "mjɛn˥˩ paʊ˥", "syllable_count": 2, "sentences": [{"text": "早上我吃了一片面包，喝了一杯牛奶。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅每天早上四点就开始烤面包。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的面包刚出炉，又香又软。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在超市买了两个面包和一瓶水。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把面粉和酵母放在一起，做成面包。", "target_word": "面包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我两片面包，我想做三明治。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个面包放了三天，已经很硬了。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友喜欢在面包上放一点果酱。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包是用面粉做的，不是用大米做的。", "target_word": "面包", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天坐地铁上班，在路上吃着面包。", "target_word": "面包", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "麵包", "label": "繁体"}, {"form": "面包店", "label": "复合"}], "register": "中性", "sense_fingerprint": "面包：用面粉发酵后烘烤成的食品，可以切片，常和牛奶、果酱、三明治一起出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94592, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面包", "is_correct": true, "explanation": "面包 miàn bāo：用面粉发酵后烘烤的食品，正确答案。"}, {"text": "棉包", "is_correct": false, "explanation": "mián bāo（第二声）与 miàn bāo 只有第一个音节声调不同，意思是棉花的包裹。"}, {"text": "棉袍", "is_correct": false, "explanation": "mián páo 与 miàn bāo 第一个音节声调不同，第二个音节的声母也不同（b 与 p），意思是棉布做的长袍。"}, {"text": "面刨", "is_correct": false, "explanation": "miàn bào 与 miàn bāo 只有第二个音节声调不同（第四声），意思是木工用的刨子。"}], "explanations": {"面包": "面包 miàn bāo：用面粉发酵后烘烤的食品，正确答案。", "棉包": "mián bāo（第二声）与 miàn bāo 只有第一个音节声调不同，意思是棉花的包裹。", "棉袍": "mián páo 与 miàn bāo 第一个音节声调不同，第二个音节的声母也不同（b 与 p），意思是棉布做的长袍。", "面刨": "miàn bào 与 miàn bāo 只有第二个音节声调不同（第四声），意思是木工用的刨子。"}, "sentence_index": null, "correct_answer": "面包"}, "level_3": {"options": [{"text": "面包", "is_correct": true, "explanation": "面包是食物，可以用“片”计量，“吃了一片面包”符合句意。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能吃，句子说的是吃东西。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“片”用于薄片状的东西，米饭要说“一碗”或“一份”，不说“一片米饭”。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能吃，与“吃了”和“喝了牛奶”的饮食语境相矛盾。"}], "explanations": {"面包": "面包是食物，可以用“片”计量，“吃了一片面包”符合句意。", "汽油": "语义：汽油不能吃，句子说的是吃东西。", "米饭": "搭配：“片”用于薄片状的东西，米饭要说“一碗”或“一份”，不说“一片米饭”。", "玻璃": "语义：玻璃不能吃，与“吃了”和“喝了牛奶”的饮食语境相矛盾。"}, "sentence_index": 0, "correct_answer": "面包"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一瓶面包。", "explanation": "这里应该用〈块〉或〈个〉。〈瓶〉用于装在瓶子里的液体或东西，面包是固体，不能用“瓶”。"}, {"text": "做蛋糕要先准备面包和鸡蛋。", "explanation": "这里应该用〈面粉〉。面包是做好的食品，不能当原料；做蛋糕要先准备面粉。"}, {"text": "我吃了一杯面包。", "explanation": "这里应该用〈块〉或〈片〉。〈杯〉多用于液体或装在杯子里的东西，面包是固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面包", "is_correct": true, "explanation": "面包放久会变干变硬，符合“放了三天，已经很硬了”。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不会变硬，“硬”只能用于固体。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶放久会变质变味，不会变硬。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”前的量词应用“股”，不说“这个空气”，而且空气也不会“放”硬。"}], "explanations": {"面包": "面包放久会变干变硬，符合“放了三天，已经很硬了”。", "水": "语义：水是液体，不会变硬，“硬”只能用于固体。", "牛奶": "语义：牛奶放久会变质变味，不会变硬。", "空气": "搭配：“空气”前的量词应用“股”，不说“这个空气”，而且空气也不会“放”硬。"}, "sentence_index": 6, "correct_answer": "面包"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天在院子里种面包。", "explanation": "这里应该用〈麦子〉。面包是烤出来的成品，不能种，种的是麦子。"}, {"text": "这种面包要煮十分钟才能吃。", "explanation": "这里应该用〈面条〉。面条要煮，面包要烤，面包不用煮。"}, {"text": "我买了一座面包。", "explanation": "这里应该用〈块〉或〈个〉。〈座〉用于山、楼房等大型固定的东西，面包不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只面包。", "corrected_sentence": "他买了一块面包。", "error_description": "量词错误：“只”用于动物，面包应该用“块”或“片”。正确的说法是“一块面包”，不说“一只面包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喝了三块面包。", "corrected_sentence": "他吃了三块面包。", "error_description": "搭配错误：“喝”用于液体，面包是固体，应说“吃了三块面包”，不说“喝了三块面包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
