INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给以，加以（多接双音节动词）。", "primary_collocate": null, "pronunciation": "yǔ yǐ", "ipa": "y˨˩˦ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司对这件事予以处理。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校对错误予以纠正。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理对我的请假予以批准。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不好的行为要予以批评。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结果明天予以公布。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师对这个问题予以解释。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们会对你的意见予以考虑。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府对违法行为予以处罚。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长对此事予以重视。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院对这个案子予以审理。", "target_word": "予以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "后接双音节动词，表示对某事加以处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b1368f-3c85-4d4d-9d9f-204f7c23b63d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以（yǔ yǐ）：加以，正确答案。"}, {"text": "语义", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是语义。"}, {"text": "雨衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，意思是雨衣。"}, {"text": "许以", "is_correct": false, "explanation": "xǔ 与 yǔ 声母不同，意思是许诺、答应。"}, {"text": "羽翼", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是羽毛和翅膀。"}], "explanations": {"予以": "予以（yǔ yǐ）：加以，正确答案。", "语义": "yì（第四声）与 yǐ（第三声）声调不同，意思是语义。", "雨衣": "yī（第一声）与 yǐ（第三声）声调不同，意思是雨衣。", "许以": "xǔ 与 yǔ 声母不同，意思是许诺、答应。", "羽翼": "yì（第四声）与 yǐ（第三声）声调不同，意思是羽毛和翅膀。"}, "sentence_index": null, "correct_answer": "予以"}, "level_3": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以：加以，对这件事进行处理，符合句意。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指感到快乐或得到好处，不能用来表示对事件的处理。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”的宾语应是物或能力，不能说拥有“处理”。"}, {"text": "忍受", "is_correct": false, "explanation": "语义：“忍受”指承受痛苦，与“处理”的行为义不符。"}], "explanations": {"予以": "予以：加以，对这件事进行处理，符合句意。", "享受": "语义：“享受”指感到快乐或得到好处，不能用来表示对事件的处理。", "拥有": "搭配：“拥有”的宾语应是物或能力，不能说拥有“处理”。", "忍受": "语义：“忍受”指承受痛苦，与“处理”的行为义不符。"}, "sentence_index": 0, "correct_answer": "予以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们予以看这份报告。", "explanation": "这里应该用〈审阅〉。予以后面要接双音节动词，单音节的“看”不能跟在“予以”后面，应说“予以审阅”。"}, {"text": "老师予以听学生的意见。", "explanation": "这里应该用〈听取〉。予以后面要接双音节动词，单音节的“听”不能用于“予以”之后，应说“予以听取”。"}, {"text": "妈妈予以买了一件衣服。", "explanation": "这里应该用〈购买〉。予以后面要接双音节动词，单音节的“买”不能跟在“予以”后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以（yǔ yǐ）：加以，正确答案。"}, {"text": "许以", "is_correct": false, "explanation": "xǔ 与 yǔ 声母不同，意思是许诺、答应。"}, {"text": "雨意", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的意思。"}, {"text": "羽衣", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，意思是羽毛做的衣服。"}], "explanations": {"予以": "予以（yǔ yǐ）：加以，正确答案。", "许以": "xǔ 与 yǔ 声母不同，意思是许诺、答应。", "雨意": "yì（第四声）与 yǐ（第三声）声调不同，意思是下雨的意思。", "羽衣": "yī（第一声）与 yǐ（第三声）声调不同，意思是羽毛做的衣服。"}, "sentence_index": null, "correct_answer": "予以"}, "level_3": {"options": [{"text": "予以", "is_correct": true, "explanation": "予以：加以，对意见加以考虑，符合句意。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止考虑”与“会考虑”的积极态度相矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃考虑”与“会考虑”的意思相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝考虑”与“会考虑”的意思相反。"}], "explanations": {"予以": "予以：加以，对意见加以考虑，符合句意。", "停止": "语义：“停止考虑”与“会考虑”的积极态度相矛盾。", "放弃": "语义：“放弃考虑”与“会考虑”的意思相反。", "拒绝": "语义：“拒绝考虑”与“会考虑”的意思相反。"}, "sentence_index": 6, "correct_answer": "予以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校对他予以一阵掌声。", "explanation": "这里应该用〈鼓掌〉。予以不用于掌声这类具体动作，应说“为他鼓掌”。"}, {"text": "妈妈予以孩子一个拥抱。", "explanation": "这里应该用〈给〉。予以后面接的是双音节动词或抽象的奖励、支持，“拥抱”这样的具体动作不能用予以。"}, {"text": "公司予以员工一个礼物。", "explanation": "这里应该用〈送〉。予以不用于礼物这类具体物品，应说送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司对这件事予以查。", "corrected_sentence": "公司对这件事予以查处。", "error_description": "“予以”后面的动词应是双音节词。单音节的“查”不能跟在“予以”后面，应说“予以查处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院对这个纠纷予以了调解。", "corrected_sentence": "法院对这个纠纷予以调解。", "error_description": "“予以”和后面的动词之间不加“了”。“予以了调解”错误，应去掉“了”，说“予以调解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32e81dd7-7185-466c-b964-1e4a575db21f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防御", "is_correct": true, "explanation": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。"}, {"text": "建设", "is_correct": false, "explanation": "建设：指创建、修建，与“侵略”不构成反义关系。"}, {"text": "访问", "is_correct": false, "explanation": "访问：指到某处去看望或了解情况，与“侵略”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指到外地游览，与“侵略”没有反义关系。"}], "correct_answer": "防御", "explanations": {"防御": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。", "建设": "建设：指创建、修建，与“侵略”不构成反义关系。", "访问": "访问：指到某处去看望或了解情况，与“侵略”没有反义关系。", "旅行": "旅行：指到外地游览，与“侵略”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防御", "is_correct": true, "explanation": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。"}, {"text": "生产", "is_correct": false, "explanation": "生产：指制造物品，与“侵略”不构成反义关系。"}, {"text": "游览", "is_correct": false, "explanation": "游览：指参观风景名胜，与“侵略”没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "写作：指写文章或作品，与“侵略”没有反义关系。"}], "correct_answer": "防御", "explanations": {"防御": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。", "生产": "生产：指制造物品，与“侵略”不构成反义关系。", "游览": "游览：指参观风景名胜，与“侵略”没有反义关系。", "写作": "写作：指写文章或作品，与“侵略”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "侵略是坏人带着兵走进别人的国家，抢别人的地方。", "primary_collocate": null, "pronunciation": "qīn lüè", "ipa": "tɕʰin˥ lɥe˥˩", "syllable_count": 2, "sentences": [{"text": "很多年前，坏人带着兵侵略了我们的国家。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国王想侵略邻居的国家。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的人都怕别的国家来侵略他们的国家。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们带着很多兵，去侵略别人的土地。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了坏国王侵略小国的故事。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为什么要侵略别人的国家？", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家带着兵侵略别人，抢走了他们的土地。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不喜欢侵略别国的行为。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别的国家来侵略我们，我们要保护家人。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家又来侵略我们的边境了，大家很害怕。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵略了", "label": "体标"}, {"form": "侵略过", "label": "体标"}, {"form": "侵略者", "label": "复合"}, {"form": "侵略战争", "label": "复合"}], "register": "书面语", "sense_fingerprint": "侵略：坏人或坏国王带兵进入别人的国家和土地，抢走别人的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：用武力入侵别国，符合“坏人带着兵”的语境。"}, {"text": "保护", "is_correct": false, "explanation": "语义：坏人带兵不会去保护国家，“保护”与“坏人带着兵”矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”是不及物动词，不能带“我们的国家”作宾语。"}, {"text": "建设", "is_correct": false, "explanation": "语义：坏人带兵去建设国家与语境矛盾，建设需要的是建设者而不是士兵。"}], "explanations": {"侵略": "侵略：用武力入侵别国，符合“坏人带着兵”的语境。", "保护": "语义：坏人带兵不会去保护国家，“保护”与“坏人带着兵”矛盾。", "出生": "配价：“出生”是不及物动词，不能带“我们的国家”作宾语。", "建设": "语义：坏人带兵去建设国家与语境矛盾，建设需要的是建设者而不是士兵。"}, "sentence_index": 0, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他侵略了我的隐私。", "explanation": "这里应该用〈侵犯〉。侵略只用于国家之间的武力入侵，隐私、权利要用侵犯。"}, {"text": "那个会计侵略了公司的钱。", "explanation": "这里应该用〈侵占〉。侵占用于钱财、财物，侵略只用于国家和领土。"}, {"text": "大哥总是侵略弟弟。", "explanation": "这里应该用〈欺负〉。侵略指国家间的武力入侵，不用于一般的人际冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：用武力入侵别国、抢占土地，与句中“带着兵”和“抢走了土地”相符。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”的对象是建筑或工程，不能说“建造别人”。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：带兵抢走别人的土地，不会去“感谢”别人，与语境矛盾。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：“诞生”是不及物动词，不能带“别人”作宾语。"}], "explanations": {"侵略": "侵略：用武力入侵别国、抢占土地，与句中“带着兵”和“抢走了土地”相符。", "建造": "搭配：“建造”的对象是建筑或工程，不能说“建造别人”。", "感谢": "语义：带兵抢走别人的土地，不会去“感谢”别人，与语境矛盾。", "诞生": "配价：“诞生”是不及物动词，不能带“别人”作宾语。"}, "sentence_index": 6, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "强盗侵略了那家银行。", "explanation": "这里应该用〈抢劫〉。侵略指国家用武力侵犯别国领土，强盗抢银行要用抢劫。"}, {"text": "邻居经常侵略我们。", "explanation": "这里应该用〈骚扰〉。侵略只用于国家之间，邻居之间的骚扰不说侵略。"}, {"text": "地主经常侵略农民。", "explanation": "这里应该用〈欺压〉。侵略用于国家之间的武力入侵，地主对农民要用欺压。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家历史上侵略了过邻国。", "corrected_sentence": "这个国家历史上侵略过邻国。", "error_description": "体标错误：“了”和“过”不能同时用在动词后面，应说“侵略过”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个国家从没被侵略过别人。", "corrected_sentence": "那个国家从没侵略过别人。", "error_description": "被字句错误：“侵略”后面已经带了宾语“别人”，不能再加“被”。正确的说法是“那个国家从没侵略过别人”，不说“从没被侵略过别人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防御", "is_correct": true, "explanation": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。"}, {"text": "建设", "is_correct": false, "explanation": "建设：指创建、修建，与“侵略”不构成反义关系。"}, {"text": "访问", "is_correct": false, "explanation": "访问：指到某处去看望或了解情况，与“侵略”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指到外地游览，与“侵略”没有反义关系。"}], "correct_answer": "防御", "explanations": {"防御": "防御：抵挡外来的侵犯，与“侵略”意思相反，是反义关系。", "建设": "建设：指创建、修建，与“侵略”不构成反义关系。", "访问": "访问：指到某处去看望或了解情况，与“侵略”没有反义关系。", "旅行": "旅行：指到外地游览，与“侵略”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
