INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用武力侵犯别国的领土和主权。", "primary_collocate": null, "pronunciation": "qīn lüè", "ipa": "tɕʰin˥ lɥe˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家用武力侵略邻国的领土。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合国反对任何国家侵略别国。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "侵略别国的领土是不对的。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写了他们怎么用武力侵略邻国。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的军队侵略了边境上的小城。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队越过边界，开始侵略邻国。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家一起反对侵略别国的行为。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家想用武力侵略我们的土地。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻说那个国家又开始侵略邻国了。", "target_word": "侵略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，用武力侵略别国是错的。", "target_word": "侵略", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵略了", "label": "体标"}, {"form": "侵略过", "label": "体标"}, {"form": "侵略者", "label": "复合"}, {"form": "侵略战争", "label": "复合"}], "register": "书面语", "sense_fingerprint": "侵略：一国用武力侵犯别国的领土和主权，多见于历史、新闻和政治语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：用武力侵犯别国领土，与“用武力”的语境相符。"}, {"text": "交换", "is_correct": false, "explanation": "语义：“用武力”不能用来“交换”领土，两者矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“邻国的领土”作宾语。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”的对象是建筑或工程，不说“建造邻国的领土”。"}], "explanations": {"侵略": "侵略：用武力侵犯别国领土，与“用武力”的语境相符。", "交换": "语义：“用武力”不能用来“交换”领土，两者矛盾。", "游泳": "配价：“游泳”是不及物动词，不能带“邻国的领土”作宾语。", "建造": "搭配：“建造”的对象是建筑或工程，不说“建造邻国的领土”。"}, "sentence_index": 0, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小偷侵略了我家的钱包。", "explanation": "这里应该用〈盗窃〉。侵略指国家用武力侵犯别国领土，小偷偷钱包要用盗窃。"}, {"text": "他总是侵略妹妹的零食。", "explanation": "这里应该用〈抢〉。侵略只用于国家的武力侵犯，抢零食不说侵略。"}, {"text": "他侵略了别人的名誉。", "explanation": "这里应该用〈损害〉。侵略针对的是领土和主权，名誉要用损害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵略", "is_correct": true, "explanation": "侵略：入侵别国，与“反对……的行为”的对象相符。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”与前面的“反对”矛盾，两者不能同时用来描述同一行为。"}, {"text": "举行", "is_correct": false, "explanation": "搭配：“举行”用于仪式、比赛等活动，不说“举行……的行为”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带宾语“别国的行为”。"}], "explanations": {"侵略": "侵略：入侵别国，与“反对……的行为”的对象相符。", "支持": "语义：“支持”与前面的“反对”矛盾，两者不能同时用来描述同一行为。", "举行": "搭配：“举行”用于仪式、比赛等活动，不说“举行……的行为”。", "散步": "配价：“散步”是不及物动词，不能带宾语“别国的行为”。"}, "sentence_index": 6, "correct_answer": "侵略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他侵略了公司的钱。", "explanation": "这里应该用〈侵吞〉。侵略指国家武力入侵，非法占有公司财物要用侵吞。"}, {"text": "同学们在食堂里侵略了别人的位子。", "explanation": "这里应该用〈霸占〉。霸占用于占据别人的位子、房间等，侵略用于国家领土。"}, {"text": "老板侵略了员工的休息时间。", "explanation": "这里应该用〈占用〉。侵略的对象是领土和主权，时间要用占用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用武力的侵略了别国的领土。", "corrected_sentence": "他们用武力侵略了别国的领土。", "error_description": "结构助词错误：“用武力”作状语修饰动词，后面不加“的”。应说“用武力侵略了别国的领土”，不说“用武力的侵略了别国的领土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小国邻国侵略了。", "corrected_sentence": "这个小国被邻国侵略了。", "error_description": "被字句漏字：有施事“邻国”时要用“被”，应说“这个小国被邻国侵略了”，不说“这个小国邻国侵略了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
