INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94603, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合格是达到了要求，可以过关。", "primary_collocate": null, "pronunciation": "hé gé", "ipa": "xɤ˧˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他考试成绩合格了，很高兴。", "target_word": "合格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次体检我全部合格。", "target_word": "合格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的分数要六十分才合格。", "target_word": "合格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她开车考试一次就合格了。", "target_word": "合格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有考试合格，才能拿到证书。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次英语考试，我只差两分就合格了。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑步没有合格，要重新测一次。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的体育测试都合格了。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次面试合格的人可以下周来上班。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的口语测试合格了。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不合格", "label": "否定"}, {"form": "合格率", "label": "复合"}, {"form": "合格证", "label": "复合"}], "register": "中性", "sense_fingerprint": "考试或测试达到要求，可以过关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合格", "is_correct": true, "explanation": "“合格”表示考试达到要求，与“很高兴”相符。"}, {"text": "不及格", "is_correct": false, "explanation": "语义：不及格说明没有过关，与“很高兴”的语气矛盾。"}, {"text": "退步", "is_correct": false, "explanation": "语义：成绩退步不会让人高兴，与句意矛盾。"}, {"text": "失败", "is_correct": false, "explanation": "搭配：“失败”不说“成绩失败”，成绩没过关应说“不及格”。"}], "explanations": {"合格": "“合格”表示考试达到要求，与“很高兴”相符。", "不及格": "语义：不及格说明没有过关，与“很高兴”的语气矛盾。", "退步": "语义：成绩退步不会让人高兴，与句意矛盾。", "失败": "搭配：“失败”不说“成绩失败”，成绩没过关应说“不及格”。"}, "sentence_index": 0, "correct_answer": "合格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个时间合格了，我们下午见面吧。", "explanation": "这里应该用〈合适〉。“合格”指达到规定标准，说时间是否合适应用“合适”，不能说“时间合格”。"}, {"text": "我和同事很合格，一起做完了报告。", "explanation": "这里应该用〈合作〉。“合格”指达到标准，不用来说人与人配合；应说“我和同事合作，一起做完了报告”。"}, {"text": "这场雨终于合格了，我们可以出门了。", "explanation": "这里应该用〈停〉。“合格”指达到标准，不用于说天气；雨停了应说“这场雨终于停了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合格", "is_correct": true, "explanation": "“合格”表示跑步测试达到要求，与“要重新测一次”相符。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“快乐”与跑步测试的结果无关，句子不通。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”不能用来说明跑步测试的结果，与“没有”搭配不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或表现，不用来说明跑步测试的结果。"}], "explanations": {"合格": "“合格”表示跑步测试达到要求，与“要重新测一次”相符。", "快乐": "语义：“快乐”与跑步测试的结果无关，句子不通。", "高兴": "语义：“高兴”不能用来说明跑步测试的结果，与“没有”搭配不通。", "漂亮": "搭配：“漂亮”形容外貌或表现，不用来说明跑步测试的结果。"}, "sentence_index": 6, "correct_answer": "合格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑修好了，我的心情已经合格了。", "explanation": "这里应该用〈高兴〉。“合格”指符合规定的标准，不用于说心情；应说“心情高兴了”。"}, {"text": "这次聚会我们合格了，大家都很热情。", "explanation": "这里应该用〈参加〉。“合格”指达到标准，不能说“合格了一次聚会”；应说“参加了这次聚会”。"}, {"text": "这家餐厅很合格，离我家很远。", "explanation": "这里应该用〈距离〉。“合格”指达到标准，不用于说地点之间的距离；应说“距离我家很远”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次驾照考试他没合格了，要重新考。", "corrected_sentence": "这次驾照考试他没合格，要重新考。", "error_description": "错误在“没合格”后加了“了”。否定已经发生的结果时不加“了”，应说“没合格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把成绩合格了，可以参加下一轮。", "corrected_sentence": "他的成绩合格了，可以参加下一轮。", "error_description": "错误在“的”被换成了“把”。“合格”是形容词，不能带宾语“成绩”，因此不能放进“把”字句去处置“成绩”；应说“他的成绩合格了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
