INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "符合规定的标准。", "primary_collocate": null, "pronunciation": "hé gé", "ipa": "xɤ˧˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这批牛奶检查合格，可以卖了。", "target_word": "合格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种玩具不合格，不能给孩子玩。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的水质检查合格了。", "target_word": "合格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车的刹车不合格，不能上路。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食品合格才能上架。", "target_word": "合格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合格的产品上都有一个小标签。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的苹果都是合格产品。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查员说这些零件全部合格。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的质量合格，我们可以放心住。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产品的尺寸不合格，要重新做。", "target_word": "合格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不合格", "label": "否定"}, {"form": "合格率", "label": "复合"}, {"form": "合格证", "label": "复合"}], "register": "中性", "sense_fingerprint": "产品等符合规定的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合格", "is_correct": true, "explanation": "“合格”表示符合标准，检查合格才可以卖，与“可以卖了”相符。"}, {"text": "不合格", "is_correct": false, "explanation": "语义：检查不合格就不能卖，与“可以卖了”矛盾。"}, {"text": "变质", "is_correct": false, "explanation": "语义：牛奶变质了就不能卖，与“可以卖了”矛盾。"}, {"text": "过期", "is_correct": false, "explanation": "语义：过期的牛奶不能卖，与“可以卖了”矛盾。"}], "explanations": {"合格": "“合格”表示符合标准，检查合格才可以卖，与“可以卖了”相符。", "不合格": "语义：检查不合格就不能卖，与“可以卖了”矛盾。", "变质": "语义：牛奶变质了就不能卖，与“可以卖了”矛盾。", "过期": "语义：过期的牛奶不能卖，与“可以卖了”矛盾。"}, "sentence_index": 0, "correct_answer": "合格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋的尺码很合格，穿着很舒服。", "explanation": "这里应该用〈合适〉。“合格”指符合规定的标准，说鞋的大小是否适合应用“合适”。"}, {"text": "他和同事很合格，一起完成了项目。", "explanation": "这里应该用〈合作〉。“合格”指符合规定的标准，不用来说人与人配合；应说“他和同事合作，一起完成了项目”。"}, {"text": "这个价格很合格，我们都买得起。", "explanation": "这里应该用〈便宜〉。“合格”不用于说价格高低，形容价格低应说“很便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
